@property --apt-fares-p { syntax: '<number>'; inherits: true; initial-value: 0; }
@property --apt-fares-n { syntax: '<integer>'; inherits: true; initial-value: 0; }

.apt-fares {
  /* re-theme with these four */
  --apt-fares-bg: oklch(0.982 0.007 85);
  --apt-fares-ink: oklch(0.23 0.025 55);
  --apt-fares-accent: oklch(0.66 0.19 42);
  --apt-fares-good: oklch(0.58 0.13 162);
  /* derived */
  --apt-fares-surface: color-mix(in oklch, var(--apt-fares-bg) 40%, white);
  --apt-fares-line: color-mix(in oklch, var(--apt-fares-ink) 10%, transparent);
  --apt-fares-line2: color-mix(in oklch, var(--apt-fares-ink) 19%, transparent);
  --apt-fares-mute: color-mix(in oklch, var(--apt-fares-ink) 60%, var(--apt-fares-bg));
  --apt-fares-faint: color-mix(in oklch, var(--apt-fares-ink) 34%, var(--apt-fares-bg));
  --apt-fares-wash: color-mix(in oklch, var(--apt-fares-ink) 3.5%, var(--apt-fares-bg));
  --apt-fares-tint: color-mix(in oklab, var(--apt-fares-accent) 11%, var(--apt-fares-surface));
  --apt-fares-mono: ui-monospace, Menlo, monospace;
  --apt-fares-ease: cubic-bezier(.2, .85, .25, 1);
  --apt-fares-spring: linear(0, .1 4%, .38 10%, .74 17%, .97 24%, 1.06 30%, 1.07 35%, 1.04 42%, 1.01 52%, .996 64%, 1);

  position: relative; width: 100%; height: var(--apt-fares-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apt-fares-bg); color: var(--apt-fares-ink); color-scheme: light; accent-color: var(--apt-fares-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; border-radius: 16px;
  box-shadow: 0 0 0 1px var(--apt-fares-line); -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--apt-fares-accent); outline-offset: 2px; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; }
  & h2, & h3, & h4, & h5, & p, & ol, & ul { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 9.5px/1 var(--apt-fares-mono); padding: 2px 4px; min-width: 15px; display: inline-block; text-align: center; border: 1px solid currentColor; border-bottom-width: 2px; border-radius: 4px; opacity: .55; }
  & .apt-fares-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}

/* ── shell ── */
.apt-fares .apt-fares-app {
  height: 100%; display: grid; grid-template-columns: 262px minmax(0, 1.12fr) minmax(0, 1fr);
  grid-template-rows: minmax(0, 1fr); grid-template-areas: "side dates res";
}
.apt-fares .apt-fares-nav { display: none; }
.apt-fares .apt-fares-side { grid-area: side; display: flex; flex-direction: column; min-height: 0; background: var(--apt-fares-wash); border-right: 1px solid var(--apt-fares-line); }
.apt-fares .apt-fares-sidebody { flex: 1; min-height: 0; overflow-y: auto; padding: 2px 14px 18px; scrollbar-width: thin; display: grid; align-content: start; gap: 14px; }
.apt-fares .apt-fares-dates { grid-area: dates; min-height: 0; overflow-y: auto; scrollbar-width: thin; display: flex; flex-direction: column; gap: 14px; padding: 20px 22px 18px; }
.apt-fares .apt-fares-res { grid-area: res; min-height: 0; display: flex; flex-direction: column; background: var(--apt-fares-surface); border-left: 1px solid var(--apt-fares-line); }
.apt-fares .apt-fares-scrim, .apt-fares .apt-fares-ib.apt-fares-close, .apt-fares .apt-fares-filtbtn { display: none; }

/* ── brand ── */
.apt-fares .apt-fares-brand {
  display: flex; align-items: center; gap: 10px; padding: 16px 14px 12px;
  & p { font-weight: 800; font-size: 15px; letter-spacing: -.02em; line-height: 1.1; flex: 1; }
  & p small { display: block; font-weight: 500; font-size: 11px; letter-spacing: 0; color: var(--apt-fares-mute); }
}
.apt-fares .apt-fares-logo {
  display: grid; place-items: center; width: 30px; height: 30px; border-radius: 9px; background: var(--apt-fares-ink); color: var(--apt-fares-accent);
  & svg { width: 18px; height: 18px; stroke-width: 2.2; }
}
.apt-fares .apt-fares-ib {
  display: grid; place-items: center; width: 30px; height: 30px; border: 0; border-radius: 9px; background: transparent; color: var(--apt-fares-mute);
  transition: background .2s, color .2s;
  &:hover:not(:disabled) { background: var(--apt-fares-line); color: var(--apt-fares-ink); }
  &:disabled { opacity: .35; }
}

/* ── search box ── */
.apt-fares .apt-fares-box { display: grid; gap: 10px; padding: 12px; border-radius: 14px; background: var(--apt-fares-surface); box-shadow: 0 0 0 1px var(--apt-fares-line), 0 8px 20px -14px color-mix(in oklch, var(--apt-fares-ink) 40%, transparent); }
.apt-fares .apt-fares-od { position: relative; display: grid; gap: 2px; }
.apt-fares .apt-fares-field {
  position: relative; display: grid; grid-template-columns: auto 1fr; column-gap: 8px; align-items: baseline; padding: 8px 40px 8px 10px; border-radius: 10px; background: var(--apt-fares-wash);
  & small { grid-column: 1 / -1; font-size: 10px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--apt-fares-faint); }
  & b { font: 750 21px/1.15 system-ui, sans-serif; letter-spacing: -.01em; font-variant-numeric: tabular-nums; }
  & span { color: var(--apt-fares-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: 12px; }
  &.is-pick { padding: 0; background: none; }
  &.is-pick > button {
    width: 100%; display: grid; grid-template-columns: auto 1fr auto; column-gap: 8px; align-items: baseline; text-align: left; padding: 8px 40px 8px 10px; border: 0; border-radius: 10px;
    background: var(--apt-fares-wash); box-shadow: inset 0 0 0 1px transparent; transition: box-shadow .2s, background .2s;
    & svg { align-self: center; color: var(--apt-fares-faint); transition: rotate .3s var(--apt-fares-ease); }
    &:hover { box-shadow: inset 0 0 0 1px var(--apt-fares-line2); background: var(--apt-fares-surface); }
    &[aria-expanded="true"] svg { rotate: 180deg; }
  }
}
.apt-fares .apt-fares-swap {
  position: absolute; right: 8px; top: 50%; translate: 0 -50%; z-index: 2; width: 30px; height: 30px; display: grid; place-items: center; border: 0; border-radius: 50%;
  background: var(--apt-fares-surface); color: var(--apt-fares-ink); box-shadow: 0 0 0 1px var(--apt-fares-line2), 0 3px 8px -3px color-mix(in oklch, var(--apt-fares-ink) 35%, transparent);
  transition: background .2s, color .2s;
  & svg { transition: rotate .6s var(--apt-fares-spring); }
  &:hover { background: var(--apt-fares-ink); color: var(--apt-fares-bg); }
}
.apt-fares[data-swapped] .apt-fares-swap svg { rotate: 180deg; }
.apt-fares .apt-fares-menu {
  position: absolute; left: 0; right: 0; top: calc(100% + 6px); z-index: 30; padding: 5px; border-radius: 12px; background: var(--apt-fares-surface);
  box-shadow: 0 0 0 1px var(--apt-fares-line2), 0 18px 40px -16px color-mix(in oklch, var(--apt-fares-ink) 55%, transparent);
  transform-origin: 50% 0; transition: opacity .18s, scale .28s var(--apt-fares-spring);
  @starting-style { opacity: 0; scale: .96; }
  & li { display: grid; grid-template-columns: 38px 1fr; column-gap: 8px; padding: 7px 9px; border-radius: 8px; cursor: pointer; }
  & li b { font-weight: 750; font-variant-numeric: tabular-nums; }
  & li small { grid-column: 2; font-size: 11px; color: var(--apt-fares-mute); text-transform: none; letter-spacing: 0; font-weight: 500; }
  & li:hover, & li:focus-visible { background: var(--apt-fares-wash); outline: none; }
  & li[aria-selected="true"] { background: var(--apt-fares-tint); }
  & li[aria-selected="true"] b { color: var(--apt-fares-accent); }
}
.apt-fares .apt-fares-dates2 {
  display: grid; grid-template-columns: 1fr 1fr; gap: 6px;
  & div { padding: 7px 10px; border-radius: 10px; box-shadow: inset 0 0 0 1px var(--apt-fares-line); }
  & small { display: block; font-size: 10px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--apt-fares-faint); }
  & b { font-weight: 650; font-variant-numeric: tabular-nums; }
}
.apt-fares .apt-fares-pax { display: grid; gap: 4px; }
.apt-fares .apt-fares-step {
  display: flex; align-items: center; justify-content: space-between; gap: 8px; padding: 2px 0;
  & span { font-weight: 550; }
  & span i { font-style: normal; color: var(--apt-fares-faint); font-size: 11px; margin-left: 2px; }
  & div { display: flex; align-items: center; gap: 4px; }
  & button { width: 26px; height: 26px; display: grid; place-items: center; border: 0; border-radius: 50%; background: var(--apt-fares-wash); box-shadow: inset 0 0 0 1px var(--apt-fares-line2); transition: background .15s, scale .2s var(--apt-fares-spring); }
  & button svg { width: 13px; height: 13px; stroke-width: 2.2; }
  & button:hover:not(:disabled) { background: var(--apt-fares-ink); color: var(--apt-fares-bg); }
  & button:active:not(:disabled) { scale: .9; }
  & button:disabled { opacity: .35; }
  & output { min-width: 18px; text-align: center; font-weight: 700; font-variant-numeric: tabular-nums; }
}
.apt-fares .apt-fares-sel {
  position: relative; display: grid; gap: 2px;
  & small { font-size: 10px; font-weight: 650; letter-spacing: .09em; text-transform: uppercase; color: var(--apt-fares-faint); }
  & select { appearance: none; width: 100%; padding: 7px 30px 7px 10px; border: 0; border-radius: 10px; background: var(--apt-fares-wash); box-shadow: inset 0 0 0 1px var(--apt-fares-line); font-weight: 600; cursor: pointer; }
  & svg { position: absolute; right: 9px; bottom: 9px; color: var(--apt-fares-faint); pointer-events: none; }
}
.apt-fares .apt-fares-switch {
  display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 9px; width: 100%; padding: 8px 10px; text-align: left; border: 0; border-radius: 10px;
  background: var(--apt-fares-wash); transition: background .2s;
  & > svg { color: var(--apt-fares-mute); }
  & span { font-weight: 600; line-height: 1.25; }
  & span small { display: block; font-weight: 450; font-size: 11px; color: var(--apt-fares-mute); }
  & > i { position: relative; width: 30px; height: 18px; border-radius: 99px; background: var(--apt-fares-line2); transition: background .25s; }
  & > i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 14px; height: 14px; border-radius: 50%; background: white; box-shadow: 0 1px 2px color-mix(in oklch, var(--apt-fares-ink) 35%, transparent); transition: translate .35s var(--apt-fares-spring); }
  &[aria-checked="true"] > i { background: var(--apt-fares-accent); }
  &[aria-checked="true"] > i::after { translate: 12px 0; }
  &[aria-checked="true"] > svg { color: var(--apt-fares-accent); }
  &:hover:not(:disabled) { background: color-mix(in oklch, var(--apt-fares-ink) 7%, var(--apt-fares-bg)); }
  &:disabled { opacity: .5; }
  &.is-sm { width: auto; padding: 5px 8px; background: transparent; box-shadow: inset 0 0 0 1px var(--apt-fares-line2); }
}

/* ── filters ── */
.apt-fares .apt-fares-filters {
  display: grid; gap: 14px;
  & > header { display: flex; align-items: baseline; justify-content: space-between; }
  & h4 { font-size: 13px; font-weight: 750; letter-spacing: -.01em; }
}
.apt-fares .apt-fares-link { border: 0; background: none; padding: 0; color: var(--apt-fares-accent); font-weight: 650; font-size: 12px; text-decoration: underline; text-underline-offset: 3px; text-decoration-color: color-mix(in oklch, currentColor 35%, transparent); &:disabled { color: var(--apt-fares-faint); text-decoration: none; } }
.apt-fares .apt-fares-fgroup {
  display: grid; gap: 6px;
  & h5 { display: flex; justify-content: space-between; align-items: baseline; font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--apt-fares-mute); }
  & h5 small, & h5 output { font-weight: 550; letter-spacing: 0; text-transform: none; color: var(--apt-fares-faint); font-size: 11px; font-variant-numeric: tabular-nums; }
  & h5 output { color: var(--apt-fares-ink); font-weight: 700; }
  & input[type="range"] { width: 100%; margin: 2px 0 0; }
}
.apt-fares .apt-fares-radio {
  display: grid; grid-template-columns: 1fr 1fr; padding: 3px; border-radius: 10px; background: var(--apt-fares-line);
  & button { border: 0; border-radius: 8px; padding: 6px 8px; background: transparent; font-weight: 600; color: var(--apt-fares-mute); transition: background .2s, color .2s, box-shadow .2s; }
  & button[aria-checked="true"] { background: var(--apt-fares-surface); color: var(--apt-fares-ink); box-shadow: 0 1px 3px color-mix(in oklch, var(--apt-fares-ink) 18%, transparent); }
}
.apt-fares .apt-fares-check {
  display: grid; grid-template-columns: auto auto 1fr auto; align-items: center; gap: 8px; padding: 4px 4px; border-radius: 8px; cursor: pointer; transition: background .15s;
  &:hover { background: var(--apt-fares-line); }
  & input { margin: 0; width: 15px; height: 15px; }
  & span { font-weight: 550; }
  & small { font-variant-numeric: tabular-nums; color: var(--apt-fares-mute); font-weight: 600; }
  &:has(input:not(:checked)) { & span, & small, & .apt-fares-mark { opacity: .45; } }
}
.apt-fares .apt-fares-mark {
  --c: oklch(0.56 0.13 var(--h)); display: grid; place-items: center; width: 22px; height: 22px; border-radius: 7px;
  background: color-mix(in oklch, var(--c) 14%, var(--apt-fares-surface)); color: var(--c); box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--c) 25%, transparent);
  & svg { width: 15px; height: 15px; stroke-width: 2; }
}
.apt-fares .apt-fares-chips { display: grid; grid-template-columns: repeat(3, 1fr); gap: 5px; }
.apt-fares .apt-fares-chip {
  display: grid; gap: 1px; padding: 6px 7px; text-align: left; border: 0; border-radius: 9px; background: var(--apt-fares-surface); box-shadow: inset 0 0 0 1px var(--apt-fares-line2); transition: box-shadow .2s, background .2s, scale .25s var(--apt-fares-spring);
  & b { font-size: 11.5px; font-weight: 650; }
  & small { font-size: 10px; color: var(--apt-fares-mute); font-variant-numeric: tabular-nums; }
  &[aria-pressed="true"] { background: var(--apt-fares-tint); box-shadow: inset 0 0 0 1.5px var(--apt-fares-accent); }
  &[aria-pressed="false"] { opacity: .7; }
  &:active { scale: .96; }
}
.apt-fares .apt-fares-ticks { display: flex; justify-content: space-between; font-size: 10px; color: var(--apt-fares-faint); font-variant-numeric: tabular-nums; }

/* ── dates pane ── */
.apt-fares .apt-fares-dhead { display: flex; align-items: flex-end; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
.apt-fares .apt-fares-eyebrow { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--apt-fares-mute); font-variant-numeric: tabular-nums; }
.apt-fares .apt-fares-title h2 {
  font-size: clamp(19px, 1.2cqi + 10px, 27px); font-weight: 800; letter-spacing: -.03em; line-height: 1.1; text-wrap: balance;
  & span[aria-hidden] { color: var(--apt-fares-accent); font-weight: 500; }
}
.apt-fares .apt-fares-seg {
  position: relative; display: grid; grid-template-columns: 1fr 1fr; padding: 3px; border-radius: 10px; background: var(--apt-fares-line);
  & button { position: relative; z-index: 1; border: 0; background: none; padding: 5px 12px; font-weight: 650; font-size: 12px; color: var(--apt-fares-mute); transition: color .2s; white-space: nowrap; }
  & button[aria-selected="true"] { color: var(--apt-fares-ink); }
  & > i { position: absolute; left: 3px; top: 3px; bottom: 3px; width: calc(50% - 3px); border-radius: 8px; background: var(--apt-fares-surface); box-shadow: 0 1px 3px color-mix(in oklch, var(--apt-fares-ink) 18%, transparent); transition: translate .45s var(--apt-fares-spring); }
}
.apt-fares[data-tab="cal"] .apt-fares-seg > i { translate: 100% 0; }

/* the matrix: one grid, each row a subgrid so headers and cells share tracks */
.apt-fares .apt-fares-dview { flex: 1 1 auto; min-height: 0; display: flex; flex-direction: column; }
.apt-fares .apt-fares-mwrap { position: relative; flex: 1 1 auto; min-height: 0; display: flex; }
.apt-fares .apt-fares-mx { flex: 1; display: grid; grid-template-columns: 50px repeat(7, minmax(0, 1fr)); grid-template-rows: auto repeat(7, minmax(36px, 1fr)); row-gap: 4px; max-height: 470px; }
.apt-fares .apt-fares-mrow { display: grid; grid-column: 1 / -1; grid-template-columns: subgrid; column-gap: 4px; }
.apt-fares .apt-fares-corner {
  display: grid; align-content: space-between; justify-items: start; padding: 4px 0 6px 4px; font-size: 9px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--apt-fares-faint); line-height: 1.2;
  & small:first-child { justify-self: end; padding-right: 2px; }
}
.apt-fares .apt-fares-ch, .apt-fares .apt-fares-rh {
  display: grid; justify-items: center; align-content: center; line-height: 1.1; color: var(--apt-fares-mute); border-radius: 8px; transition: color .2s, background .2s;
  & small { font-size: 9.5px; font-weight: 600; letter-spacing: .05em; text-transform: uppercase; }
  & b { font-size: 15px; font-weight: 750; color: var(--apt-fares-ink); font-variant-numeric: tabular-nums; }
}
.apt-fares .apt-fares-ch { padding: 4px 0 7px; position: relative; }
.apt-fares .apt-fares-ch[aria-current]::after { content: ""; position: absolute; left: 30%; right: 30%; bottom: 1px; height: 2.5px; border-radius: 2px; background: var(--apt-fares-ink); }
.apt-fares .apt-fares-rh { grid-template-columns: auto auto; column-gap: 4px; justify-content: start; padding-left: 4px; & small:last-child { display: none; } }
.apt-fares .apt-fares-cell {
  --hv: clamp(-1, var(--h), 1);
  position: relative; min-height: 36px; display: grid; place-content: center; gap: 0; border: 0; border-radius: 9px; padding: 0;
  font-variant-numeric: tabular-nums; line-height: 1.1;
  background:
    color-mix(in oklab, var(--apt-fares-good) max(0%, calc(var(--hv) * -30%)),
      color-mix(in oklab, var(--apt-fares-accent) max(0%, calc(var(--hv) * 22%)), var(--apt-fares-surface)));
  box-shadow: inset 0 0 0 1px var(--apt-fares-line);
  transition: background .25s, color .25s, box-shadow .25s, scale .35s var(--apt-fares-spring);
  & b { font-size: clamp(11.5px, .55cqi + 6px, 13.5px); font-weight: 650; }
  & small { font-size: 9.5px; color: var(--apt-fares-mute); font-weight: 550; }
  &.is-low::after { content: ""; position: absolute; top: 5px; right: 5px; width: 6px; height: 6px; border-radius: 50%; background: var(--apt-fares-good); box-shadow: 0 0 0 2px var(--apt-fares-surface); }
  &:hover { box-shadow: inset 0 0 0 1.5px var(--apt-fares-ink); }
  &[aria-selected="true"] { background: var(--apt-fares-ink); color: var(--apt-fares-bg); scale: 1.06; z-index: 1; box-shadow: 0 8px 18px -8px color-mix(in oklch, var(--apt-fares-ink) 70%, transparent); }
  &[aria-selected="true"] small { color: color-mix(in oklch, var(--apt-fares-bg) 70%, transparent); }
  &.is-none { background: repeating-linear-gradient(135deg, transparent 0 5px, var(--apt-fares-line) 5px 6px); color: var(--apt-fares-faint); cursor: not-allowed; }
}
/* crosshair: hovering or focusing a cell lights its row and column headers, via :has() */
.apt-fares .apt-fares-mx {
  &:has([data-c="0"]:is(:hover, :focus-visible)) [data-c="0"], &:has([data-c="1"]:is(:hover, :focus-visible)) [data-c="1"],
  &:has([data-c="2"]:is(:hover, :focus-visible)) [data-c="2"], &:has([data-c="3"]:is(:hover, :focus-visible)) [data-c="3"],
  &:has([data-c="4"]:is(:hover, :focus-visible)) [data-c="4"], &:has([data-c="5"]:is(:hover, :focus-visible)) [data-c="5"],
  &:has([data-c="6"]:is(:hover, :focus-visible)) [data-c="6"],
  &:has([data-r="0"]:is(:hover, :focus-visible)) [data-r="0"], &:has([data-r="1"]:is(:hover, :focus-visible)) [data-r="1"],
  &:has([data-r="2"]:is(:hover, :focus-visible)) [data-r="2"], &:has([data-r="3"]:is(:hover, :focus-visible)) [data-r="3"],
  &:has([data-r="4"]:is(:hover, :focus-visible)) [data-r="4"], &:has([data-r="5"]:is(:hover, :focus-visible)) [data-r="5"],
  &:has([data-r="6"]:is(:hover, :focus-visible)) [data-r="6"] {
    &.apt-fares-ch, &.apt-fares-rh { background: var(--apt-fares-ink); color: var(--apt-fares-bg); & b { color: var(--apt-fares-bg); } }
    &.apt-fares-cell:not([aria-selected="true"]) { box-shadow: inset 0 0 0 1px var(--apt-fares-line2); }
  }
}
.apt-fares .apt-fares-dview.is-enter .apt-fares-cell, .apt-fares .apt-fares-dview.is-enter .apt-fares-day { animation: apt-fares-pop .5s var(--apt-fares-ease) both; animation-delay: calc(var(--i, 0) * 22ms); }
@keyframes apt-fares-pop { from { opacity: 0; translate: 0 6px; filter: blur(3px); } }
.apt-fares .apt-fares-mfoot { display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap; margin-top: 10px; font-size: 11px; color: var(--apt-fares-mute); }
.apt-fares .apt-fares-legend {
  display: inline-flex; align-items: center; gap: 4px;
  & i { width: 14px; height: 10px; border-radius: 3px; box-shadow: inset 0 0 0 1px var(--apt-fares-line); }
  & i.is-lo { background: color-mix(in oklab, var(--apt-fares-good) 30%, var(--apt-fares-surface)); }
  & i.is-mid { background: var(--apt-fares-surface); margin-left: 4px; }
  & i.is-hi { background: color-mix(in oklab, var(--apt-fares-accent) 22%, var(--apt-fares-surface)); margin-right: 4px; }
}
.apt-fares .apt-fares-keys { display: inline-flex; align-items: center; gap: 3px; }

/* month view */
.apt-fares .apt-fares-cal {
  display: grid; gap: 8px;
  & > header { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 6px; }
  & h4 { text-align: center; font-size: 14px; font-weight: 750; letter-spacing: -.01em; }
}
.apt-fares .apt-fares-lens {
  grid-column: 1 / -1; display: flex; gap: 4px; justify-content: center; flex-wrap: wrap;
  & button { border: 0; border-radius: 99px; padding: 4px 10px; font-size: 11.5px; font-weight: 650; background: var(--apt-fares-line); color: var(--apt-fares-mute); transition: background .2s, color .2s; }
  & button[aria-checked="true"] { background: var(--apt-fares-ink); color: var(--apt-fares-bg); }
}
.apt-fares .apt-fares-bars {
  display: flex; align-items: flex-end; gap: 2px; height: 38px; padding: 0 2px;
  & i { flex: 1; height: calc(18% + var(--v, 0) * 82%); border-radius: 2px 2px 0 0; background: color-mix(in oklch, var(--apt-fares-ink) calc(14% + var(--v, 0) * 30%), transparent); transform-origin: bottom; animation: apt-fares-grow .6s var(--apt-fares-ease) both; }
  & i.is-off { height: 3px; background: var(--apt-fares-line); }
