@keyframes apt-fares-grow { from { scale: 1 0; } }
.apt-fares .apt-fares-dow { display: grid; grid-template-columns: repeat(7, 1fr); gap: 4px; font-size: 10px; font-weight: 650; letter-spacing: .06em; text-transform: uppercase; color: var(--apt-fares-faint); text-align: center; }
.apt-fares .apt-fares-days { display: grid; grid-template-columns: repeat(7, 1fr); gap: 4px; }
.apt-fares .apt-fares-day {
  position: relative; display: grid; align-content: center; justify-items: center; height: clamp(40px, 4cqi, 48px); padding: 0; border: 0; border-radius: 9px; background: var(--apt-fares-surface); box-shadow: inset 0 0 0 1px var(--apt-fares-line); line-height: 1.15; font-variant-numeric: tabular-nums;
  transition: background .2s, box-shadow .2s, scale .3s var(--apt-fares-spring);
  & b { font-size: 12.5px; font-weight: 700; }
  & small { font-size: 10px; font-weight: 600; color: var(--apt-fares-mute); }
  &.is-lo small { color: var(--apt-fares-good); }
  &.is-hi small { color: color-mix(in oklch, var(--apt-fares-accent) 85%, var(--apt-fares-ink)); }
  &.is-lo { background: color-mix(in oklab, var(--apt-fares-good) 10%, var(--apt-fares-surface)); }
  &.is-low::after { content: ""; position: absolute; top: 5px; right: 5px; width: 6px; height: 6px; border-radius: 50%; background: var(--apt-fares-good); }
  &.is-off { background: none; box-shadow: none; color: var(--apt-fares-faint); }
