}

/* insight */
.apt-fares .apt-fares-ins {
  --vc: var(--apt-fares-ink);
  flex: none; display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 10px 14px; padding: 12px 14px; border-radius: 14px; background: var(--apt-fares-surface); box-shadow: inset 0 0 0 1px var(--apt-fares-line);
  &[data-v="low"] { --vc: var(--apt-fares-good); }
  &[data-v="high"] { --vc: var(--apt-fares-accent); }
  & .apt-fares-insp { grid-column: 1; text-wrap: pretty; color: var(--apt-fares-mute); }
  & .apt-fares-insp b { color: var(--vc); font-weight: 750; }
