}
.apt-fares .apt-fares-range {
  grid-column: 1 / -1; position: relative; height: 26px;
  &::before { content: ""; position: absolute; left: 0; right: 0; top: 6px; height: 4px; border-radius: 4px; background: var(--apt-fares-line); }
  & .apt-fares-band { position: absolute; top: 6px; height: 4px; border-radius: 4px; left: calc(var(--a) * 100%); width: calc((var(--b) - var(--a)) * 100%); background: var(--apt-fares-faint); transition: left .5s var(--apt-fares-ease), width .5s var(--apt-fares-ease); }
  & .apt-fares-mk { position: absolute; left: 0; top: 0; width: 100%; height: 16px; transform: translateX(calc(var(--apt-fares-p) * 100%)); transition: --apt-fares-p .7s var(--apt-fares-spring); pointer-events: none; }
  & .apt-fares-mk i { position: absolute; left: -7px; top: 1px; width: 14px; height: 14px; border-radius: 50%; background: var(--apt-fares-surface); box-shadow: 0 0 0 3.5px var(--vc), 0 2px 6px color-mix(in oklch, var(--apt-fares-ink) 30%, transparent); }
  & small { position: absolute; bottom: 0; font-size: 10px; color: var(--apt-fares-faint); font-variant-numeric: tabular-nums; }
  & small:last-of-type { right: 0; }
