/* ── results ── */
.apt-fares .apt-fares-rhead {
  position: relative; display: grid; grid-template-columns: 1fr auto; align-items: center; gap: 10px; padding: 18px 16px 12px; border-bottom: 1px solid var(--apt-fares-line);
  & h3 { font-size: 17px; font-weight: 800; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & p { font-size: 11.5px; color: var(--apt-fares-mute); font-variant-numeric: tabular-nums; }
}
.apt-fares .apt-fares-sort {
  grid-column: 1 / -1; position: relative; display: grid; grid-template-columns: repeat(3, 1fr); padding: 3px; border-radius: 10px; background: var(--apt-fares-line);
  & button { position: relative; z-index: 1; display: inline-flex; align-items: center; justify-content: center; gap: 6px; border: 0; background: none; padding: 5px 6px; font-weight: 650; font-size: 12px; color: var(--apt-fares-mute); transition: color .2s; }
  & button[aria-checked="true"] { color: var(--apt-fares-ink); }
  & > i { position: absolute; left: 3px; top: 3px; bottom: 3px; width: calc((100% - 6px) / 3); border-radius: 8px; background: var(--apt-fares-surface); box-shadow: 0 1px 3px color-mix(in oklch, var(--apt-fares-ink) 18%, transparent); translate: calc(var(--x) * 100%) 0; transition: translate .45s var(--apt-fares-spring); }
}
.apt-fares .apt-fares-prog {
  position: absolute; left: 0; right: 0; bottom: -1px; height: 2px; overflow: hidden; opacity: 0; transition: opacity .2s;
  & i { position: absolute; inset: 0; width: 40%; background: var(--apt-fares-accent); animation: apt-fares-indet 1s cubic-bezier(.6, .1, .3, .9) infinite; }
}
.apt-fares[data-loading] .apt-fares-prog { opacity: 1; }
@keyframes apt-fares-indet { from { translate: -100% 0; } to { translate: 260% 0; } }
.apt-fares .apt-fares-list { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; padding: 8px 10px 12px; display: grid; align-content: start; gap: 6px; }
.apt-fares .apt-fares-item {
  border-radius: 13px; background: var(--apt-fares-surface); box-shadow: inset 0 0 0 1px var(--apt-fares-line); transition: box-shadow .25s, background .25s;
  &.is-new { transition: opacity .4s var(--apt-fares-ease), translate .5s var(--apt-fares-ease), box-shadow .25s; transition-delay: calc(var(--i) * 40ms), calc(var(--i) * 40ms), 0s; @starting-style { opacity: 0; translate: 0 10px; } }
  &:hover { box-shadow: inset 0 0 0 1px var(--apt-fares-line2), 0 6px 16px -12px color-mix(in oklch, var(--apt-fares-ink) 45%, transparent); }
  &.is-open { box-shadow: inset 0 0 0 1.5px var(--apt-fares-ink); }
  &.is-picked { box-shadow: inset 0 0 0 2px var(--apt-fares-accent); background: color-mix(in oklch, var(--apt-fares-accent) 4%, var(--apt-fares-surface)); }
}
.apt-fares .apt-fares-row {
  width: 100%; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 10px; align-items: start; padding: 10px 12px; border: 0; background: none; text-align: left; border-radius: 13px;
  & > .apt-fares-mark { width: 30px; height: 30px; border-radius: 9px; margin-top: 1px; & svg { width: 18px; height: 18px; } }
}
.apt-fares .apt-fares-legs { display: grid; gap: 3px; min-width: 0; }
.apt-fares .apt-fares-leg {
  display: grid; grid-template-columns: auto minmax(30px, 1fr) auto 54px; align-items: center; gap: 7px; font-variant-numeric: tabular-nums;
  & > b { font-size: 13.5px; font-weight: 700; letter-spacing: -.01em; }
  & sup { font-size: 9px; color: var(--apt-fares-accent); margin-left: 1px; }
  & em { font-style: normal; font-size: 11px; color: var(--apt-fares-mute); text-align: right; }
}
.apt-fares .apt-fares-line {
  position: relative; height: 16px; display: grid; place-items: center;
  &::before { content: ""; position: absolute; left: 0; right: 0; top: 50%; height: 1.5px; background: var(--apt-fares-line2); border-radius: 2px; }
  &::after { content: ""; position: absolute; right: -1px; top: calc(50% - 2.5px); width: 5px; height: 5px; border-radius: 50%; background: var(--apt-fares-faint); }
  & small { position: relative; z-index: 1; padding: 0 5px; font-size: 9.5px; font-weight: 600; color: var(--apt-fares-mute); background: inherit; line-height: 1; white-space: nowrap; translate: 0 -8px; }
}
.apt-fares .apt-fares-stop { position: absolute; left: 50%; top: calc(50% - 4px); translate: -50% 0; width: 8px; height: 8px; border-radius: 50%; background: var(--apt-fares-surface); box-shadow: inset 0 0 0 2px var(--apt-fares-accent); z-index: 1; }
.apt-fares .apt-fares-al {
  display: flex; flex-wrap: wrap; align-items: center; gap: 4px 6px; margin-top: 2px; font-size: 11px; color: var(--apt-fares-mute);
  & u { text-decoration: none; color: color-mix(in oklch, var(--apt-fares-accent) 80%, var(--apt-fares-ink)); }
  & em { font-style: normal; font-size: 9.5px; font-weight: 750; letter-spacing: .06em; text-transform: uppercase; padding: 1px 6px; border-radius: 99px; }
  & em.is-best { background: var(--apt-fares-ink); color: var(--apt-fares-bg); }
  & em.is-cheap { background: color-mix(in oklch, var(--apt-fares-good) 16%, transparent); color: var(--apt-fares-good); }
  & em.is-fast { background: color-mix(in oklch, var(--apt-fares-accent) 14%, transparent); color: color-mix(in oklch, var(--apt-fares-accent) 80%, var(--apt-fares-ink)); }
}
.apt-fares .apt-fares-price {
  display: grid; justify-items: end; font-variant-numeric: tabular-nums;
  & b { font-size: 17px; font-weight: 800; letter-spacing: -.02em; }
  & small { font-size: 10.5px; color: var(--apt-fares-mute); white-space: nowrap; }
}
.apt-fares .apt-fares-detail {
  display: grid; grid-template-rows: 0fr; transition: grid-template-rows .4s var(--apt-fares-ease), visibility 0s linear .4s; visibility: hidden;
  & > div { min-height: 0; overflow: hidden; display: grid; gap: 8px; padding: 0 12px 0 52px; }
}
.apt-fares .apt-fares-item.is-open .apt-fares-detail { grid-template-rows: 1fr; visibility: visible; transition: grid-template-rows .45s var(--apt-fares-ease), visibility 0s; & > div { padding-bottom: 12px; } }
.apt-fares .apt-fares-seg2 {
  display: grid; gap: 2px; padding: 8px 10px; border-radius: 10px; background: var(--apt-fares-wash); font-variant-numeric: tabular-nums;
  & > small { font-size: 10px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--apt-fares-faint); }
  & p { display: flex; gap: 5px; align-items: baseline; font-size: 12px; }
  & p em { margin-left: auto; font-style: normal; color: var(--apt-fares-mute); font-size: 11px; }
  & .apt-fares-lay { color: color-mix(in oklch, var(--apt-fares-accent) 80%, var(--apt-fares-ink)); font-size: 11px; align-items: center; padding-left: 10px; & svg { width: 12px; height: 12px; } }
}
.apt-fares .apt-fares-incl {
  display: flex; flex-wrap: wrap; gap: 4px 12px; font-size: 11.5px; color: var(--apt-fares-mute);
  & li { display: inline-flex; align-items: center; gap: 5px; }
  & li svg { width: 13px; height: 13px; color: var(--apt-fares-good); }
  & li.is-x svg { color: var(--apt-fares-accent); }
}
.apt-fares .apt-fares-dact { display: flex; align-items: center; justify-content: space-between; gap: 8px; font-size: 12px; color: var(--apt-fares-mute); font-variant-numeric: tabular-nums; & b { color: var(--apt-fares-ink); } }
.apt-fares .apt-fares-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 7px 14px; border: 0; border-radius: 10px; font-weight: 700; font-size: 12.5px;
  background: var(--apt-fares-surface); box-shadow: inset 0 0 0 1.5px var(--apt-fares-ink); transition: background .2s, color .2s, scale .25s var(--apt-fares-spring); white-space: nowrap;
  &:hover:not(:disabled) { background: var(--apt-fares-ink); color: var(--apt-fares-bg); }
  &:active:not(:disabled) { scale: .96; }
  &.is-solid { background: var(--apt-fares-accent); color: white; box-shadow: none; &:hover:not(:disabled) { background: color-mix(in oklch, var(--apt-fares-accent) 85%, black); } }
  &.is-done { background: var(--apt-fares-accent); color: white; box-shadow: none; }
  &.is-held { background: var(--apt-fares-ink); color: var(--apt-fares-bg); box-shadow: none; font-variant-numeric: tabular-nums; }
  &:disabled { opacity: .4; }
  & svg { width: 14px; height: 14px; stroke-width: 2.2; }
}
.apt-fares .apt-fares-skel {
  display: grid; grid-template-columns: 30px 1fr 60px; gap: 10px; padding: 12px; border-radius: 13px; box-shadow: inset 0 0 0 1px var(--apt-fares-line);
  animation: apt-fares-fade .4s var(--apt-fares-ease) both; animation-delay: calc(var(--i) * 60ms);
  & i { height: 30px; border-radius: 8px; background: linear-gradient(90deg, var(--apt-fares-line) 0 30%, var(--apt-fares-wash) 50%, var(--apt-fares-line) 70%) 0 0 / 300% 100%; animation: apt-fares-shine 1.1s linear infinite; }
  & i:nth-child(2) { height: 38px; }
}
@keyframes apt-fares-shine { to { background-position: -150% 0; } }
@keyframes apt-fares-fade { from { opacity: 0; } }
.apt-fares .apt-fares-empty { display: grid; justify-items: center; gap: 6px; padding: 40px 20px; text-align: center; color: var(--apt-fares-mute); & b { color: var(--apt-fares-ink); font-size: 14px; } & p { text-wrap: pretty; } }
.apt-fares .apt-fares-pick {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto auto; align-items: center; gap: 10px; padding: 12px 14px; border-top: 1px solid var(--apt-fares-line); background: var(--apt-fares-wash);
  & .apt-fares-ph { grid-column: 1 / 4; color: var(--apt-fares-mute); font-size: 12px; text-wrap: pretty; }
  & .apt-fares-mark { width: 28px; height: 28px; }
}
.apt-fares .apt-fares-ps { min-width: 0; line-height: 1.25; & b { display: block; font-weight: 750; } & small { color: var(--apt-fares-mute); font-size: 11px; font-variant-numeric: tabular-nums; } }
.apt-fares .apt-fares-tot {
  display: grid; justify-items: end; line-height: 1.1;
  & small { font-size: 10px; color: var(--apt-fares-mute); }
  & b { counter-reset: apt-fares-n var(--apt-fares-n); font-size: 18px; font-weight: 800; letter-spacing: -.02em; font-variant-numeric: tabular-nums; }
  & b::before { content: "\20ac" counter(apt-fares-n); }
  &.is-count b { transition: --apt-fares-n .9s cubic-bezier(.15, .8, .2, 1); @starting-style { --apt-fares-n: 0; } }
}

/* toast */
.apt-fares .apt-fares-toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50; translate: -50% 20px; opacity: 0; pointer-events: none; max-width: calc(100% - 32px);
  padding: 9px 14px; border-radius: 12px; background: var(--apt-fares-ink); color: var(--apt-fares-bg); font-weight: 600; font-size: 12.5px; box-shadow: 0 14px 30px -12px color-mix(in oklch, var(--apt-fares-ink) 70%, transparent);
  transition: opacity .25s, translate .5s var(--apt-fares-spring);
  &.is-on { opacity: 1; translate: -50% 0; }
}

/* ── medium: filters become a drawer ── */
@container (max-width: 959px) {
  .apt-fares .apt-fares-app { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); grid-template-areas: "dates res"; }
  .apt-fares .apt-fares-side {
    position: absolute; left: 0; top: 0; bottom: 0; width: min(300px, 88cqi); z-index: 40; box-shadow: 0 0 0 1px var(--apt-fares-line), 24px 0 60px -30px color-mix(in oklch, var(--apt-fares-ink) 60%, transparent);
    translate: -104% 0; visibility: hidden; transition: translate .45s var(--apt-fares-ease), visibility 0s linear .45s;
  }
  .apt-fares[data-drawer] .apt-fares-side { translate: 0 0; visibility: visible; transition: translate .5s var(--apt-fares-spring), visibility 0s; }
  .apt-fares .apt-fares-ib.apt-fares-close { display: grid; }
  .apt-fares .apt-fares-filtbtn {
    display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border: 0; border-radius: 9px; background: var(--apt-fares-wash); box-shadow: inset 0 0 0 1px var(--apt-fares-line2); font-weight: 650; font-size: 12px;
    &:hover { background: var(--apt-fares-ink); color: var(--apt-fares-bg); }
  }
  .apt-fares .apt-fares-scrim { position: absolute; inset: 0; z-index: 35; border: 0; background: color-mix(in oklch, var(--apt-fares-ink) 28%, transparent); opacity: 0; transition: opacity .3s; display: block; pointer-events: none; }
  .apt-fares[data-drawer] .apt-fares-scrim { opacity: 1; pointer-events: auto; }
  .apt-fares .apt-fares-dates { padding: 16px; }
  .apt-fares .apt-fares-leg { grid-template-columns: auto minmax(24px, 1fr) auto; & em { display: none; } }
}

/* ── narrow: one pane at a time ── */
@container (max-width: 759px) {
  .apt-fares .apt-fares-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "nav" "main"; }
  .apt-fares .apt-fares-nav {
    grid-area: nav; display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; padding: 8px 10px; border-bottom: 1px solid var(--apt-fares-line); background: var(--apt-fares-wash);
    & button { display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 8px 6px; border: 0; border-radius: 10px; background: none; font-weight: 650; color: var(--apt-fares-mute); }
    & button span { font-variant-numeric: tabular-nums; font-size: 11px; padding: 0 5px; border-radius: 99px; background: var(--apt-fares-line); }
    & button[aria-selected="true"] { background: var(--apt-fares-surface); color: var(--apt-fares-ink); box-shadow: 0 1px 3px color-mix(in oklch, var(--apt-fares-ink) 18%, transparent); }
  }
  .apt-fares .apt-fares-side, .apt-fares .apt-fares-dates, .apt-fares .apt-fares-res { grid-area: main; display: none; position: static; translate: none; visibility: visible; width: auto; box-shadow: none; border: 0; }
  .apt-fares[data-pane="search"] .apt-fares-side { display: flex; }
  .apt-fares[data-pane="dates"] .apt-fares-dates { display: flex; }
  .apt-fares[data-pane="res"] .apt-fares-res { display: flex; }
  .apt-fares .apt-fares-ib.apt-fares-close, .apt-fares .apt-fares-scrim { display: none; }
  .apt-fares .apt-fares-brand { display: none; }
  .apt-fares .apt-fares-sidebody { padding-top: 12px; }
  .apt-fares .apt-fares-mx { grid-template-columns: 38px repeat(7, minmax(0, 1fr)); }
  .apt-fares .apt-fares-mrow { column-gap: 3px; }
  .apt-fares .apt-fares-rh { grid-template-columns: 1fr; justify-items: center; padding: 0; & small:first-child { display: none; } }
  .apt-fares .apt-fares-cell small { display: none; }
  .apt-fares .apt-fares-keys { display: none; }
}
@container (max-width: 440px) {
  .apt-fares .apt-fares-dates { padding: 12px 10px; }
  .apt-fares .apt-fares-cell b { font-size: 10.5px; letter-spacing: -.02em; }
  .apt-fares .apt-fares-ch small, .apt-fares .apt-fares-corner small { display: none; }
  .apt-fares .apt-fares-ins { grid-template-columns: 1fr; & .apt-fares-switch { grid-column: 1; grid-row: auto; justify-self: start; } }
  .apt-fares .apt-fares-pick { grid-template-columns: auto minmax(0, 1fr) auto; & .apt-fares-btn { grid-column: 1 / -1; } }
}

