    else if (e.key === 'Tab') closeMenu();
    return;
  }
  const cell = t.closest && t.closest('.' + P + '-cell');
  if (cell && /^Arrow/.test(e.key)) {
    e.preventDefault();
    let c = +cell.dataset.c, r = +cell.dataset.r;
    if (e.key === 'ArrowLeft') c--; if (e.key === 'ArrowRight') c++; if (e.key === 'ArrowUp') r--; if (e.key === 'ArrowDown') r++;
    if (c < 0 || c > 6 || r < 0 || r > 6) {
      /* walk off the edge: slide the whole window by a day */
      const d = +cell.dataset.d + (c < 0 ? -1 : c > 6 ? 1 : 0), rt = +cell.dataset.rt + (r < 0 ? -1 : r > 6 ? 1 : 0);
      if (d < FIRST || rt > LAST + 6 || rt <= d) return;
      S.cd += c < 0 ? -1 : c > 6 ? 1 : 0; S.cr += r < 0 ? -1 : r > 6 ? 1 : 0;
      keepFocus(() => renderDates(false));
      const n = $('.' + P + '-cell[data-c="' + clamp(c, 0, 6) + '"][data-r="' + clamp(r, 0, 6) + '"]'); if (n) { $$('.' + P + '-cell').forEach(x => x.tabIndex = -1); n.tabIndex = 0; n.focus(); }
      return;
    }
    const n = $('.' + P + '-cell[data-c="' + c + '"][data-r="' + r + '"]');
    if (n) { $$('.' + P + '-cell').forEach(x => x.tabIndex = -1); n.tabIndex = 0; n.focus(); }
    return;
  }
  const group = t.closest && t.closest('[role="radiogroup"], [role="tablist"]');
  if (group && /^Arrow(Left|Right|Up|Down)$/.test(e.key)) {
    const items = $$('[role="radio"], [role="tab"]', group).filter(b => !b.disabled && b.offsetParent);
    const i = items.indexOf(t.closest('[role="radio"], [role="tab"]'));
    if (i > -1) { e.preventDefault(); const n = items[(i + (/Right|Down/.test(e.key) ? 1 : -1) + items.length) % items.length]; n.focus(); n.click(); }
    return;
  }
  if (/INPUT|SELECT|TEXTAREA/.test(t.tagName) && t.type !== 'checkbox' && t.type !== 'range') return;
  if (e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.key === '[' || e.key === ']') { e.preventDefault(); shift(e.key === ']' ? 1 : -1); }
  else if (e.key === 's' || e.key === 'S') { e.preventDefault(); $('[data-act="swap"]').click(); }
  else if (e.key === '1' || e.key === '2' || e.key === '3') { e.preventDefault(); setSort(SORTS[+e.key - 1][0]); }
});

renderAll('enter');

