@property --apt-seats-n { syntax: '<integer>'; inherits: true; initial-value: 0; }

.apt-seats {
  /* re-theme with these four */
  --apt-seats-bg: oklch(0.195 0.009 65);
  --apt-seats-ink: oklch(0.95 0.012 85);
  --apt-seats-accent: oklch(0.83 0.145 80);
  --apt-seats-space: oklch(0.77 0.1 158);
  /* derived */
  --apt-seats-surface: color-mix(in oklab, var(--apt-seats-ink) 6%, var(--apt-seats-bg));
  --apt-seats-raised: color-mix(in oklab, var(--apt-seats-ink) 10%, var(--apt-seats-bg));
  --apt-seats-line: color-mix(in oklab, var(--apt-seats-ink) 11%, transparent);
  --apt-seats-line2: color-mix(in oklab, var(--apt-seats-ink) 20%, transparent);
  --apt-seats-mute: color-mix(in oklab, var(--apt-seats-ink) 62%, var(--apt-seats-bg));
  --apt-seats-faint: color-mix(in oklab, var(--apt-seats-ink) 38%, var(--apt-seats-bg));
  --apt-seats-front: oklch(0.8 0.045 70);
  --apt-seats-std: color-mix(in oklab, var(--apt-seats-ink) 34%, var(--apt-seats-bg));
  --apt-seats-ines: var(--apt-seats-accent);
  --apt-seats-rui: oklch(0.74 0.15 32);
  --apt-seats-lia: oklch(0.8 0.09 225);
  --apt-seats-mono: ui-monospace, Menlo, monospace;
  --apt-seats-ease: cubic-bezier(.2, .85, .25, 1);
  --apt-seats-spring: linear(0, .1 4%, .38 10%, .74 17%, .97 24%, 1.06 30%, 1.07 35%, 1.04 42%, 1.01 52%, .996 64%, 1);

  position: relative; width: 100%; height: var(--apt-seats-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apt-seats-bg); color: var(--apt-seats-ink); color-scheme: dark; accent-color: var(--apt-seats-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; border-radius: 16px; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--apt-seats-accent); outline-offset: 2px; }
  & button { font: inherit; color: inherit; cursor: pointer; }
  & button:disabled { cursor: not-allowed; }
  & h2, & h3, & p, & dl, & dd, & ul { margin: 0; padding: 0; }
  & ul { list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 9.5px/1 var(--apt-seats-mono); padding: 2px 4px; min-width: 15px; display: inline-block; text-align: center; border: 1px solid currentColor; border-bottom-width: 2px; border-radius: 4px; opacity: .6; }
  & .apt-seats-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & [data-c="ines"] { --pc: var(--apt-seats-ines); }
  & [data-c="rui"] { --pc: var(--apt-seats-rui); }
  & [data-c="lia"] { --pc: var(--apt-seats-lia); }
}

/* ── shell ── */
.apt-seats .apt-seats-app {
  height: 100%; display: grid; grid-template-columns: 268px minmax(0, 1fr) 312px; grid-template-rows: minmax(0, 1fr);
  grid-template-areas: "trav cabin side";
}
.apt-seats .apt-seats-nav { display: none; }
.apt-seats .apt-seats-trav { grid-area: trav; min-height: 0; display: flex; flex-direction: column; gap: 16px; padding: 18px 16px 16px; border-right: 1px solid var(--apt-seats-line); overflow-y: auto; scrollbar-width: none; }
.apt-seats .apt-seats-cabin { grid-area: cabin; min-height: 0; display: flex; flex-direction: column; position: relative; }
.apt-seats .apt-seats-side { grid-area: side; min-height: 0; display: flex; flex-direction: column; gap: 14px; padding: 16px; border-left: 1px solid var(--apt-seats-line); overflow-y: auto; scrollbar-width: none; }
.apt-seats .apt-seats-h {
  display: flex; justify-content: space-between; align-items: center; font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--apt-seats-mute);
  & span { display: inline-flex; gap: 3px; font-weight: 550; letter-spacing: 0; text-transform: none; color: var(--apt-seats-faint); }
}

/* flight header */
.apt-seats .apt-seats-flight {
  display: grid; gap: 4px;
  & h2 { display: flex; align-items: center; gap: 10px; font-size: clamp(26px, 1.4cqi + 12px, 32px); font-weight: 800; letter-spacing: -.02em; line-height: 1.05; font-variant-numeric: tabular-nums; }
  & h2 svg { width: 22px; height: 22px; color: var(--apt-seats-accent); stroke-width: 2; }
}
.apt-seats .apt-seats-eyebrow { display: flex; align-items: center; gap: 7px; font-size: 11px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--apt-seats-mute); }
.apt-seats .apt-seats-logo { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 6px; background: var(--apt-seats-accent); color: var(--apt-seats-bg); & svg { width: 14px; height: 14px; stroke-width: 2.2; } }
.apt-seats .apt-seats-sub { font-size: 12px; color: var(--apt-seats-mute); font-variant-numeric: tabular-nums; text-wrap: pretty; }

/* passengers */
.apt-seats .apt-seats-paxwrap { display: grid; gap: 8px; }
.apt-seats .apt-seats-pax { display: grid; gap: 6px; }
.apt-seats .apt-seats-p {
  position: relative; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 10px; padding: 9px 10px; border: 0; border-radius: 12px; text-align: left;
  background: var(--apt-seats-surface); box-shadow: inset 0 0 0 1px var(--apt-seats-line); transition: background .2s, box-shadow .25s;
  animation: apt-seats-in .45s var(--apt-seats-ease) both; animation-delay: calc(var(--i) * 50ms);
  &:hover { background: var(--apt-seats-raised); }
  &[aria-checked="true"] { background: color-mix(in oklab, var(--pc, var(--apt-seats-accent)) 12%, var(--apt-seats-surface)); box-shadow: inset 0 0 0 1.5px var(--pc, var(--apt-seats-accent)); }
  &:has([data-c="ines"]) { --pc: var(--apt-seats-ines); }
  &:has([data-c="rui"]) { --pc: var(--apt-seats-rui); }
  &:has([data-c="lia"]) { --pc: var(--apt-seats-lia); }
}
@keyframes apt-seats-in { from { opacity: 0; translate: -8px 0; } }
.apt-seats .apt-seats-av { display: grid; place-items: center; width: 30px; height: 30px; border-radius: 50%; background: var(--pc); color: var(--apt-seats-bg); font-weight: 800; font-size: 11px; letter-spacing: .02em; flex: none; }
.apt-seats .apt-seats-pn { min-width: 0; line-height: 1.25; & b { display: block; font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } & small { color: var(--apt-seats-mute); font-size: 11px; } }
.apt-seats .apt-seats-ps { display: grid; justify-items: end; line-height: 1.15; font-variant-numeric: tabular-nums; & b { font-size: 15px; font-weight: 800; } & small { font-size: 10.5px; color: var(--apt-seats-mute); } }

/* summary */
.apt-seats .apt-seats-sum { margin-top: auto; display: grid; gap: 10px; padding: 12px; border-radius: 14px; background: var(--apt-seats-surface); box-shadow: inset 0 0 0 1px var(--apt-seats-line); }
.apt-seats .apt-seats-lines {
  display: grid; gap: 6px;
  & > div { display: flex; justify-content: space-between; align-items: baseline; gap: 8px; }
  & dt { font-weight: 600; } & dt small { display: block; font-weight: 450; font-size: 11px; color: var(--apt-seats-mute); }
  & dd { font-variant-numeric: tabular-nums; font-weight: 650; }
  & .is-due { padding-top: 8px; border-top: 1px dashed var(--apt-seats-line2); align-items: center; }
  & .is-due dt { font-size: 12px; text-transform: uppercase; letter-spacing: .08em; color: var(--apt-seats-mute); }
  & .is-due dd { counter-reset: apt-seats-n var(--apt-seats-n); font-size: 24px; font-weight: 800; letter-spacing: -.02em; transition: --apt-seats-n .8s cubic-bezier(.15, .8, .2, 1); }
  & .is-due dd::before { content: "\20ac" counter(apt-seats-n); }
}
.apt-seats .apt-seats-warn { display: flex; gap: 7px; align-items: flex-start; font-size: 12px; color: var(--apt-seats-rui); text-wrap: pretty; & svg { margin-top: 1px; } }
.apt-seats .apt-seats-note { font-size: 11.5px; color: var(--apt-seats-mute); text-wrap: pretty; }
.apt-seats .apt-seats-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 7px; padding: 9px 14px; border: 0; border-radius: 11px; font-weight: 700;
  background: var(--apt-seats-raised); box-shadow: inset 0 0 0 1px var(--apt-seats-line2); transition: background .2s, scale .25s var(--apt-seats-spring), opacity .2s;
  &:hover:not(:disabled) { background: color-mix(in oklab, var(--apt-seats-ink) 16%, var(--apt-seats-bg)); }
  &:active:not(:disabled) { scale: .97; }
  &.is-solid { background: var(--apt-seats-accent); color: oklch(0.2 0.03 70); box-shadow: none; &:hover:not(:disabled) { background: color-mix(in oklab, var(--apt-seats-accent) 88%, white); } }
  &:disabled { opacity: .45; }
}
.apt-seats .apt-seats-spin { animation: apt-seats-rot .8s linear infinite; }
@keyframes apt-seats-rot { to { rotate: 1turn; } }
.apt-seats .apt-seats-done {
  display: grid; grid-template-columns: auto 1fr; gap: 10px 12px; align-items: center;
  & p { line-height: 1.3; } & p b { display: block; font-size: 14px; } & p small { display: block; font-size: 11.5px; color: var(--apt-seats-mute); font-variant-numeric: tabular-nums; }
  & .apt-seats-btn { grid-column: 1 / -1; }
}
.apt-seats .apt-seats-stamp {
  display: grid; place-items: center; width: 40px; height: 40px; border-radius: 50%; background: var(--apt-seats-space); color: var(--apt-seats-bg);
  animation: apt-seats-stamp .6s var(--apt-seats-spring) both; & svg { width: 22px; height: 22px; stroke-width: 2.6; }
}
@keyframes apt-seats-stamp { from { scale: .3; rotate: -30deg; opacity: 0; } }

/* ── cabin tools ── */
.apt-seats .apt-seats-ctools { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 12px 14px; border-bottom: 1px solid var(--apt-seats-line); flex-wrap: wrap; }
.apt-seats .apt-seats-legend { display: flex; flex-wrap: wrap; gap: 4px; }
.apt-seats .apt-seats-lg {
  display: inline-flex; align-items: center; gap: 6px; padding: 5px 9px; border: 0; border-radius: 99px; font-size: 12px; font-weight: 600; background: transparent; box-shadow: inset 0 0 0 1px var(--apt-seats-line2); transition: opacity .2s, background .2s;
  & i { width: 12px; height: 12px; border-radius: 4px 4px 3px 3px; background: var(--sc); }
  & small { font-size: 11px; color: var(--apt-seats-mute); font-variant-numeric: tabular-nums; }
  &[aria-pressed="false"] { opacity: .45; & i { background: none; box-shadow: inset 0 0 0 1.5px var(--sc); } }
  &:hover { background: var(--apt-seats-surface); }
  &.is-space { --sc: var(--apt-seats-space); } &.is-front { --sc: var(--apt-seats-front); } &.is-standard { --sc: var(--apt-seats-std); }
  &.is-taken { box-shadow: none; color: var(--apt-seats-mute); & i { background: repeating-linear-gradient(135deg, var(--apt-seats-line2) 0 2px, transparent 2px 4px); box-shadow: inset 0 0 0 1px var(--apt-seats-line2); } }
}
.apt-seats .apt-seats-acts { display: flex; gap: 6px; }
.apt-seats .apt-seats-tb {
  display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border: 0; border-radius: 9px; font-weight: 650; font-size: 12px; background: var(--apt-seats-surface); box-shadow: inset 0 0 0 1px var(--apt-seats-line2); transition: background .2s;
  &:hover:not(:disabled) { background: var(--apt-seats-raised); }
  &.is-icon { padding: 6px 8px; }
  &:disabled { opacity: .35; }
  & svg { color: var(--apt-seats-accent); }
}

/* ── the stage: scroller + overview ── */
.apt-seats .apt-seats-stage { position: relative; flex: 1; min-height: 0; display: grid; grid-template-columns: minmax(0, 1fr) 76px; timeline-scope: --apt-seats-cabin; }
.apt-seats .apt-seats-scroll {
  position: relative; min-height: 0; overflow-y: auto; overflow-x: hidden; scrollbar-width: none; scroll-timeline: --apt-seats-cabin block; outline: none;
  background:
    radial-gradient(circle at 50% 0, color-mix(in oklab, var(--apt-seats-accent) 6%, transparent), transparent 60%),
    radial-gradient(color-mix(in oklab, var(--apt-seats-ink) 7%, transparent) 1px, transparent 1.5px) 0 0 / 18px 18px;
  -webkit-mask: linear-gradient(transparent, black 18px, black calc(100% - 24px), transparent); mask: linear-gradient(transparent, black 18px, black calc(100% - 24px), transparent);
}
.apt-seats .apt-seats-plane {
  --rw: clamp(232px, 46cqi, 300px);
  position: relative; isolation: isolate; width: var(--rw); margin: 22px auto 40px; padding: 0 16px 0;
  background: linear-gradient(90deg, color-mix(in oklab, var(--apt-seats-ink) 9%, var(--apt-seats-bg)), color-mix(in oklab, var(--apt-seats-ink) 5%, var(--apt-seats-bg)) 20% 80%, color-mix(in oklab, var(--apt-seats-ink) 9%, var(--apt-seats-bg)));
  border-radius: 50% 50% 46% 46% / 150px 150px 90px 90px; box-shadow: 0 0 0 1px var(--apt-seats-line2), 0 30px 60px -30px black;
}
.apt-seats .apt-seats-nose {
  position: relative; height: 128px; display: flex; justify-content: center; align-items: flex-end; gap: 5px; padding-bottom: 46px;
  & i { width: 16px; height: 10px; border-radius: 3px 3px 2px 2px; background: color-mix(in oklab, var(--apt-seats-ink) 22%, var(--apt-seats-bg)); }
  & i:first-child { rotate: -18deg; translate: 0 -5px; } & i:last-child { rotate: 18deg; translate: 0 -5px; }
}
.apt-seats .apt-seats-zone { font-size: 10px; font-weight: 750; letter-spacing: .14em; text-transform: uppercase; text-align: center; color: var(--apt-seats-faint); padding: 8px 0 4px; }
.apt-seats .apt-seats-letters {
  display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)) 24px repeat(3, minmax(0, 1fr)); gap: 5px; padding: 4px 0; font-size: 10.5px; font-weight: 700; color: var(--apt-seats-mute); text-align: center;
  &.is-biz { grid-template-columns: repeat(2, minmax(0, 1fr)) 24px repeat(2, minmax(0, 1fr)); padding: 0 10px 4px; }
  &.is-sticky { position: sticky; top: 0; z-index: 3; margin: 0 -16px; padding: 6px 16px; background: color-mix(in oklab, var(--apt-seats-ink) 6%, var(--apt-seats-bg)); box-shadow: 0 6px 12px -8px black; border-radius: 0 0 10px 10px; }
}
.apt-seats .apt-seats-grid { display: grid; gap: 5px; }
.apt-seats .apt-seats-row {
  position: relative; display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)) 24px repeat(3, minmax(0, 1fr)); gap: 5px; align-items: center;
  &.is-biz { grid-template-columns: repeat(2, minmax(0, 1fr)) 24px repeat(2, minmax(0, 1fr)); padding: 0 10px 4px; }
  /* cabin windows on both walls */
  &::before, &::after { content: ""; position: absolute; top: 50%; width: 4px; height: 12px; translate: 0 -50%; border-radius: 3px; background: color-mix(in oklab, var(--apt-seats-lia) 30%, var(--apt-seats-bg)); }
  &::before { left: -11px; } &::after { right: -11px; }
  &.is-exit { padding: 10px 0; }
}
.apt-seats .apt-seats-rn { text-align: center; font-size: 10px; font-weight: 650; color: var(--apt-seats-faint); font-variant-numeric: tabular-nums; }
.apt-seats .apt-seats-exit {
  position: absolute; top: 50%; translate: 0 -50%; display: inline-flex; align-items: center; gap: 3px; padding: 2px 5px; border-radius: 5px; font-size: 9px; font-weight: 800; letter-spacing: .08em; text-transform: uppercase;
  background: oklch(0.62 0.19 28); color: white; & svg { width: 10px; height: 10px; stroke-width: 2.4; }
  &.is-l { right: calc(100% + 18px); } &.is-r { left: calc(100% + 18px); }
}
.apt-seats .apt-seats-seat {
  --sc: var(--apt-seats-std);
  position: relative; aspect-ratio: 1 / 1.08; min-height: 0; padding: 0; border: 0; border-radius: 9px 9px 6px 6px; display: grid; place-items: center;
  background: color-mix(in oklab, var(--sc) 26%, var(--apt-seats-bg)); box-shadow: inset 0 0 0 1.5px color-mix(in oklab, var(--sc) 70%, transparent);
  transition: background .2s, box-shadow .2s, opacity .3s, scale .3s var(--apt-seats-spring);
  /* cushion */
  &::after { content: ""; position: absolute; left: 18%; right: 18%; bottom: 4px; height: 3px; border-radius: 3px; background: color-mix(in oklab, var(--sc) 60%, transparent); }
  & i { font-style: normal; font-size: 10px; font-weight: 800; letter-spacing: .01em; color: var(--apt-seats-bg); position: relative; z-index: 1; }
  &.is-space { --sc: var(--apt-seats-space); }
  &.is-front { --sc: var(--apt-seats-front); }
  &.is-biz { --sc: var(--apt-seats-front); aspect-ratio: 1.25 / 1; }
  &:hover:not([aria-disabled="true"]) { background: color-mix(in oklab, var(--sc) 55%, var(--apt-seats-bg)); scale: 1.08; }
  &[aria-disabled="true"] { cursor: not-allowed; background: repeating-linear-gradient(135deg, var(--apt-seats-line) 0 2px, transparent 2px 5px), color-mix(in oklab, var(--apt-seats-ink) 4%, var(--apt-seats-bg)); box-shadow: inset 0 0 0 1px var(--apt-seats-line); &::after { opacity: .3; } }
  &[data-who] { background: var(--pc); box-shadow: 0 0 0 2px color-mix(in oklab, var(--pc) 35%, transparent), 0 6px 14px -6px var(--pc); &::after { background: color-mix(in oklab, var(--apt-seats-bg) 35%, transparent); } }
  &[data-who="ines"] { --pc: var(--apt-seats-ines); } &[data-who="rui"] { --pc: var(--apt-seats-rui); } &[data-who="lia"] { --pc: var(--apt-seats-lia); }
}
.apt-seats .apt-seats-grid[data-hide-space] .apt-seats-seat.is-space:not([data-who]),
.apt-seats .apt-seats-grid[data-hide-front] .apt-seats-seat.is-front:not([data-who]),
.apt-seats .apt-seats-grid[data-hide-standard] .apt-seats-seat:is(.is-standard, .is-tight):not([data-who]) { opacity: .16; }
/* the active traveller's colour previews on hover */
.apt-seats .apt-seats-grid[data-active="ines"] .apt-seats-seat:not([aria-disabled="true"]):not([data-who]):hover { box-shadow: inset 0 0 0 2px var(--apt-seats-ines); }
.apt-seats .apt-seats-grid[data-active="rui"] .apt-seats-seat:not([aria-disabled="true"]):not([data-who]):hover { box-shadow: inset 0 0 0 2px var(--apt-seats-rui); }
