/* ── Halden Air · seat selection with fare rules ─────────────────────────
   The cabin is built once as an ARIA grid of real buttons; assignments only
   patch attributes, so focus, scroll and the scroll-driven overview lens are
   never disturbed. Seat prices are read from the same table the fare-rules
   grid prints, so changing fare family re-prices the map, the hover card and
   the running total together. */
const P = 'apt-seats';
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const eur = n => (n ? '€' + n.toLocaleString('en-IE') : 'Free');
const MAC = /Mac|iP/.test(navigator.platform || navigator.userAgent || '');
const hash = s => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } h ^= h >>> 15; h = Math.imul(h, 2246822507); h ^= h >>> 13; return (h >>> 0) / 4294967296; };

/* ── data ── */
const PAX = [
  { id: 'ines', name: 'Inês Carvalho', short: 'Inês', ini: 'IC', kind: 'adult', paid: 446 },
  { id: 'rui', name: 'Rui Carvalho', short: 'Rui', ini: 'RC', kind: 'adult', paid: 446 },
  { id: 'lia', name: 'Lia Carvalho', short: 'Lia', ini: 'LC', kind: 'child', age: 7, paid: 392 }
];
const FARES = [{ id: 'light', name: 'Light', add: 0 }, { id: 'classic', name: 'Classic', add: 45 }, { id: 'flex', name: 'Flex', add: 110 }];
const FI = id => FARES.findIndex(f => f.id === id);
const TYPES = {
  space: { name: 'Space+', blurb: 'Extra legroom', pitch: 86, price: [48, 34, 0] },
  front: { name: 'Front', blurb: 'Quicker off the plane', pitch: 79, price: [26, 12, 0] },
  standard: { name: 'Standard', blurb: 'Regular seat', pitch: 76, price: [14, 0, 0] },
  tight: { name: 'Standard', blurb: 'Last row, limited recline', pitch: 76, price: [9, 0, 0] }
};
const RULES = [
  ['Personal item', ['yes', 'yes', 'yes']],
  ['Cabin bag 8 kg', ['€25', 'yes', 'yes']],
  ['Checked bag 23 kg', ['€45', 'yes', '2 ×']],
  ['Standard seat', TYPES.standard.price.map(v => v ? '€' + v : 'yes')],
  ['Front seat', TYPES.front.price.map(v => v ? '€' + v : 'yes')],
  ['Space+ seat', TYPES.space.price.map(v => v ? '€' + v : 'yes')],
  ['Date change', ['no', '€70', 'yes']],
  ['Refund', ['no', 'Credit', 'yes']],
  ['Miles earned', ['50%', '100%', '150%']]
];
const LET = ['A', 'B', 'C', 'D', 'E', 'F'];
const ROWS = [];
[1, 2, 3, 4].forEach(n => ROWS.push({ n, biz: true, letters: ['A', 'C', 'D', 'F'] }));
for (let n = 10; n <= 32; n++) if (n !== 13) ROWS.push({ n, biz: false, letters: LET });
const EXIT = 21, WING = [17, 25];
const typeOf = n => n === 10 || n === EXIT ? 'space' : n === 11 || n === 12 || n === 14 ? 'front' : n === 32 ? 'tight' : 'standard';
const FREE = new Set(['10D', '10E', '10F', '19D', '19E', '19F', '27A', '27B', '27C', '11A', '15C', '21A', '21F', '24E', '29D', '30A', '31F', '12E', '16B', '22C']);
const SEAT = {};
ROWS.forEach(r => r.letters.forEach(l => {
  const id = r.n + l, t = r.biz ? 'biz' : typeOf(r.n);
  const p = t === 'space' ? .55 : t === 'front' ? .62 : .6;
  SEAT[id] = { id, row: r.n, l, biz: r.biz, type: t, exit: r.n === EXIT, taken: r.biz ? true : !FREE.has(id) && hash(id + 'hd418') < p };
}));
const posName = l => l === 'A' || l === 'F' ? 'Window' : l === 'C' || l === 'D' ? 'Aisle' : 'Middle';

/* ── state ── */
const S = { fare: 'light', active: 'ines', seats: { ines: null, rui: null, lia: null }, hide: new Set(), peek: null, pane: 'map', confirmed: false, busy: false, focus: '27A' };
const hist = [];
const price = id => { const s = SEAT[id]; return s && !s.biz ? TYPES[s.type].price[FI(S.fare)] : 0; };
const holder = id => PAX.find(p => S.seats[p.id] === id);
const paxById = id => PAX.find(p => p.id === id);
function adjacent(a, b) {
  if (!a || !b || SEAT[a].row !== SEAT[b].row) return false;
  const i = LET.indexOf(SEAT[a].l), j = LET.indexOf(SEAT[b].l);
  return Math.abs(i - j) === 1 && !((i === 2 && j === 3) || (i === 3 && j === 2));
}
function childRule() {
  const c = S.seats.lia, adults = PAX.filter(p => p.kind === 'adult' && S.seats[p.id]);
  if (!c) return null;
  if (!adults.length) return 'Seat an adult next to Lia before confirming.';
  return adults.some(p => adjacent(c, S.seats[p.id])) ? null : 'Lia is 7 — she must sit directly beside an adult, not across the aisle.';
}

/* ── icons ── */
const I = {
  check: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.2 4.2L19 7"/></svg>',
  x: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 7l10 10M17 7 7 17"/></svg>',
  warn: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4.5M12 17.2v.3"/></svg>',
  exit: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M14 4h5v16h-5M10 8l-4 4 4 4M6 12h9"/></svg>',
  plug: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M9 3v5M15 3v5M6.5 8h11v3a5.5 5.5 0 0 1-11 0zM12 16.5V21"/></svg>',
  leg: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 4v9a3 3 0 0 0 3 3h8l3 4"/><path d="M5 9h7"/></svg>',
  win: '<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="6" y="3.5" width="12" height="17" rx="6"/><path d="M9 9.5h6"/></svg>',
  lav: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="8" cy="5" r="1.8"/><circle cx="16" cy="5" r="1.8"/><path d="M8 8v12M5.5 9.5h5L9 15H7zM16 8v12M14 9h4v6h-4z"/></svg>',
  cup: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 9h11v5a5 5 0 0 1-5 5h-1a5 5 0 0 1-5-5zM16 10.5h1.5a2.5 2.5 0 0 1 0 5H16M8 3.5v2.5M11 3.5v2.5M14 3.5v2.5"/></svg>',
  spin: '<svg viewBox="0 0 24 24" aria-hidden="true" class="' + P + '-spin"><path d="M12 3a9 9 0 1 0 9 9"/></svg>'
};
const yn = v => v === 'yes' ? '<span class="is-y">' + I.check + '<span class="' + P + '-sr">Included</span></span>' : v === 'no' ? '<span class="is-n">' + I.x + '<span class="' + P + '-sr">Not available</span></span>' : '<span class="is-t">' + esc(v) + '</span>';

/* ── build the cabin once ── */
function buildPlane() {
  const rowsHTML = ROWS.map((r, ri) => {
    const seats = r.letters.map(l => {
      const s = SEAT[r.n + l];
      return '<button type="button" role="gridcell" class="' + P + '-seat is-' + s.type + '" data-seat="' + s.id + '" data-ri="' + ri + '" data-l="' + l + '" tabindex="-1"' +
        (s.taken ? ' aria-disabled="true" title="' + (s.biz ? 'Business cabin — sold with Business fares' : 'Taken') + '"' : '') + '><i aria-hidden="true"></i></button>';
    });
    const half = r.letters.length / 2;
    const exit = r.n === EXIT ? '<span class="' + P + '-exit is-l" aria-hidden="true">' + I.exit + 'Exit</span><span class="' + P + '-exit is-r" aria-hidden="true">Exit' + I.exit + '</span>' : '';
    return '<div class="' + P + '-row' + (r.biz ? ' is-biz' : '') + (r.n === EXIT ? ' is-exit' : '') + '" role="row" data-row="' + r.n + '">' +
      seats.slice(0, half).join('') + '<span class="' + P + '-rn" role="rowheader">' + r.n + '</span>' + seats.slice(half).join('') + exit + '</div>';
