root.addEventListener('pointerleave', () => { if (S.peek) { S.peek = null; renderPeek(); } });
root.addEventListener('focusin', e => {
  const b = e.target.closest && e.target.closest('.' + P + '-seat');
  if (b && S.peek !== b.dataset.seat) { S.peek = b.dataset.seat; renderPeek(); }
});
root.addEventListener('keydown', e => {
  const t = e.target;
  if (!root.querySelector('[data-modal]').hidden) {
    if (e.key === 'Escape') { e.preventDefault(); $('[data-act="exitno"]').click(); }
    if (e.key === 'Tab') { const f = $$('[data-modal] button'); const i = f.indexOf(t); if (e.shiftKey && i <= 0) { e.preventDefault(); f[f.length - 1].focus(); } else if (!e.shiftKey && i === f.length - 1) { e.preventDefault(); f[0].focus(); } }
    return;
  }
  if ((e.metaKey || e.ctrlKey) && (e.key === 'z' || e.key === 'Z')) { e.preventDefault(); undo(); return; }
  const seat = t.closest && t.closest('.' + P + '-seat');
  if (seat && /^Arrow/.test(e.key)) { e.preventDefault(); moveFocus(seat, e.key); return; }
  if (t.closest && t.closest('[data-pax-list]') && /^Arrow/.test(e.key)) {
    e.preventDefault();
    const i = PAX.findIndex(p => p.id === S.active), n = PAX[(i + (/Down|Right/.test(e.key) ? 1 : -1) + PAX.length) % PAX.length];
    $('[data-pax="' + n.id + '"]').click(); return;
  }
  if (t === $('[data-mini]') && /^(ArrowUp|ArrowDown|PageUp|PageDown|Home|End)$/.test(e.key)) {
    e.preventDefault();
    const sc = $('[data-scroll]'), step = /Page/.test(e.key) ? sc.clientHeight * .9 : 80;
    sc.scrollBy({ top: e.key === 'Home' ? -1e5 : e.key === 'End' ? 1e5 : /Up/.test(e.key) ? -step : step, behavior: RM.matches ? 'auto' : 'smooth' });
    return;
  }
  if (/INPUT|TEXTAREA|SELECT/.test(t.tagName) || e.metaKey || e.ctrlKey || e.altKey) return;
  if (e.key >= '1' && e.key <= '3') { e.preventDefault(); $('[data-pax="' + PAX[+e.key - 1].id + '"]').click(); }
  else if (e.key === 't' || e.key === 'T') { e.preventDefault(); together(); }
});

/* minimap: click or drag to scroll the cabin */
const mini = $('[data-mini]');
let drag = null;
function miniTo(clientY, smooth) {
  const sc = $('[data-scroll]'), svg = $('[data-minisvg]').getBoundingClientRect();
  const f = Math.min(1, Math.max(0, (clientY - svg.top) / svg.height));
  sc.scrollTo({ top: f * sc.scrollHeight - sc.clientHeight / 2, behavior: smooth && !RM.matches ? 'smooth' : 'auto' });
}
mini.addEventListener('pointerdown', e => {
  drag = { id: e.pointerId, moved: false };
  try { mini.setPointerCapture(e.pointerId); } catch (err) { /* synthetic pointer */ }
});
mini.addEventListener('pointermove', e => { if (drag && e.buttons) { drag.moved = true; miniTo(e.clientY, false); } });
mini.addEventListener('pointerup', e => { if (drag && !drag.moved) miniTo(e.clientY, true); drag = null; });
mini.addEventListener('pointercancel', () => { drag = null; });
$('[data-scroll]').addEventListener('scroll', onScroll, { passive: true });

/* ── boot ── */
buildPlane();
renderAll();
const ro = new ResizeObserver(() => { if (!root.isConnected) { ro.disconnect(); return; } placeWings(); buildMini(); });
ro.observe($('[data-scroll]'));
requestAnimationFrame(() => {
  if (!root.isConnected) return;
  placeWings(); buildMini();
  const sc = $('[data-scroll]'), r = $('[data-row="24"]');
  if (r) sc.scrollTop = r.offsetTop - sc.clientHeight * .55;
});

css:
.apt-route {
  /* re-theme with these four */
  --apt-route-bg: oklch(0.975 0.013 88);
  --apt-route-ink: oklch(0.27 0.03 48);
  --apt-route-accent: oklch(0.6 0.19 33);
  --apt-route-water: oklch(0.84 0.05 218);
  /* derived */
  --apt-route-surface: color-mix(in oklab, var(--apt-route-bg) 35%, white);
  --apt-route-land: color-mix(in oklab, var(--apt-route-ink) 4%, var(--apt-route-bg));
  --apt-route-line: color-mix(in oklab, var(--apt-route-ink) 11%, transparent);
  --apt-route-line2: color-mix(in oklab, var(--apt-route-ink) 20%, transparent);
  --apt-route-mute: color-mix(in oklab, var(--apt-route-ink) 60%, var(--apt-route-bg));
  --apt-route-faint: color-mix(in oklab, var(--apt-route-ink) 36%, var(--apt-route-bg));
  --apt-route-green: oklch(0.62 0.11 145);
  --apt-route-teal: oklch(0.55 0.08 200);
  --apt-route-food: oklch(0.7 0.13 72);
  --apt-route-warn: oklch(0.66 0.15 62);
  --apt-route-err: oklch(0.56 0.2 27);
  --apt-route-mono: ui-monospace, Menlo, monospace;
  --apt-route-ease: cubic-bezier(.2, .85, .25, 1);
  --apt-route-spring: linear(0, .1 4%, .38 10%, .74 17%, .97 24%, 1.06 30%, 1.07 35%, 1.04 42%, 1.01 52%, .996 64%, 1);

  position: relative; width: 100%; height: var(--apt-route-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apt-route-bg); color: var(--apt-route-ink); color-scheme: light; accent-color: var(--apt-route-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; border-radius: 16px; box-shadow: 0 0 0 1px var(--apt-route-line); -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--apt-route-accent); outline-offset: 2px; }
  & button { font: inherit; color: inherit; cursor: pointer; }
  & button:disabled { cursor: not-allowed; }
  & h2, & p, & ol, & ul { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 9.5px/1 var(--apt-route-mono); padding: 2px 4px; min-width: 15px; display: inline-block; text-align: center; border: 1px solid currentColor; border-bottom-width: 2px; border-radius: 4px; opacity: .6; }
  & .apt-route-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & [data-cat="accent"] { --cc: var(--apt-route-accent); } & [data-cat="food"] { --cc: var(--apt-route-food); } & [data-cat="green"] { --cc: var(--apt-route-green); }
  & [data-cat="teal"] { --cc: var(--apt-route-teal); } & [data-cat="water"] { --cc: oklch(0.62 0.09 225); } & [data-cat="ink"] { --cc: var(--apt-route-ink); }
}

/* ── shell ── */
.apt-route .apt-route-app { height: 100%; display: grid; grid-template-columns: minmax(360px, 420px) minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); grid-template-areas: "plan map"; }
.apt-route .apt-route-nav { display: none; }
.apt-route .apt-route-plan { grid-area: plan; min-height: 0; display: flex; flex-direction: column; border-right: 1px solid var(--apt-route-line); background: var(--apt-route-bg); }
.apt-route .apt-route-mapwrap { grid-area: map; position: relative; min-height: 0; display: grid; grid-template-rows: auto minmax(0, 1fr) auto; background: var(--apt-route-land); }

/* header */
.apt-route .apt-route-head { display: grid; gap: 4px; padding: 18px 18px 10px; }
.apt-route .apt-route-eyebrow { display: flex; align-items: center; gap: 6px; font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--apt-route-accent); & svg { width: 13px; height: 13px; stroke-width: 2.2; } }
.apt-route .apt-route-head h2 { font: 700 clamp(20px, 1.1cqi + 9px, 25px)/1.1 ui-serif, "Iowan Old Style", "Palatino Linotype", Georgia, serif; letter-spacing: -.015em; text-wrap: balance; }
.apt-route .apt-route-days {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; margin-top: 10px; padding: 3px; border-radius: 12px; background: var(--apt-route-line);
  & button { display: grid; gap: 0; padding: 6px 8px; border: 0; border-radius: 9px; background: none; text-align: left; transition: background .2s, box-shadow .2s; line-height: 1.2; }
  & b { font-weight: 750; font-size: 13px; } & small { font-size: 10.5px; color: var(--apt-route-mute); font-variant-numeric: tabular-nums; } & small i { font-style: normal; color: var(--apt-route-err); font-weight: 650; }
  & button[aria-selected="true"] { background: var(--apt-route-surface); box-shadow: 0 1px 3px color-mix(in oklab, var(--apt-route-ink) 18%, transparent); }
  & button:hover:not([aria-selected="true"]) { background: color-mix(in oklab, var(--apt-route-surface) 50%, transparent); }
}
.apt-route .apt-route-tools { display: flex; gap: 6px; padding: 0 18px 10px; }
.apt-route .apt-route-tb {
  display: inline-flex; align-items: center; gap: 6px; padding: 6px 11px; border: 0; border-radius: 9px; font-weight: 650; font-size: 12px; background: var(--apt-route-surface); box-shadow: inset 0 0 0 1px var(--apt-route-line2); transition: background .2s, color .2s;
  &:first-child { margin-right: auto; background: var(--apt-route-ink); color: var(--apt-route-bg); box-shadow: none; }
  &:first-child:hover { background: var(--apt-route-accent); }
  &.is-icon { padding: 6px 8px; } &:disabled { opacity: .35; }
  &:hover:not(:disabled):not(:first-child) { background: var(--apt-route-bg); }
}

/* the timeline list: a rail at the left with legs on it */
.apt-route .apt-route-scroll { position: relative; flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; padding: 4px 16px 18px 12px; overscroll-behavior: contain; }
.apt-route .apt-route-scroll::before { content: ""; position: absolute; left: 32px; top: 28px; bottom: 44px; width: 2px; background: repeating-linear-gradient(var(--apt-route-line2) 0 4px, transparent 4px 8px); }
.apt-route .apt-route-start, .apt-route .apt-route-end { position: relative; }
.apt-route .apt-route-start {
  display: grid; grid-template-columns: 42px minmax(0, 1fr) auto; align-items: center; gap: 0 10px; padding: 6px 0 2px;
  & .apt-route-st b { display: block; font-weight: 700; } & .apt-route-st small { color: var(--apt-route-mute); font-size: 11px; }
}
.apt-route .apt-route-home { position: relative; z-index: 1; justify-self: center; display: grid; place-items: center; width: 32px; height: 32px; border-radius: 10px; background: var(--apt-route-ink); color: var(--apt-route-bg); & svg { width: 17px; height: 17px; } }
.apt-route .apt-route-leave { display: grid; justify-items: end; gap: 2px; & > small { font-size: 10px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--apt-route-faint); } }
.apt-route .apt-route-stepper {
  display: inline-flex; align-items: center; gap: 2px; padding: 2px; border-radius: 9px; background: var(--apt-route-surface); box-shadow: inset 0 0 0 1px var(--apt-route-line2);
  & button { display: grid; place-items: center; width: 24px; height: 24px; border: 0; border-radius: 7px; background: none; } & button:hover:not(:disabled) { background: var(--apt-route-line); } & button:disabled { opacity: .3; }
  & svg { width: 13px; height: 13px; stroke-width: 2.2; }
  & output { min-width: 44px; text-align: center; font-weight: 750; font-variant-numeric: tabular-nums; }
}
.apt-route .apt-route-list { display: grid; gap: 0; }
.apt-route .apt-route-item {
  position: relative; display: grid; gap: 4px; padding-bottom: 6px; transition: translate .28s var(--apt-route-ease), opacity .2s;
  &.is-new { animation: apt-route-in .5s var(--apt-route-ease) both; animation-delay: calc(var(--i) * 45ms); }
  &.is-drag { z-index: 5; transition: none; & .apt-route-card { box-shadow: 0 0 0 1.5px var(--apt-route-ink), 0 18px 40px -16px color-mix(in oklab, var(--apt-route-ink) 60%, transparent); scale: 1.02; rotate: -.6deg; } }
}
@keyframes apt-route-in { from { opacity: 0; translate: 0 10px; } }
.apt-route .apt-route-list.is-dragging .apt-route-leg, .apt-route .apt-route-list.is-dragging .apt-route-wait { opacity: .25; }
.apt-route .apt-route-leg {
  position: relative; display: grid; grid-template-columns: 42px auto 1fr; align-items: center; column-gap: 8px; padding: 4px 6px 4px 0; border: 0; border-radius: 10px; background: none; text-align: left; font-size: 11.5px; color: var(--apt-route-mute); transition: background .2s, opacity .2s;
  & > svg { justify-self: center; position: relative; z-index: 1; width: 26px; height: 26px; padding: 5px; border-radius: 50%; background: var(--apt-route-bg); box-shadow: inset 0 0 0 1.5px var(--apt-route-line2); color: var(--apt-route-ink); stroke-width: 1.7; }
  & b { font-weight: 750; color: var(--apt-route-ink); font-variant-numeric: tabular-nums; }
  & span { font-variant-numeric: tabular-nums; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  &.is-tram > svg { background: var(--apt-route-accent); color: white; box-shadow: none; }
  &.is-taxi > svg { background: var(--apt-route-ink); color: var(--apt-route-bg); box-shadow: none; }
  &:hover { background: var(--apt-route-line); }
}
.apt-route .apt-route-wait { display: flex; align-items: center; gap: 6px; margin-left: 50px; font-size: 11px; color: var(--apt-route-mute); font-style: italic; & svg { width: 13px; height: 13px; } }
.apt-route .apt-route-card {
  position: relative; display: grid; grid-template-columns: 22px 30px minmax(0, 1fr) auto; align-items: start; gap: 4px 8px; margin-left: 4px; padding: 10px 8px 10px 4px; border-radius: 14px;
  background: var(--apt-route-surface); box-shadow: 0 0 0 1px var(--apt-route-line), 0 4px 12px -10px color-mix(in oklab, var(--apt-route-ink) 50%, transparent);
  transition: box-shadow .25s, scale .25s var(--apt-route-spring), rotate .25s;
  &::before { content: ""; position: absolute; left: 0; top: 12px; bottom: 12px; width: 3px; border-radius: 0 3px 3px 0; background: var(--cc); }
  & > .apt-route-iss { grid-column: 3 / -1; }
}
.apt-route .apt-route-item.is-hover .apt-route-card { box-shadow: 0 0 0 1px var(--apt-route-line2), 0 8px 20px -12px color-mix(in oklab, var(--apt-route-ink) 50%, transparent); }
.apt-route .apt-route-item.is-sel .apt-route-card { box-shadow: 0 0 0 2px var(--apt-route-ink); }
.apt-route .apt-route-item.is-moving .apt-route-card { box-shadow: 0 0 0 2px var(--apt-route-accent), 0 10px 30px -14px var(--apt-route-accent); }
.apt-route .apt-route-grip {
  align-self: center; display: grid; place-items: center; width: 22px; height: 34px; padding: 0; border: 0; border-radius: 7px; background: none; color: var(--apt-route-faint); cursor: grab; touch-action: none;
  &:hover, &[aria-pressed="true"] { color: var(--apt-route-ink); background: var(--apt-route-line); }
  &[aria-pressed="true"] { color: var(--apt-route-accent); }
}
.apt-route .apt-route-num { align-self: center; display: grid; place-items: center; width: 28px; height: 28px; border-radius: 50%; background: var(--apt-route-ink); color: var(--apt-route-bg); font-weight: 800; font-size: 12.5px; font-variant-numeric: tabular-nums; }
.apt-route .apt-route-item.is-sel .apt-route-num { background: var(--apt-route-accent); }
.apt-route .apt-route-main {
  display: grid; gap: 1px; min-width: 0; padding: 0; border: 0; background: none; text-align: left;
  & b { font-weight: 700; font-size: 13.5px; letter-spacing: -.005em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & small { font-size: 11px; color: var(--apt-route-mute); text-wrap: pretty; }
}
.apt-route .apt-route-time { font-size: 11.5px; color: var(--apt-route-mute); font-variant-numeric: tabular-nums; & time { font-weight: 700; color: var(--apt-route-ink); } }
.apt-route .apt-route-rm {
  display: grid; place-items: center; width: 26px; height: 26px; border: 0; border-radius: 8px; background: none; color: var(--apt-route-faint); opacity: 0; transition: opacity .2s, background .2s, color .2s;
  &:hover { background: color-mix(in oklab, var(--apt-route-err) 12%, transparent); color: var(--apt-route-err); }
}
.apt-route .apt-route-card:is(:hover, :focus-within) .apt-route-rm { opacity: 1; }
.apt-route .apt-route-iss {
  display: flex; align-items: flex-start; gap: 6px; font-size: 11.5px; font-weight: 600; text-wrap: pretty;
  & svg { width: 14px; height: 14px; margin-top: 1px; }
  &.is-warn { color: color-mix(in oklab, var(--apt-route-warn) 75%, var(--apt-route-ink)); } &.is-err { color: var(--apt-route-err); }
}
.apt-route .apt-route-item.is-err .apt-route-card { background: color-mix(in oklab, var(--apt-route-err) 5%, var(--apt-route-surface)); }
.apt-route .apt-route-back { display: flex; align-items: center; gap: 8px; margin: 2px 0 0 4px; font-size: 12px; color: var(--apt-route-mute); & svg { width: 32px; height: 32px; padding: 7px; border-radius: 10px; background: var(--apt-route-ink); color: var(--apt-route-bg); position: relative; z-index: 1; margin-left: 1px; } & b { color: var(--apt-route-ink); font-variant-numeric: tabular-nums; } }
.apt-route .apt-route-add { position: relative; z-index: 1; margin: 14px 0 0 0; padding-left: 4px; display: grid; gap: 6px; }
.apt-route .apt-route-addbtn {
  justify-self: start; display: inline-flex; align-items: center; gap: 6px; padding: 7px 12px; border: 0; border-radius: 10px; background: var(--apt-route-surface); box-shadow: inset 0 0 0 1px var(--apt-route-line2); font-weight: 650; font-size: 12px;
  & small { padding: 0 6px; border-radius: 99px; background: var(--apt-route-line); font-variant-numeric: tabular-nums; }
  &[aria-expanded="true"] { background: var(--apt-route-ink); color: var(--apt-route-bg); & small { background: color-mix(in oklab, var(--apt-route-bg) 25%, transparent); } }
}
.apt-route .apt-route-saved {
  display: grid; gap: 4px;
  & li { animation: apt-route-in .4s var(--apt-route-ease) both; animation-delay: calc(var(--i) * 40ms); }
  & button { width: 100%; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; align-items: center; gap: 0 10px; padding: 8px 10px; border: 0; border-radius: 11px; text-align: left; background: var(--apt-route-surface); box-shadow: inset 0 0 0 1px var(--apt-route-line); }
  & button:hover { box-shadow: inset 0 0 0 1.5px var(--apt-route-ink); }
  & b { font-weight: 650; } & small { grid-column: 2; font-size: 11px; color: var(--apt-route-mute); }
  & button > svg { grid-row: 1 / 3; grid-column: 3; color: var(--apt-route-accent); }
}
.apt-route .apt-route-dot { grid-row: 1 / 3; width: 10px; height: 10px; border-radius: 50%; background: var(--cc); }
.apt-route .apt-route-none { padding: 8px 10px; color: var(--apt-route-mute); font-size: 12px; }
.apt-route .apt-route-keys { display: flex; flex-wrap: wrap; align-items: center; gap: 3px; padding: 8px 18px 10px; border-top: 1px solid var(--apt-route-line); font-size: 11px; color: var(--apt-route-faint); }
.apt-route .apt-route-gripi { display: inline-block; width: 8px; height: 12px; margin: 0 1px; background: radial-gradient(circle, currentColor 1.2px, transparent 1.6px) 0 0 / 4px 4px; }

/* ── map pane ── */
.apt-route .apt-route-sum {
  display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 1px; margin: 12px 12px 0; border-radius: 14px; overflow: hidden; background: var(--apt-route-line); box-shadow: 0 0 0 1px var(--apt-route-line); z-index: 2;
  & > div { display: grid; gap: 0; padding: 8px 12px; background: var(--apt-route-surface); line-height: 1.15; }
  & b { font-size: clamp(15px, .6cqi + 9px, 19px); font-weight: 800; letter-spacing: -.02em; font-variant-numeric: tabular-nums; display: flex; align-items: baseline; gap: 2px; }
  & b i { font-style: normal; font-size: 11px; font-weight: 650; color: var(--apt-route-mute); }
  & small { font-size: 10.5px; color: var(--apt-route-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
  & .is-bad b { color: var(--apt-route-err); } & .is-ok b { color: var(--apt-route-green); } & .is-ok svg { width: 18px; height: 18px; stroke-width: 2.2; }
}
.apt-route .apt-route-map { position: relative; min-height: 0; overflow: hidden; }
.apt-route .apt-route-svg {
  --ps: 1; display: block; width: 100%; height: 100%;
  & .apt-route-land { fill: var(--apt-route-land); stroke: none; }
  & .apt-route-sea { fill: var(--apt-route-water); stroke: color-mix(in oklab, var(--apt-route-water) 55%, var(--apt-route-ink)); stroke-width: 1.2; }
  & .apt-route-river { fill: none; stroke: var(--apt-route-water); stroke-width: 26; stroke-linecap: round; }
  & .apt-route-park { fill: color-mix(in oklab, var(--apt-route-green) 26%, var(--apt-route-land)); stroke: none; }
  & .apt-route-sand { fill: color-mix(in oklab, var(--apt-route-food) 22%, var(--apt-route-land)); stroke: none; }
  & .apt-route-contour { fill: none; stroke: color-mix(in oklab, var(--apt-route-ink) 12%, transparent); stroke-width: 1.2; }
  & .apt-route-roads path { fill: none; stroke: var(--apt-route-surface); stroke-width: 9; stroke-linecap: round; stroke-linejoin: round; filter: drop-shadow(0 0 .6px color-mix(in oklab, var(--apt-route-ink) 40%, transparent)); }
  & .apt-route-roads path.is-minor { stroke-width: 4.5; }
  & .apt-route-bridge { stroke: color-mix(in oklab, var(--apt-route-ink) 45%, var(--apt-route-bg)); stroke-width: 10; stroke-linecap: butt; }
  & .apt-route-tramline { fill: none; stroke: color-mix(in oklab, var(--apt-route-accent) 35%, transparent); stroke-width: 2; stroke-dasharray: 2 5; }
  & .apt-route-lbl { font: italic 600 15px ui-serif, Georgia, serif; letter-spacing: .14em; text-transform: uppercase; fill: color-mix(in oklab, var(--apt-route-ink) 34%, transparent); pointer-events: none; }
