/* ── Porto Alva · day itinerary planner ──────────────────────────────────
   The order of stops is the only thing you edit. Everything else — each
   leg's distance, mode, minutes and fare, the arrival and wait at every
   stop, opening-hours conflicts, the map route, the time ribbon and the day
   totals — is recomputed from that order by one schedule() pass. */
const P = 'apt-route';
const doc = root.ownerDocument;
const NS = 'http://www.w3.org/2000/svg';
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const clamp = (v, a, b) => Math.min(b, Math.max(a, v));
const hm = m => String(Math.floor(m / 60) % 24).padStart(2, '0') + ':' + String(Math.round(m) % 60).padStart(2, '0');
const mins = m => (m >= 60 ? Math.floor(m / 60) + ' h ' + (m % 60 ? (m % 60) + ' min' : '') : m + ' min').trim();
const H = (h, m) => h * 60 + (m || 0);
const MAC = /Mac|iP/.test(navigator.platform || navigator.userAgent || '');

/* ── places: map units, 1 unit = 5 m ── */
const HOTEL = { id: 'hotel', name: 'Hotel Lanterna', x: 470, y: 300 };
const CAT = {
  food: { label: 'Food & drink', c: 'food' }, market: { label: 'Market', c: 'green' }, museum: { label: 'Museum', c: 'teal' },
  view: { label: 'Viewpoint', c: 'accent' }, sight: { label: 'Sight', c: 'accent' }, beach: { label: 'Beach', c: 'water' },
  park: { label: 'Garden', c: 'green' }, shop: { label: 'Shopping', c: 'food' }, train: { label: 'Departure', c: 'ink' }
};
const PL = {
  duna: { name: 'Pastelaria Duna', cat: 'food', x: 505, y: 334, dur: 40, open: H(7, 30), close: H(19), blurb: 'Custard tarts out of the oven at 8' },
  mercado: { name: 'Mercado do Rio', cat: 'market', x: 566, y: 372, dur: 50, open: H(8), close: H(14), blurb: 'Fish hall closes early' },
  azulejo: { name: 'Casa do Azulejo', cat: 'museum', x: 428, y: 214, dur: 90, open: H(10), close: H(18), blurb: 'Tile museum, 4 floors' },
  se: { name: 'Miradouro da Sé', cat: 'view', x: 528, y: 226, dur: 30, blurb: 'Best light before noon' },
  amelia: { name: 'Tasca Amélia', cat: 'food', x: 612, y: 288, dur: 75, open: H(12), close: H(15, 30), blurb: 'Lunch only, no bookings' },
  conchas: { name: 'Praia das Conchas', cat: 'beach', x: 214, y: 566, dur: 120, blurb: 'Lifeguards until 18:00' },
  farol: { name: 'Farol Velho', cat: 'sight', x: 112, y: 478, dur: 45, by: H(18, 40), blurb: 'Sunset 18:52 — arrive by 18:40' },
  jardim: { name: 'Jardim Botânico do Lume', cat: 'park', x: 792, y: 236, dur: 75, open: H(9), close: H(19), blurb: 'Glasshouse at the top' },
  barco: { name: 'Cais dos Barcos cruise', cat: 'sight', x: 646, y: 404, dur: 60, fixed: H(11, 30), blurb: 'Boat leaves 11:30 sharp' },
  conservas: { name: 'Fábrica de Conservas', cat: 'museum', x: 392, y: 470, dur: 60, open: H(10), close: H(17), blurb: 'Cannery tour + tasting' },
  flores: { name: 'Rua das Flores', cat: 'shop', x: 482, y: 262, dur: 45, open: H(10), close: H(20), blurb: 'Ceramics and cork' },
  adega: { name: 'Adega Vinhal', cat: 'food', x: 704, y: 468, dur: 60, open: H(15), close: H(19), blurb: 'Tasting, last pour 18:45' },
  largo: { name: 'Taberna do Largo', cat: 'food', x: 446, y: 326, dur: 90, open: H(19), close: H(23), blurb: 'Booked for 2 at 19:30' },
  bras: { name: 'Igreja de São Brás', cat: 'sight', x: 376, y: 298, dur: 30, open: H(9), close: H(12, 30), blurb: 'Mornings only' },
  ponte: { name: 'Ponte Velha walk', cat: 'view', x: 604, y: 392, dur: 30, blurb: 'Cross on foot, back by tram' },
  mosteiro: { name: 'Mosteiro de Alva', cat: 'museum', x: 862, y: 522, dur: 75, open: H(10), close: H(17, 30), blurb: 'Cloister and library' },
  central: { name: 'Café Central', cat: 'food', x: 722, y: 356, dur: 45, open: H(8), close: H(22), blurb: 'Late lunch, river terrace' },
  estacao: { name: 'Estação de Alva · 17:10 train', cat: 'train', x: 724, y: 604, dur: 15, fixed: H(16, 50), last: true, blurb: 'Board 20 min before departure' },
  livraria: { name: 'Livraria Ondina', cat: 'shop', x: 512, y: 290, dur: 30, open: H(10), close: H(19), blurb: 'Secondhand maps upstairs' },
  gelataria: { name: 'Gelataria Mar', cat: 'food', x: 262, y: 530, dur: 20, open: H(11), close: H(21), blurb: 'Fig and port sorbet' },
  maritimo: { name: 'Museu Marítimo', cat: 'museum', x: 300, y: 430, dur: 60, open: H(10), close: H(18), blurb: 'Free on Sundays' },
  castelo: { name: 'Mirante do Castelo', cat: 'view', x: 344, y: 176, dur: 30, blurb: 'Steep climb, 140 steps' }
};
const at = id => (id === 'hotel' ? HOTEL : PL[id]);
const KM = 0.005, WALK = 16.2, TRAM_KM = 4.3;   /* walk min/km incl. detours ; tram min/km */
function travel(a, b, mode) {
  const A = at(a), B = at(b), km = Math.hypot(A.x - B.x, A.y - B.y) * KM;
  const m = mode || (km <= 1.5 ? 'walk' : 'tram');
  if (m === 'walk') return { km, mode: m, min: Math.max(2, Math.round(km * WALK)), cost: 0 };
  if (m === 'tram') return { km, mode: m, min: Math.round(6 + 3 + km * TRAM_KM), cost: 1.8 };
  return { km, mode: m, min: Math.round(4 + km * 2.7), cost: Math.round((3.25 + .95 * km) * 20) / 20 };
}

/* ── state ── */
const S = {
  day: 0, sel: null, pane: 'plan', adding: false, moving: null,
  days: [
    { id: 'fri', tab: 'Fri 16', title: 'Friday 16 October', start: H(9), stops: ['duna', 'azulejo', 'mercado', 'se', 'amelia', 'conchas', 'farol'], modes: {} },
    { id: 'sat', tab: 'Sat 17', title: 'Saturday 17 October', start: H(9, 30), stops: ['jardim', 'barco', 'conservas', 'adega', 'flores', 'largo'], modes: {} },
    { id: 'sun', tab: 'Sun 18', title: 'Sunday 18 October', start: H(9), stops: ['bras', 'ponte', 'central', 'mosteiro', 'estacao'], modes: {} }
  ],
  saved: ['livraria', 'gelataria', 'maritimo', 'castelo']
};
const past = [], future = [];
const D = () => S.days[S.day];
const snap = () => JSON.stringify({ days: S.days, saved: S.saved });
function commit(label) { past.push(snap()); if (past.length > 60) past.shift(); future.length = 0; if (label) announce(label); }
function restore(json) { const o = JSON.parse(json); S.days = o.days; S.saved = o.saved; }

/* ── schedule ── */
function schedule(day) {
  const out = [];
  let t = day.start, pos = 'hotel', km = 0, walkKm = 0, travelMin = 0, cost = 0, issues = 0;
  day.stops.forEach(id => {
    const p = PL[id], key = pos + '>' + id, leg = travel(pos, id, day.modes[key]);
    const arrive = t + leg.min;
    let start = arrive, list = [];
    if (p.fixed != null) {
      start = p.fixed;
      if (arrive > p.fixed) { list.push(['err', (p.cat === 'train' ? 'Misses the train' : 'Misses the ' + hm(p.fixed) + ' departure') + ' by ' + (arrive - p.fixed) + ' min']); start = arrive; }
    } else if (p.open != null && arrive < p.open) start = p.open;
    const end = start + p.dur;
    if (p.close != null) {
      if (start >= p.close) list.push(['err', 'Closed by then — shuts at ' + hm(p.close)]);
      else if (end > p.close) list.push(['warn', 'Closes ' + hm(p.close) + ' — only ' + (p.close - start) + ' of ' + p.dur + ' min']);
    }
    if (p.by != null && arrive > p.by) list.push(['warn', 'Arrives ' + hm(arrive) + ', after the ' + hm(p.by) + ' target']);
    issues += list.length;
    km += leg.km; travelMin += leg.min; cost += leg.cost; if (leg.mode === 'walk') walkKm += leg.km;
    out.push({ id, from: pos, key, leg, arrive, start, wait: start - arrive, end, issues: list });
    t = end; pos = id;
  });
  const back = travel(pos, 'hotel', day.modes[pos + '>hotel']);
  km += back.km; travelMin += back.min; cost += back.cost; if (back.mode === 'walk') walkKm += back.km;
  return { rows: out, back: Object.assign(back, { key: pos + '>hotel', from: pos, arrive: t + back.min }), km, walkKm, travelMin, cost, issues };
}
const dist = (a, b) => { const A = at(a), B = at(b); return Math.hypot(A.x - B.x, A.y - B.y); };
/* time-aware: every permutation is scheduled and scored, so the shortest
   route never wins by breaking an opening hour or a fixed departure */
function optimise(day) {
  const last = day.stops.filter(id => PL[id].last), free = day.stops.filter(id => !PL[id].last);
  const score = order => {
    const sc = schedule(Object.assign({}, day, { stops: order.concat(last) }));
    let errs = 0, warns = 0, wait = 0;
    sc.rows.forEach(r => { wait += r.wait; r.issues.forEach(x => { if (x[0] === 'err') errs++; else warns++; }); });
    return errs * 5000 + warns * 900 + (sc.back.arrive - day.start) + sc.travelMin * .6 + wait * .5;
  };
  let best = free.slice(), bestS = score(best);
  if (free.length <= 8) {
    const a = free.slice(), c = new Array(a.length).fill(0);
    let i = 0;
    while (i < a.length) {
      if (c[i] < i) {
        const k = i % 2 ? c[i] : 0; const tmp = a[k]; a[k] = a[i]; a[i] = tmp;
        const v = score(a); if (v < bestS - .01) { bestS = v; best = a.slice(); }
        c[i]++; i = 0;
      } else { c[i] = 0; i++; }
    }
  } else {
    let improved = true;
    while (improved) {
      improved = false;
      for (let x = 0; x < best.length - 1; x++) for (let y = x + 1; y < best.length; y++) {
        const r2 = best.slice(0, x).concat(best.slice(x, y + 1).reverse(), best.slice(y + 1)), v = score(r2);
        if (v < bestS - .01) { best = r2; bestS = v; improved = true; }
      }
    }
  }
  return best.concat(last);
}

/* ── icons ── */
