@property --apt-pass-hue { syntax: '<number>'; inherits: true; initial-value: 160; }
@property --apt-pass-chroma { syntax: '<number>'; inherits: true; initial-value: .13; }

.apt-pass {
  /* re-theme with these four */
  --apt-pass-bg: oklch(0.175 0.006 75);
  --apt-pass-ink: oklch(0.94 0.01 85);
  --apt-pass-accent: oklch(0.87 0.17 125);
  --apt-pass-paper: oklch(0.975 0.009 85);
  /* derived */
