  --apt-pass-raised: color-mix(in oklab, var(--apt-pass-ink) 10%, var(--apt-pass-bg));
  --apt-pass-line: color-mix(in oklab, var(--apt-pass-ink) 11%, transparent);
  --apt-pass-line2: color-mix(in oklab, var(--apt-pass-ink) 20%, transparent);
  --apt-pass-mute: color-mix(in oklab, var(--apt-pass-ink) 60%, var(--apt-pass-bg));
  --apt-pass-faint: color-mix(in oklab, var(--apt-pass-ink) 36%, var(--apt-pass-bg));
  --apt-pass-pink: oklch(0.21 0.02 60);
  --apt-pass-pmute: color-mix(in oklab, var(--apt-pass-pink) 55%, var(--apt-pass-paper));
  --apt-pass-mono: ui-monospace, Menlo, monospace;
  --apt-pass-ease: cubic-bezier(.2, .85, .25, 1);
  --apt-pass-spring: linear(0, .1 4%, .38 10%, .74 17%, .97 24%, 1.06 30%, 1.07 35%, 1.04 42%, 1.01 52%, .996 64%, 1);

  position: relative; width: 100%; height: var(--apt-pass-h, 680px);
  container-type: inline-size; container-name: apt-pass; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: radial-gradient(120% 80% at 50% -10%, color-mix(in oklab, var(--apt-pass-accent) 5%, transparent), transparent 60%), var(--apt-pass-bg);
  color: var(--apt-pass-ink); color-scheme: dark; accent-color: var(--apt-pass-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; border-radius: 16px; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--apt-pass-accent); outline-offset: 2px; }
  & button, & input { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; }
  & h2, & h3, & h4, & p, & ol, & dl, & dd { margin: 0; padding: 0; }
  & ol { list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 9.5px/1 var(--apt-pass-mono); padding: 2px 4px; display: inline-block; border: 1px solid currentColor; border-bottom-width: 2px; border-radius: 4px; opacity: .6; }
}

/* ── shell ── */
.apt-pass .apt-pass-app { height: 100%; display: grid; grid-template-columns: 236px minmax(0, 1fr) 300px; grid-template-rows: minmax(0, 1fr); grid-template-areas: "wallet main live"; }
.apt-pass .apt-pass-nav { display: none; }
.apt-pass .apt-pass-wallet { grid-area: wallet; min-height: 0; display: flex; flex-direction: column; gap: 10px; padding: 16px 14px; border-right: 1px solid var(--apt-pass-line); overflow-y: auto; scrollbar-width: none; }
.apt-pass .apt-pass-main { grid-area: main; min-height: 0; overflow-y: auto; scrollbar-width: none; container-type: inline-size; container-name: apt-pass-main; }
.apt-pass .apt-pass-live { grid-area: live; min-height: 0; display: flex; flex-direction: column; gap: 12px; padding: 16px 14px; border-left: 1px solid var(--apt-pass-line); overflow-y: auto; scrollbar-width: none; }
.apt-pass .apt-pass-whead { display: flex; align-items: center; justify-content: space-between; & h2 { font-size: 20px; font-weight: 800; letter-spacing: -.02em; } }
.apt-pass .apt-pass-ib {
