.apt-pass .apt-pass-addh { font-weight: 700; }
.apt-pass .apt-pass-adda { display: flex; gap: 6px; justify-content: flex-end; }
.apt-pass .apt-pass-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 7px 12px; border: 0; border-radius: 10px; font-weight: 650; font-size: 12.5px;
