  &.is-solid:hover:not(:disabled) { background: color-mix(in oklab, var(--apt-pass-accent) 85%, white); }
  &:disabled { opacity: .4; }
  &[aria-pressed="true"] { color: var(--apt-pass-accent); }
}

/* the wallet: stubs overlap like cards in a sleeve */
.apt-pass .apt-pass-stack { display: grid; gap: 0; padding-top: 4px; }
.apt-pass .apt-pass-stub {
  --band: oklch(0.6 var(--ch) var(--h));
  position: relative; display: grid; gap: 4px; padding: 0 0 24px; margin-top: -16px; border: 0; border-radius: 14px; text-align: left; overflow: hidden;
  background: var(--apt-pass-paper); color: var(--apt-pass-pink); box-shadow: 0 -6px 16px -8px black, 0 0 0 1px color-mix(in oklab, black 30%, transparent);
  transition: translate .45s var(--apt-pass-spring), box-shadow .3s, filter .3s;
  animation: apt-pass-deal .55s var(--apt-pass-ease) both; animation-delay: calc(var(--i) * 70ms);
  &:first-child { margin-top: 0; }
  &:last-child { padding-bottom: 12px; }
  &:hover { translate: 0 -4px; }
  &[aria-selected="true"] { translate: 8px 0; box-shadow: 0 -6px 16px -8px black, 0 0 0 2px var(--apt-pass-accent); z-index: 2; }
  &.is-used { filter: grayscale(1) brightness(.85); }
}
@keyframes apt-pass-deal { from { opacity: 0; translate: 0 18px; } }
.apt-pass .apt-pass-sband { display: flex; justify-content: space-between; align-items: baseline; padding: 8px 12px 7px; background: var(--band); color: white; transition: background .8s; & b { font-size: 12px; font-weight: 750; } & small { font: 600 11px var(--apt-pass-mono); opacity: .85; } }
.apt-pass .apt-pass-sroute { display: flex; align-items: center; gap: 8px; padding: 2px 12px 0; & b { font-size: 21px; font-weight: 800; letter-spacing: -.01em; } & svg { width: 14px; height: 14px; color: var(--apt-pass-pmute); } }
.apt-pass .apt-pass-smeta {
