}

/* ── the pass card ── */
.apt-pass .apt-pass-stage { position: relative; display: grid; align-content: start; gap: 14px; padding: 22px clamp(14px, 2.4cqi, 28px) 20px; min-height: 100%; perspective: 1200px; }
.apt-pass .apt-pass-card {
