  .apt-pass .apt-pass-stamp, .apt-pass .apt-pass-dep-stamp { right: 20px; }
}

@media (prefers-reduced-motion: reduce) {
  .apt-pass {
    & *, & *::before, & *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; transition-delay: 0s !important; }
    & .apt-pass-card { transform: none !important; }
    & .apt-pass-beam { animation: none; translate: 0 120%; opacity: .5; }
    & .apt-pass-tmap .apt-pass-trail { stroke-dashoffset: 0; }
  }
}

