/* ── Corvid wallet · boarding passes with live gate states ───────────────
   Today's flight is a pure function of one simulated airport clock: scrub
   or play it and the pass band colour, gate (with the struck old one), the
   countdown, the walk-to-gate path, the milestones and the update feed all
   re-derive from live(t). The 2D code is drawn on a DPR-aware canvas. */
const P = 'apt-pass';
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const H = (h, m) => h * 60 + (m || 0);
const hm = m => String(Math.floor(m / 60) % 24).padStart(2, '0') + ':' + String(m % 60).padStart(2, '0');
const span = m => (m >= 60 ? Math.floor(m / 60) + ' h ' + (m % 60 ? (m % 60) + ' min' : '') : m + ' min').trim();
const hashStr = s => { let h = 2166136261; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); } return h >>> 0; };
const rng = seed => { let x = seed || 1; return () => { x ^= x << 13; x ^= x >>> 17; x ^= x << 5; return ((x >>> 0) % 10000) / 10000; }; };

/* ── data ── */
const T0 = H(12, 40), T1 = H(15, 20);
