.apt-stays {
  /* re-theme with these four */
  --apt-stays-bg: oklch(0.2 0.011 55);
  --apt-stays-ink: oklch(0.95 0.012 80);
  --apt-stays-accent: oklch(0.72 0.16 35);
  --apt-stays-water: oklch(0.29 0.035 240);
  /* derived */
  --apt-stays-surface: color-mix(in oklab, var(--apt-stays-ink) 6%, var(--apt-stays-bg));
  --apt-stays-raised: color-mix(in oklab, var(--apt-stays-ink) 10%, var(--apt-stays-bg));
  --apt-stays-land: color-mix(in oklab, var(--apt-stays-ink) 5%, var(--apt-stays-bg));
  --apt-stays-line: color-mix(in oklab, var(--apt-stays-ink) 11%, transparent);
  --apt-stays-line2: color-mix(in oklab, var(--apt-stays-ink) 20%, transparent);
  --apt-stays-mute: color-mix(in oklab, var(--apt-stays-ink) 60%, var(--apt-stays-bg));
  --apt-stays-faint: color-mix(in oklab, var(--apt-stays-ink) 36%, var(--apt-stays-bg));
  --apt-stays-good: oklch(0.78 0.12 155);
  --apt-stays-mono: ui-monospace, Menlo, monospace;
  --apt-stays-ease: cubic-bezier(.2, .85, .25, 1);
  --apt-stays-spring: linear(0, .1 4%, .38 10%, .74 17%, .97 24%, 1.06 30%, 1.07 35%, 1.04 42%, 1.01 52%, .996 64%, 1);

  position: relative; width: 100%; height: var(--apt-stays-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apt-stays-bg); color: var(--apt-stays-ink); color-scheme: dark; accent-color: var(--apt-stays-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; border-radius: 16px; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--apt-stays-accent); outline-offset: 2px; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; }
  & h3, & p, & ol, & dl, & dd, & fieldset { margin: 0; padding: 0; }
  & ol { list-style: none; } & fieldset { border: 0; min-width: 0; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 9.5px/1 var(--apt-stays-mono); padding: 2px 4px; display: inline-block; border: 1px solid currentColor; border-bottom-width: 2px; border-radius: 4px; }
  & .apt-stays-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}

/* ── shell ── */
.apt-stays .apt-stays-app { height: 100%; display: grid; grid-template-columns: minmax(380px, 430px) minmax(0, 1fr); grid-template-rows: minmax(0, 1fr); grid-template-areas: "side map"; }
.apt-stays .apt-stays-nav { display: none; }
.apt-stays .apt-stays-side { grid-area: side; position: relative; min-height: 0; display: flex; flex-direction: column; border-right: 1px solid var(--apt-stays-line); }
.apt-stays .apt-stays-mapwrap { grid-area: map; position: relative; min-height: 0; overflow: hidden; }

/* header + filters */
.apt-stays .apt-stays-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 16px 16px 10px; }
.apt-stays .apt-stays-where { display: flex; align-items: center; gap: 6px; font-size: 19px; font-weight: 800; letter-spacing: -.02em; & svg { color: var(--apt-stays-accent); width: 18px; height: 18px; } }
.apt-stays .apt-stays-when { font-size: 12px; color: var(--apt-stays-mute); font-variant-numeric: tabular-nums; }
.apt-stays .apt-stays-sort {
  position: relative; flex: none;
  & select { appearance: none; padding: 7px 28px 7px 10px; border: 0; border-radius: 10px; background: var(--apt-stays-surface); box-shadow: inset 0 0 0 1px var(--apt-stays-line2); font-weight: 600; font-size: 12px; cursor: pointer; }
  & svg { position: absolute; right: 8px; top: 50%; translate: 0 -50%; pointer-events: none; color: var(--apt-stays-mute); }
}
.apt-stays .apt-stays-filters { display: grid; gap: 10px; padding: 0 16px 10px; border-bottom: 1px solid var(--apt-stays-line); }
.apt-stays .apt-stays-fl { display: flex; justify-content: space-between; font-size: 10.5px; font-weight: 700; letter-spacing: .09em; text-transform: uppercase; color: var(--apt-stays-mute); & output { letter-spacing: 0; text-transform: none; font-size: 12px; color: var(--apt-stays-ink); font-variant-numeric: tabular-nums; } }
.apt-stays .apt-stays-hist {
  display: flex; align-items: flex-end; gap: 3px; height: 34px; margin: 6px 7px 0;
  & i { flex: 1; height: calc(8% + var(--v) * 92%); border-radius: 3px 3px 0 0; background: var(--apt-stays-line2); transition: height .45s var(--apt-stays-ease), background .25s; }
  & i.is-on { background: color-mix(in oklab, var(--apt-stays-accent) 75%, var(--apt-stays-bg)); }
}
.apt-stays .apt-stays-range {
  --a: 0; --b: 1; position: relative; height: 20px;
  &::before { content: ""; position: absolute; left: 7px; right: 7px; top: 9px; height: 3px; border-radius: 3px; background: linear-gradient(90deg, var(--apt-stays-line2) calc(var(--a) * 100%), var(--apt-stays-accent) 0 calc(var(--b) * 100%), var(--apt-stays-line2) 0); }
  & input { position: absolute; inset: 0; width: 100%; margin: 0; appearance: none; background: none; pointer-events: none; }
  & input::-webkit-slider-thumb { appearance: none; pointer-events: auto; width: 16px; height: 16px; border-radius: 50%; background: var(--apt-stays-ink); box-shadow: 0 0 0 3px var(--apt-stays-bg), 0 0 0 4.5px var(--apt-stays-accent); cursor: grab; }
  & input::-moz-range-thumb { pointer-events: auto; width: 14px; height: 14px; border: 0; border-radius: 50%; background: var(--apt-stays-ink); cursor: grab; }
  & input::-webkit-slider-runnable-track { background: none; }
}
.apt-stays .apt-stays-chips { display: flex; flex-wrap: wrap; gap: 5px; }
.apt-stays .apt-stays-seg {
  display: inline-flex; padding: 2px; border-radius: 99px; background: var(--apt-stays-surface); box-shadow: inset 0 0 0 1px var(--apt-stays-line2);
  & button { display: inline-flex; align-items: center; gap: 3px; padding: 4px 10px; border: 0; border-radius: 99px; background: none; font-size: 12px; font-weight: 650; color: var(--apt-stays-mute); transition: background .2s, color .2s; }
  & svg { width: 11px; height: 11px; fill: currentColor; stroke: none; }
  & button[aria-checked="true"] { background: var(--apt-stays-ink); color: var(--apt-stays-bg); }
}
.apt-stays .apt-stays-chip {
  display: inline-flex; align-items: center; gap: 5px; padding: 4px 10px; border: 0; border-radius: 99px; font-size: 12px; font-weight: 600; background: transparent; box-shadow: inset 0 0 0 1px var(--apt-stays-line2); transition: background .2s, box-shadow .2s, scale .25s var(--apt-stays-spring);
  & small { font-size: 10.5px; color: var(--apt-stays-faint); font-variant-numeric: tabular-nums; }
  & svg { width: 13px; height: 13px; }
  &:hover:not(:disabled) { background: var(--apt-stays-surface); }
  &:active:not(:disabled) { scale: .95; }
  &[aria-pressed="true"] { background: color-mix(in oklab, var(--apt-stays-accent) 18%, transparent); box-shadow: inset 0 0 0 1.5px var(--apt-stays-accent); & small { color: var(--apt-stays-ink); } }
  &.is-saved[aria-pressed="true"] svg { fill: var(--apt-stays-accent); stroke: var(--apt-stays-accent); }
  &:disabled { opacity: .4; }
}
.apt-stays .apt-stays-count { padding: 10px 16px 6px; font-size: 12px; color: var(--apt-stays-mute); font-variant-numeric: tabular-nums; & b { color: var(--apt-stays-ink); } & span { color: var(--apt-stays-faint); } & em { font-style: normal; margin-left: 4px; padding: 1px 7px; border-radius: 99px; background: color-mix(in oklab, var(--apt-stays-accent) 22%, transparent); color: var(--apt-stays-accent); font-size: 11px; font-weight: 650; } }

/* results */
.apt-stays .apt-stays-list { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; display: grid; align-content: start; gap: 8px; padding: 4px 12px 16px; }
.apt-stays .apt-stays-item {
  position: relative;
  &.is-new { animation: apt-stays-in .45s var(--apt-stays-ease) both; animation-delay: calc(var(--i) * 35ms); }
}
