}
/* ── narrow: list or map ── */
@container (max-width: 759px) {
  .apt-stays .apt-stays-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "nav" "main"; }
  .apt-stays .apt-stays-nav {
    grid-area: nav; display: grid; grid-template-columns: 1fr 1fr; gap: 4px; padding: 8px 10px; border-bottom: 1px solid var(--apt-stays-line);
