    & button[aria-selected="true"] { background: var(--apt-stays-surface); color: var(--apt-stays-ink); box-shadow: inset 0 0 0 1px var(--apt-stays-line2); }
  }
  .apt-stays .apt-stays-side, .apt-stays .apt-stays-mapwrap { grid-area: main; display: none; border: 0; }
  .apt-stays[data-pane="list"] .apt-stays-side { display: flex; }
  .apt-stays[data-pane="map"] .apt-stays-mapwrap { display: block; }
  .apt-stays .apt-stays-mtools { top: 10px; flex-direction: column; }
  .apt-stays .apt-stays-mk { display: none; }
}
@container (max-width: 420px) {
  .apt-stays .apt-stays-head { flex-wrap: wrap; }
  .apt-stays .apt-stays-pk { width: 220px; grid-template-columns: 1fr; & .apt-stays-photo { display: none; } }
}

@media (prefers-reduced-motion: reduce) {
  .apt-stays {
    & *, & *::before, & *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; transition-delay: 0s !important; }
    & .apt-stays-spin { animation: none; }
    & .apt-stays-pin:hover, & .apt-stays-pin.is-hover { scale: 1; }
  }
}

