@property --apt-pack-p { syntax: '<number>'; inherits: true; initial-value: 0; }

.apt-pack {
  /* re-theme with these four */
  --apt-pack-bg: oklch(0.968 0.011 170);
  --apt-pack-ink: oklch(0.25 0.035 205);
  --apt-pack-accent: oklch(0.74 0.15 78);
  --apt-pack-rain: oklch(0.58 0.11 245);
