  --apt-pack-line: color-mix(in oklab, var(--apt-pack-ink) 11%, transparent);
  --apt-pack-line2: color-mix(in oklab, var(--apt-pack-ink) 20%, transparent);
  --apt-pack-mute: color-mix(in oklab, var(--apt-pack-ink) 60%, var(--apt-pack-bg));
  --apt-pack-faint: color-mix(in oklab, var(--apt-pack-ink) 36%, var(--apt-pack-bg));
  --apt-pack-wash: color-mix(in oklab, var(--apt-pack-ink) 4%, var(--apt-pack-bg));
  --apt-pack-deep: color-mix(in oklab, var(--apt-pack-accent) 55%, var(--apt-pack-ink));
  --apt-pack-bad: oklch(0.57 0.19 28);
  --apt-pack-mono: ui-monospace, Menlo, monospace;
  --apt-pack-ease: cubic-bezier(.2, .85, .25, 1);
  --apt-pack-spring: linear(0, .1 4%, .38 10%, .74 17%, .97 24%, 1.06 30%, 1.07 35%, 1.04 42%, 1.01 52%, .996 64%, 1);

  position: relative; width: 100%; height: var(--apt-pack-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apt-pack-bg); color: var(--apt-pack-ink); color-scheme: light; accent-color: var(--apt-pack-ink);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; border-radius: 16px; box-shadow: 0 0 0 1px var(--apt-pack-line); -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--apt-pack-ink); outline-offset: 2px; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; }
  & h2, & h3, & p, & ol, & ul { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 9.5px/1 var(--apt-pack-mono); padding: 2px 4px; display: inline-block; border: 1px solid currentColor; border-bottom-width: 2px; border-radius: 4px; opacity: .6; }
  & .apt-pack-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
  & .c-a { --tc: oklch(0.62 0.08 205); } & .c-b { --tc: var(--apt-pack-rain); } & .c-c { --tc: oklch(0.52 0.06 60); } & .c-d { --tc: oklch(0.7 0.09 160); }
  & .c-e { --tc: oklch(0.45 0.03 230); } & .c-f { --tc: oklch(0.66 0.13 25); } & .c-g { --tc: var(--apt-pack-accent); }
}

/* ── shell ── */
.apt-pack .apt-pack-app { height: 100%; display: grid; grid-template-columns: 276px minmax(0, 1fr) 288px; grid-template-rows: minmax(0, 1fr); grid-template-areas: "trip list bag"; }
.apt-pack .apt-pack-nav { display: none; }
