.apt-pack .apt-pack-listpane { grid-area: list; min-height: 0; display: flex; flex-direction: column; background: var(--apt-pack-surface); }
.apt-pack .apt-pack-bagpane { grid-area: bag; min-height: 0; overflow-y: auto; scrollbar-width: none; display: flex; flex-direction: column; gap: 12px; padding: 16px 14px; border-left: 1px solid var(--apt-pack-line); }
.apt-pack .apt-pack-trip > *, .apt-pack .apt-pack-bagpane > * { flex: none; }
.apt-pack .apt-pack-h { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--apt-pack-mute); }

