.apt-pack .apt-pack-day {
  position: relative; width: 100%; display: grid; grid-template-columns: 46px 20px minmax(0, 1fr) 40px; align-items: center; gap: 8px; padding: 5px 8px; border: 0; border-radius: 10px; background: none; text-align: left; font-variant-numeric: tabular-nums;
  transition: background .2s;
