.apt-pack .apt-pack-dot { position: absolute; left: 3px; top: 50%; width: 5px; height: 5px; translate: 0 -50%; border-radius: 50%; background: var(--apt-pack-accent); }
.apt-pack .apt-pack-daycard { min-height: 56px; }
