}
.apt-pack .apt-pack-link { border: 0; background: none; padding: 0; font-size: 12px; font-weight: 650; color: var(--apt-pack-deep); text-decoration: underline; text-underline-offset: 3px; text-decoration-color: color-mix(in oklab, currentColor 35%, transparent); &:disabled { color: var(--apt-pack-faint); text-decoration: none; } }
.apt-pack .apt-pack-tabs {
  display: flex; gap: 4px;
  & button { display: inline-flex; align-items: center; gap: 6px; padding: 5px 11px; border: 0; border-radius: 99px; background: none; font-weight: 650; font-size: 12px; color: var(--apt-pack-mute); transition: background .2s, color .2s; }
  & small { font-size: 11px; font-variant-numeric: tabular-nums; opacity: .75; }
  & button[aria-selected="true"] { background: var(--apt-pack-ink); color: var(--apt-pack-bg); }
  & button:hover:not([aria-selected="true"]) { background: var(--apt-pack-line); }
}
.apt-pack .apt-pack-scroll { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; padding: 6px 12px 14px; }
.apt-pack .apt-pack-grp {
  padding: 8px 0 4px;
  & > header { position: sticky; top: -6px; z-index: 1; display: flex; align-items: baseline; justify-content: space-between; padding: 8px 6px 6px; background: var(--apt-pack-surface); }
  & h3 { font-size: 13px; font-weight: 750; letter-spacing: -.005em; } & h3 small { margin-left: 8px; font-size: 11px; font-weight: 500; color: var(--apt-pack-faint); font-variant-numeric: tabular-nums; }
  & ul { display: grid; gap: 2px; }
