.apt-pack .apt-pack-row {
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto auto 52px; align-items: center; gap: 10px; padding: 7px 6px; border-radius: 11px; transition: background .2s, opacity .3s;
  &:hover { background: var(--apt-pack-wash); }
  &.is-new { animation: apt-pack-in .45s var(--apt-pack-ease) both; animation-delay: calc(var(--i) * 30ms); }
  &.is-hit { background: color-mix(in oklab, var(--apt-pack-rain) 9%, transparent); box-shadow: inset 3px 0 0 var(--apt-pack-rain); }
  &.is-packed .apt-pack-nm b { color: var(--apt-pack-mute); text-decoration: line-through; text-decoration-color: color-mix(in oklab, var(--apt-pack-ink) 40%, transparent); }
}
.apt-pack .apt-pack-cb {
  position: relative; display: grid; place-items: center; width: 22px; height: 22px; cursor: pointer;
  & input { position: absolute; inset: 0; margin: 0; opacity: 0; cursor: pointer; }
  & span { display: grid; place-items: center; width: 20px; height: 20px; border-radius: 7px; box-shadow: inset 0 0 0 1.5px var(--apt-pack-line2); background: var(--apt-pack-surface); transition: background .2s, box-shadow .2s, scale .3s var(--apt-pack-spring); }
  & svg { width: 13px; height: 13px; stroke-width: 2.8; color: var(--apt-pack-ink); stroke-dasharray: 20; stroke-dashoffset: 20; transition: stroke-dashoffset .3s var(--apt-pack-ease); }
  &:has(input:checked) span { background: var(--apt-pack-accent); box-shadow: none; scale: 1.05; }
  &:has(input:checked) svg { stroke-dashoffset: 0; }
  &:has(input:focus-visible) span { outline: 2px solid var(--apt-pack-ink); outline-offset: 2px; }
}
.apt-pack .apt-pack-nm { min-width: 0; display: grid; gap: 2px; & b { font-weight: 650; font-size: 13.5px; } }
.apt-pack .apt-pack-why { display: flex; flex-wrap: wrap; gap: 3px; & i { font-style: normal; font-size: 10.5px; padding: 0 6px; border-radius: 5px; background: var(--apt-pack-line); color: color-mix(in oklab, var(--apt-pack-ink) 75%, var(--apt-pack-bg)); white-space: nowrap; } & i.is-ed { background: color-mix(in oklab, var(--apt-pack-accent) 25%, transparent); } & i.is-worn { background: color-mix(in oklab, var(--apt-pack-rain) 16%, transparent); color: var(--apt-pack-rain); } }
.apt-pack .apt-pack-wb {
  display: grid; place-items: center; width: 28px; height: 28px; border: 0; border-radius: 8px; background: none; color: var(--apt-pack-faint); transition: background .2s, color .2s;
  &:hover { background: var(--apt-pack-line); color: var(--apt-pack-ink); }
