}
.apt-pack .apt-pack-qty {
  display: inline-flex; align-items: center; gap: 2px; padding: 2px; border-radius: 9px; box-shadow: inset 0 0 0 1px var(--apt-pack-line2);
  & button { display: grid; place-items: center; width: 22px; height: 22px; border: 0; border-radius: 7px; background: none; } & button:hover:not(:disabled) { background: var(--apt-pack-line); } & button:disabled { opacity: .25; }
  & svg { width: 12px; height: 12px; stroke-width: 2.4; }
