.apt-pack .apt-pack-g { text-align: right; font-size: 11px; color: var(--apt-pack-faint); font-variant-numeric: tabular-nums; }
.apt-pack .apt-pack-rm { justify-self: end; display: grid; place-items: center; width: 26px; height: 26px; border: 0; border-radius: 8px; background: none; color: var(--apt-pack-faint); &:hover { background: color-mix(in oklab, var(--apt-pack-bad) 12%, transparent); color: var(--apt-pack-bad); } }
