.apt-pack .apt-pack-err { grid-column: 1 / -1; font-style: normal; font-size: 11.5px; color: var(--apt-pack-bad); &:empty { display: none; } }
.apt-pack .apt-pack-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 7px 14px; border: 0; border-radius: 10px; font-weight: 700; font-size: 12.5px;
  background: var(--apt-pack-surface); box-shadow: inset 0 0 0 1.5px var(--apt-pack-ink); transition: background .2s, color .2s, scale .25s var(--apt-pack-spring);
  &:hover { background: var(--apt-pack-ink); color: var(--apt-pack-bg); } &:active { scale: .97; }
  &.is-solid { background: var(--apt-pack-ink); color: var(--apt-pack-bg); box-shadow: none; &:hover { background: var(--apt-pack-deep); } }
  & svg { width: 15px; height: 15px; }
}

/* ── bag pane ── */
.apt-pack .apt-pack-bagsel {
  display: grid; grid-template-columns: 1fr 1fr; gap: 6px;
  & button { display: grid; gap: 1px; padding: 8px 10px; border: 0; border-radius: 12px; text-align: left; background: var(--apt-pack-surface); box-shadow: inset 0 0 0 1px var(--apt-pack-line2); transition: box-shadow .2s, background .2s; }
  & b { font-weight: 750; } & small { font-size: 10.5px; color: var(--apt-pack-mute); line-height: 1.25; }
  & button[aria-checked="true"] { box-shadow: inset 0 0 0 2px var(--apt-pack-ink); background: var(--apt-pack-surface); }
}
.apt-pack .apt-pack-meter { display: grid; gap: 8px; }
.apt-pack .apt-pack-kg {
  display: flex; align-items: baseline; gap: 6px; font-variant-numeric: tabular-nums;
  & b { font-size: 38px; font-weight: 800; letter-spacing: -.04em; line-height: 1; } & span { color: var(--apt-pack-mute); font-weight: 600; }
  & em { margin-left: auto; font-style: normal; font-size: 12px; font-weight: 700; color: var(--apt-pack-deep); }
  &.is-over b, &.is-over em { color: var(--apt-pack-bad); }
}
.apt-pack .apt-pack-gauge {
  position: relative; height: 14px; border-radius: 7px; background: var(--apt-pack-line); overflow: visible;
  & i { position: absolute; left: 0; top: 0; bottom: 0; border-radius: 7px; transition: width .6s var(--apt-pack-ease); }
  & .is-all { width: calc(var(--all) * 100%); background: repeating-linear-gradient(135deg, color-mix(in oklab, var(--apt-pack-accent) 45%, transparent) 0 4px, color-mix(in oklab, var(--apt-pack-accent) 25%, transparent) 4px 8px); }
  & .is-pk { width: calc(var(--pk) * 100%); background: var(--apt-pack-accent); }
  & .is-tare { width: calc(var(--tare) * 100%); background: var(--apt-pack-ink); }
  & b { position: absolute; top: -5px; bottom: -5px; left: calc(var(--lim) * 100%); width: 2px; border-radius: 2px; background: var(--apt-pack-bad); transition: left .6s var(--apt-pack-ease); }
}
.apt-pack .apt-pack-meter:has(.is-over) .apt-pack-gauge .is-all { background: repeating-linear-gradient(135deg, color-mix(in oklab, var(--apt-pack-bad) 45%, transparent) 0 4px, color-mix(in oklab, var(--apt-pack-bad) 22%, transparent) 4px 8px); }
.apt-pack .apt-pack-legend { display: flex; flex-wrap: wrap; gap: 4px 10px; font-size: 11px; color: var(--apt-pack-mute); font-variant-numeric: tabular-nums; & span::before { content: ""; display: inline-block; width: 8px; height: 8px; margin-right: 4px; border-radius: 2px; vertical-align: -1px; } & .is-tare::before { background: var(--apt-pack-ink); } & .is-pk::before { background: var(--apt-pack-accent); } & .is-all::before { background: color-mix(in oklab, var(--apt-pack-accent) 40%, transparent); } }
.apt-pack .apt-pack-case { display: grid; gap: 6px; }
.apt-pack .apt-pack-shell {
  position: relative; margin-top: 12px; padding: 10px; border-radius: 16px; background: var(--apt-pack-wash); box-shadow: inset 0 0 0 2px var(--apt-pack-ink);
  &::before { content: ""; position: absolute; left: 50%; top: -12px; width: 64px; height: 12px; translate: -50% 0; border: 2.5px solid var(--apt-pack-ink); border-bottom: 0; border-radius: 10px 10px 0 0; }
  &::after { content: ""; position: absolute; left: 50%; top: 6px; bottom: 6px; width: 0; border-left: 1.5px dashed var(--apt-pack-line2); }
}
.apt-pack .apt-pack-tiles { position: relative; display: grid; grid-template-columns: repeat(8, 1fr); grid-auto-rows: 18px; grid-auto-flow: dense; gap: 3px; min-height: 120px; }
.apt-pack .apt-pack-tile {
  position: relative; display: grid; place-items: center; overflow: hidden; border-radius: 5px; background: transparent; box-shadow: inset 0 0 0 1.5px color-mix(in oklab, var(--tc) 70%, transparent);
  transition: background .35s, box-shadow .35s;
  & span { font-style: normal; font-size: 8.5px; font-weight: 700; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 100%; padding: 0 3px; color: color-mix(in oklab, var(--tc) 70%, var(--apt-pack-ink)); }
  &.is-in { background: var(--tc); box-shadow: none; animation: apt-pack-drop .4s var(--apt-pack-spring); & span { color: white; } }
}
@keyframes apt-pack-drop { from { translate: 0 -8px; } }
.apt-pack .apt-pack-vol { font-size: 11.5px; color: var(--apt-pack-mute); text-align: center; font-variant-numeric: tabular-nums; }
.apt-pack .apt-pack-wear { display: grid; gap: 6px; }
.apt-pack .apt-pack-worn { display: flex; flex-wrap: wrap; gap: 4px; }
.apt-pack .apt-pack-wchip {
  display: inline-flex; align-items: center; gap: 5px; padding: 4px 6px 4px 8px; border: 0; border-radius: 99px; font-size: 12px; font-weight: 600; background: color-mix(in oklab, var(--apt-pack-rain) 14%, transparent); color: color-mix(in oklab, var(--apt-pack-rain) 70%, var(--apt-pack-ink));
  & small { font-size: 10.5px; opacity: .8; font-variant-numeric: tabular-nums; } & svg { width: 13px; height: 13px; } & svg:last-child { opacity: .6; }
  &:hover svg:last-child { opacity: 1; }
}
.apt-pack .apt-pack-keys { margin-top: auto; display: flex; flex-wrap: wrap; align-items: center; gap: 3px; font-size: 11px; color: var(--apt-pack-faint); }

/* toast */
.apt-pack .apt-pack-toast {
  position: absolute; left: 50%; bottom: 62px; z-index: 50; translate: -50% 16px; opacity: 0; pointer-events: none; max-width: calc(100% - 32px);
  padding: 9px 14px; border-radius: 12px; background: var(--apt-pack-ink); color: var(--apt-pack-bg); font-weight: 600; font-size: 12.5px; box-shadow: 0 14px 30px -12px color-mix(in oklab, var(--apt-pack-ink) 70%, transparent);
  transition: opacity .25s, translate .5s var(--apt-pack-spring);
  &.is-on { opacity: 1; translate: -50% 0; }
}

/* ── medium ── */
@container (max-width: 1023px) {
  .apt-pack .apt-pack-app { grid-template-columns: 250px minmax(0, 1fr); grid-template-rows: minmax(0, 1fr) minmax(0, 1fr); grid-template-areas: "trip list" "bag list"; }
  .apt-pack .apt-pack-trip { border-bottom: 1px solid var(--apt-pack-line); }
  .apt-pack .apt-pack-bagpane { border-left: 0; border-right: 1px solid var(--apt-pack-line); background: var(--apt-pack-wash); }
  .apt-pack .apt-pack-keys { display: none; }
  .apt-pack .apt-pack-row { grid-template-columns: auto minmax(0, 1fr) auto auto auto; & .apt-pack-g { display: none; } }
}
/* ── narrow ── */
@container (max-width: 759px) {
  .apt-pack .apt-pack-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "nav" "main"; }
  .apt-pack .apt-pack-nav {
    grid-area: nav; display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; padding: 8px 10px; border-bottom: 1px solid var(--apt-pack-line);
    & button { padding: 8px 4px; border: 0; border-radius: 10px; background: none; font-weight: 650; color: var(--apt-pack-mute); }
    & button span { font-size: 11px; font-variant-numeric: tabular-nums; padding: 0 5px; border-radius: 99px; background: var(--apt-pack-line); }
    & button[aria-selected="true"] { background: var(--apt-pack-surface); color: var(--apt-pack-ink); box-shadow: 0 1px 3px color-mix(in oklab, var(--apt-pack-ink) 18%, transparent); }
  }
  .apt-pack .apt-pack-trip, .apt-pack .apt-pack-listpane, .apt-pack .apt-pack-bagpane { grid-area: main; display: none; border: 0; }
  .apt-pack[data-pane="trip"] .apt-pack-trip { display: flex; }
  .apt-pack[data-pane="list"] .apt-pack-listpane { display: flex; }
  .apt-pack[data-pane="bag"] .apt-pack-bagpane { display: flex; }
  .apt-pack .apt-pack-addf { grid-template-columns: minmax(0, 1fr) auto; & select { grid-column: 1; grid-row: 2; } }
  .apt-pack .apt-pack-out li { grid-template-columns: 1fr; gap: 0; }
}
@container (max-width: 420px) {
  .apt-pack .apt-pack-row { gap: 6px; }
  .apt-pack .apt-pack-why i:nth-child(n+2) { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  .apt-pack {
    & *, & *::before, & *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; transition-delay: 0s !important; }
    & .apt-pack-cb:has(input:checked) span { scale: 1; }
  }
}

