/* ── Bergen packing list · rules from the forecast ───────────────────────
   Every line in the list is the output of a rule over the 9-day forecast,
   your plans, laundry and bag choice, and says why it is there ("6 rainy
   days, 46 mm"). Items a rule rejects are kept in "Left out" with the
   reason. Weight and volume are summed from the same lines, so the bag
   gauge, the suitcase tiles and the list always agree. */
const P = 'apt-pack';
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const kg = g => (g / 1000).toFixed(1) + ' kg';

/* ── forecast ── */
const DAYS = [
  { d: 'Wed', n: 14, hi: 11, lo: 6, mm: 4, wind: 18, c: 'showers' },
  { d: 'Thu', n: 15, hi: 10, lo: 5, mm: 9, wind: 26, c: 'rain' },
  { d: 'Fri', n: 16, hi: 12, lo: 7, mm: 0, wind: 12, c: 'partly' },
  { d: 'Sat', n: 17, hi: 9, lo: 4, mm: 14, wind: 52, c: 'storm' },
  { d: 'Sun', n: 18, hi: 10, lo: 3, mm: 2, wind: 20, c: 'showers' },
  { d: 'Mon', n: 19, hi: 8, lo: 3, mm: 0, wind: 10, c: 'sun' },
  { d: 'Tue', n: 20, hi: 11, lo: 6, mm: 6, wind: 22, c: 'rain' },
  { d: 'Wed', n: 21, hi: 12, lo: 7, mm: 11, wind: 30, c: 'rain' },
  { d: 'Thu', n: 22, hi: 13, lo: 8, mm: 1, wind: 14, c: 'partly' }
];
const N = DAYS.length;
const rainy = DAYS.map((x, i) => x.mm >= 2 ? i : -1).filter(i => i > -1);
const rainMM = DAYS.reduce((s, x) => s + x.mm, 0);
const cold = DAYS.map((x, i) => x.lo <= 5 ? i : -1).filter(i => i > -1);
const minLo = Math.min(...DAYS.map(x => x.lo));
const gust = Math.max(...DAYS.map(x => x.wind)), gustDay = DAYS.findIndex(x => x.wind === gust);
const bright = DAYS.map((x, i) => x.c === 'sun' || x.c === 'partly' ? i : -1).filter(i => i > -1);
const dayName = i => DAYS[i].d + ' ' + DAYS[i].n;

const CATS = [['wear', 'Clothing'], ['wx', 'Weather layers'], ['feet', 'Footwear'], ['wash', 'Toiletries'], ['tech', 'Tech'], ['docs', 'Documents & health'], ['act', 'For your plans']];
const BAGS = { carry: { name: 'Carry-on', kg: 10, tare: 2100, cap: 80, note: '10 kg · 55 × 40 × 23 cm' }, checked: { name: 'Checked', kg: 23, tare: 3600, cap: 150, note: '23 kg · +€45 each way' } };

/* g = grams each, v = volume units (≈ 0.5 L) each */
const ITEMS = [
  { id: 'under', name: 'Underwear', cat: 'wear', g: 60, v: .5, rule: c => ({ q: c.laundry ? Math.ceil(N / 2) + 1 : N + 1, why: c.laundry ? ['washing on day 5', '+1 spare'] : [N + ' days', '+1 spare'] }) },
  { id: 'socks', name: 'Socks', cat: 'wear', g: 50, v: .4, rule: c => ({ q: c.laundry ? Math.ceil(N / 2) + 1 : N + 1, why: [c.laundry ? 'washing on day 5' : N + ' days', '+1 spare'] }) },
  { id: 'tees', name: 'T-shirts', cat: 'wear', g: 150, v: 1, rule: c => ({ q: c.laundry ? 3 : Math.ceil(N / 2), why: [c.laundry ? 'one on, two in the wash rotation' : 'one per two days under layers'] }) },
  { id: 'thermal', name: 'Merino base layer', cat: 'wear', g: 180, v: 1, wear: true, rule: () => cold.length ? { q: 2, why: [cold.length + ' nights at 5°C or colder', 'low ' + minLo + '°C'], days: cold } : { q: 0, skip: 'No nights below 6°C' } },
  { id: 'fleece', name: 'Fleece mid-layer', cat: 'wear', g: 400, v: 3, wear: true, layer: true, rule: c => ({ q: c.laundry ? 1 : 2, why: ['highs only ' + Math.min(...DAYS.map(x => x.hi)) + '–' + Math.max(...DAYS.map(x => x.hi)) + '°C'] }) },
  { id: 'trousers', name: 'Trousers', cat: 'wear', g: 450, v: 2.5, wear: true, rule: () => ({ q: 2, why: ['one on, one drying'] }) },
  { id: 'jacket', name: 'Rain shell, hooded', cat: 'wx', g: 380, v: 2, wear: true, layer: true, rule: () => rainy.length >= 2 ? { q: 1, why: [rainy.length + ' rainy days, ' + rainMM + ' mm'], days: rainy } : { q: 0, skip: 'Mostly dry week' } },
  { id: 'umbrella', name: 'Umbrella', cat: 'wx', g: 300, v: 1.5, rule: () => gust >= 40 ? { q: 0, skip: 'Gusts to ' + gust + ' km/h on ' + dayName(gustDay) + ' — a hood beats an umbrella', days: [gustDay] } : { q: 1, why: ['rain, little wind'] } },
  { id: 'gloves', name: 'Gloves', cat: 'wx', g: 80, v: .5, rule: () => minLo <= 5 ? { q: 1, why: ['mornings at ' + minLo + '°C'], days: cold } : { q: 0, skip: 'Mild mornings' } },
  { id: 'beanie', name: 'Beanie', cat: 'wx', g: 60, v: .5, rule: () => minLo <= 5 ? { q: 1, why: ['wind chill on the harbour'], days: cold } : { q: 0, skip: 'Mild mornings' } },
  { id: 'sunglasses', name: 'Sunglasses', cat: 'wx', g: 30, v: .3, rule: () => bright.length >= 2 ? { q: 1, why: [bright.length + ' bright days, low sun'], days: bright } : { q: 0, skip: 'Overcast all week' } },
  { id: 'boots', name: 'Waterproof boots', cat: 'feet', g: 1150, v: 5, wear: true, shoe: true, rule: c => rainy.length >= 3 || c.act.hike ? { q: 1, why: [c.act.hike ? 'fjord hike' : null, rainy.length + ' wet days'].filter(Boolean), days: rainy } : { q: 0, skip: 'Not wet enough' } },
