  t.classList.remove('is-on'); void t.offsetWidth; t.classList.add('is-on');
  clearTimeout(toastT); toastT = setTimeout(() => { if (root.isConnected) t.classList.remove('is-on'); }, 2600);
}
function setQty(id, d) {
