  const a = t.dataset;
  if (a.day != null) { S.sel = S.sel === +a.day ? null : +a.day; renderList(); const n = $('[data-day="' + a.day + '"]'); if (n) n.focus(); return; }
  if (a.actToggle) { S.act[a.actToggle] = !S.act[a.actToggle]; renderList(true); const n = $('[data-act-toggle="' + a.actToggle + '"]'); if (n) n.focus(); toast(ACTS.find(x => x[0] === a.actToggle)[1] + (S.act[a.actToggle] ? ' added — list updated' : ' removed — its gear is out')); return; }
  if (a.actDay) { const k = a.actDay; S.days[k] = (S.days[k] + 1) % N; S.sel = S.days[k]; renderList(); const n = $('[data-act-day="' + k + '"]'); if (n) n.focus(); const x = DAYS[S.days[k]]; toast(ACTS.find(z => z[0] === k)[1] + ' moved to ' + dayName(S.days[k]) + ' · ' + (x.mm ? x.mm + ' mm' : 'dry') + ', ' + x.wind + ' km/h'); return; }
  if (t.hasAttribute('data-laundry')) { S.laundry = !S.laundry; renderList(true); const n = $('[data-laundry]'); if (n) n.focus(); toast(S.laundry ? 'Laundry on day 5 — fewer socks, tees and underwear' : 'No laundry — a set for every day'); return; }
  if (a.view) { S.view = a.view; renderList(true); const n = $('[data-view="' + a.view + '"]'); if (n) n.focus(); return; }
  if (a.q) { setQty(a.q, +a.d); return; }
  if (a.wear) {
    const was = S.wear.has(a.wear), it = ITEMS.find(x => x.id === a.wear);
    if (was) S.wear.delete(a.wear);
    else { if (it && it.shoe) ITEMS.forEach(x => { if (x.shoe) S.wear.delete(x.id); }); S.wear.add(a.wear); }
    renderList(); const l = lines().out.find(x => x.id === a.wear); toast((was ? 'Packing ' : 'Wearing ') + esc(l ? l.name.toLowerCase() : 'it') + (was ? '' : ' — ' + kg(l ? l.g : 0) + ' off the bag')); return; }
  if (a.packall) { const ls = lines().out.filter(l => l.cat === a.packall), all = ls.every(l => S.packed.has(l.id)); ls.forEach(l => { if (all) S.packed.delete(l.id); else S.packed.add(l.id); }); renderList(true); const n = $('[data-packall="' + a.packall + '"]'); if (n) n.focus(); return; }
  if (a.rm) { S.custom = S.custom.filter(x => x.id !== a.rm); S.packed.delete(a.rm); delete S.qty[a.rm]; renderList(true); toast('Removed'); return; }
  if (a.bag) { S.bag = a.bag; renderList(); const n = $('[data-bagsel] [data-bag="' + a.bag + '"]'); if (n) n.focus(); toast(BAGS[S.bag].name + ' · ' + BAGS[S.bag].note); return; }
  if (a.go) { S.pane = a.go; root.dataset.pane = S.pane; $$('[data-go]').forEach(b => b.setAttribute('aria-selected', b.dataset.go === S.pane)); return; }
  switch (a.act) {
    case 'resetq': S.qty = {}; renderList(); toast('Quantities back to the forecast’s'); return;
