      const out = lines().out, ws = bestWear(out);
      ws.forEach(l => S.wear.add(l.id)); renderList();
      toast('Wearing ' + ws.map(l => l.name.toLowerCase()).join(' and ') + ' — ' + kg(ws.reduce((s, l) => s + l.g, 0)) + ' saved');
