});
root.addEventListener('change', e => {
  const t = e.target;
  if (t.matches('[data-pack]')) {
    const id = t.dataset.pack;
    if (t.checked) S.packed.add(id); else S.packed.delete(id);
    renderList(S.view !== 'all');
  } else if (t.matches('[data-newcat]')) S.newcat = t.value;
