renderList();

css:
.apt-split {
  /* re-theme with these four */
  --apt-split-bg: oklch(0.205 0.014 45);
  --apt-split-ink: oklch(0.95 0.011 80);
  --apt-split-accent: oklch(0.84 0.12 168);
  --apt-split-neg: oklch(0.72 0.15 14);
  /* derived */
  --apt-split-surface: color-mix(in oklab, var(--apt-split-ink) 6%, var(--apt-split-bg));
  --apt-split-raised: color-mix(in oklab, var(--apt-split-ink) 10%, var(--apt-split-bg));
  --apt-split-line: color-mix(in oklab, var(--apt-split-ink) 11%, transparent);
  --apt-split-line2: color-mix(in oklab, var(--apt-split-ink) 20%, transparent);
  --apt-split-mute: color-mix(in oklab, var(--apt-split-ink) 60%, var(--apt-split-bg));
  --apt-split-faint: color-mix(in oklab, var(--apt-split-ink) 36%, var(--apt-split-bg));
  --apt-split-on: oklch(0.22 0.04 168);
  --apt-split-mono: ui-monospace, Menlo, monospace;
  --apt-split-ease: cubic-bezier(.2, .85, .25, 1);
  --apt-split-spring: linear(0, .1 4%, .38 10%, .74 17%, .97 24%, 1.06 30%, 1.07 35%, 1.04 42%, 1.01 52%, .996 64%, 1);

  position: relative; width: 100%; height: var(--apt-split-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apt-split-bg); color: var(--apt-split-ink); color-scheme: dark; accent-color: var(--apt-split-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; border-radius: 16px; -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--apt-split-accent); outline-offset: 2px; }
  & button, & input, & select { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; }
  & h2, & h3, & p, & ol, & ul { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & .apt-split-sr { position: absolute; width: 1px; height: 1px; overflow: hidden; clip-path: inset(50%); white-space: nowrap; }
}

/* ── shell ── */
.apt-split .apt-split-app { height: 100%; display: grid; grid-template-columns: minmax(340px, 380px) minmax(0, 1fr) 286px; grid-template-rows: minmax(0, 1fr); grid-template-areas: "left mid right"; }
.apt-split .apt-split-nav { display: none; }
.apt-split .apt-split-left { grid-area: left; position: relative; min-height: 0; display: flex; flex-direction: column; border-right: 1px solid var(--apt-split-line); }
.apt-split .apt-split-mid { grid-area: mid; min-height: 0; overflow-y: auto; scrollbar-width: none; display: flex; flex-direction: column; gap: 14px; padding: 16px 18px; }
.apt-split .apt-split-right { grid-area: right; min-height: 0; display: flex; flex-direction: column; gap: 10px; padding: 16px 14px; border-left: 1px solid var(--apt-split-line); }
.apt-split .apt-split-av { display: inline-grid; place-items: center; flex: none; width: 28px; height: 28px; border-radius: 50%; background: oklch(0.74 0.11 var(--h)); color: oklch(0.22 0.04 var(--h)); font-weight: 800; font-size: 12px; &.is-sm { width: 20px; height: 20px; font-size: 10px; } }

/* header + filter */
.apt-split .apt-split-head {
  display: flex; justify-content: space-between; align-items: flex-start; gap: 12px; padding: 16px 16px 10px;
  & h2 { font-size: clamp(24px, 1.5cqi + 10px, 30px); font-weight: 800; letter-spacing: -.03em; line-height: 1.1; font-variant-numeric: tabular-nums; }
  & h2 small { font-size: 13px; font-weight: 550; letter-spacing: 0; color: var(--apt-split-mute); }
}
.apt-split .apt-split-eyebrow { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--apt-split-accent); }
.apt-split .apt-split-sub { font-size: 12px; color: var(--apt-split-mute); font-variant-numeric: tabular-nums; text-wrap: pretty; }
.apt-split .apt-split-who {
  display: flex; gap: 4px; padding: 0 16px 10px; overflow-x: auto; scrollbar-width: none; border-bottom: 1px solid var(--apt-split-line);
  & button { flex: none; display: inline-flex; align-items: center; gap: 5px; padding: 3px 10px 3px 4px; border: 0; border-radius: 99px; background: none; box-shadow: inset 0 0 0 1px var(--apt-split-line2); font-size: 12px; font-weight: 600; color: var(--apt-split-mute); transition: background .2s, color .2s; }
  & button:first-child { padding-left: 10px; }
  & button[aria-checked="true"] { background: var(--apt-split-ink); color: var(--apt-split-bg); box-shadow: none; }
  & button:hover:not([aria-checked="true"]) { background: var(--apt-split-surface); color: var(--apt-split-ink); }
}
.apt-split .apt-split-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 7px 12px; border: 0; border-radius: 10px; font-weight: 700; font-size: 12.5px; white-space: nowrap;
  background: var(--apt-split-raised); box-shadow: inset 0 0 0 1px var(--apt-split-line2); transition: background .2s, color .2s, scale .25s var(--apt-split-spring);
  &:hover:not(:disabled) { background: color-mix(in oklab, var(--apt-split-ink) 15%, var(--apt-split-bg)); }
  &:active:not(:disabled) { scale: .96; }
  &.is-solid { background: var(--apt-split-accent); color: var(--apt-split-on); box-shadow: none; &:hover:not(:disabled) { background: color-mix(in oklab, var(--apt-split-accent) 85%, white); } }
  & svg { width: 15px; height: 15px; stroke-width: 2.2; }
}
.apt-split .apt-split-ib { display: grid; place-items: center; width: 30px; height: 30px; border: 0; border-radius: 9px; background: var(--apt-split-surface); &:hover { background: var(--apt-split-raised); } }
.apt-split .apt-split-link { display: inline-flex; align-items: center; gap: 4px; border: 0; background: none; padding: 0; font-size: 12px; font-weight: 650; color: var(--apt-split-accent); & svg { width: 13px; height: 13px; } &.is-danger { color: var(--apt-split-neg); } }

/* expense list */
.apt-split .apt-split-list { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; display: grid; align-content: start; gap: 4px; padding: 8px 10px 16px; }
.apt-split .apt-split-ex {
  border-radius: 13px; transition: background .2s;
  &.is-new { animation: apt-split-in .45s var(--apt-split-ease) both; animation-delay: calc(var(--i) * 35ms); }
  &.is-open { background: var(--apt-split-surface); box-shadow: inset 0 0 0 1px var(--apt-split-line); }
  &.is-settle .apt-split-exm b { color: var(--apt-split-mute); font-weight: 600; }
}
@keyframes apt-split-in { from { opacity: 0; translate: 0 8px; } }
.apt-split .apt-split-exrow {
  width: 100%; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 8px; border: 0; border-radius: 13px; background: none; text-align: left;
  &:hover { background: var(--apt-split-surface); }
}
.apt-split .apt-split-cat {
  display: grid; place-items: center; width: 34px; height: 34px; border-radius: 11px; background: var(--apt-split-surface); color: var(--apt-split-mute); box-shadow: inset 0 0 0 1px var(--apt-split-line);
  &.is-stay { color: oklch(0.8 0.1 75); } &.is-car { color: oklch(0.78 0.09 230); } &.is-food { color: oklch(0.78 0.12 35); } &.is-fun { color: var(--apt-split-accent); } &.is-settle { color: var(--apt-split-faint); }
}
.apt-split .apt-split-exm { min-width: 0; display: grid; & b { font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } & small { font-size: 11.5px; color: var(--apt-split-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; } }
.apt-split .apt-split-exa {
  display: grid; justify-items: end; line-height: 1.2; font-variant-numeric: tabular-nums;
  & b { font-size: 14px; font-weight: 750; }
  & em { font-style: normal; font-size: 11px; color: var(--apt-split-faint); white-space: nowrap; }
  & em.is-pos { color: var(--apt-split-accent); } & em.is-neg { color: var(--apt-split-neg); } & em.is-settle { color: var(--apt-split-mute); }
}
.apt-split .apt-split-exd {
  display: grid; grid-template-rows: 0fr; visibility: hidden; transition: grid-template-rows .4s var(--apt-split-ease), visibility 0s linear .4s;
  & > div { min-height: 0; overflow: hidden; display: grid; gap: 8px; padding: 0 12px 0 52px; }
}
.apt-split .apt-split-ex.is-open .apt-split-exd { grid-template-rows: 1fr; visibility: visible; transition: grid-template-rows .45s var(--apt-split-ease), visibility 0s; & > div { padding-bottom: 12px; } }
.apt-split .apt-split-shares {
  display: grid; gap: 4px;
  & li { display: grid; grid-template-columns: auto 64px 1fr auto; gap: 8px; align-items: center; font-size: 12px; font-variant-numeric: tabular-nums; }
  & li span small { color: var(--apt-split-faint); }
  & i { height: 5px; border-radius: 5px; background: var(--apt-split-line); position: relative; overflow: hidden; }
  & i::after { content: ""; position: absolute; inset: 0; width: calc(var(--w) * 100%); border-radius: 5px; background: var(--apt-split-accent); transform-origin: left; animation: apt-split-grow .6s var(--apt-split-ease) both; }
  & b { font-weight: 650; }
}
@keyframes apt-split-grow { from { scale: 0 1; } }
.apt-split .apt-split-exf { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 6px; font-size: 11px; color: var(--apt-split-faint); font-variant-numeric: tabular-nums; }
.apt-split .apt-split-empty { padding: 30px 16px; text-align: center; color: var(--apt-split-mute); }

/* composer drawer over the list */
.apt-split .apt-split-compose {
  position: absolute; inset: 0; z-index: 20; display: flex; flex-direction: column; background: var(--apt-split-bg);
  transition: translate .45s var(--apt-split-spring), opacity .25s; @starting-style { translate: 0 18px; opacity: 0; }
  &[hidden] { display: none; }
  & > header { display: flex; justify-content: space-between; align-items: center; padding: 14px 16px; border-bottom: 1px solid var(--apt-split-line); & h3 { font-size: 15px; font-weight: 800; } }
  & > footer { display: flex; gap: 8px; padding: 12px 16px; border-top: 1px solid var(--apt-split-line); & .apt-split-btn { flex: 1; } }
}
.apt-split .apt-split-cbody { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; display: grid; align-content: start; gap: 10px; padding: 14px 16px; }
.apt-split .apt-split-fld {
  display: grid; gap: 3px; flex: 1;
  & > span { font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--apt-split-mute); }
  & input { width: 100%; padding: 8px 10px; border: 0; border-radius: 10px; background: var(--apt-split-surface); box-shadow: inset 0 0 0 1px var(--apt-split-line2); }
  & input[aria-invalid="true"] { box-shadow: inset 0 0 0 1.5px var(--apt-split-neg); }
  & em { font-style: normal; font-size: 11px; color: var(--apt-split-mute); min-height: 15px; font-variant-numeric: tabular-nums; }
  &:has([aria-invalid="true"]) em { color: var(--apt-split-neg); }
}
.apt-split .apt-split-amtrow { display: flex; gap: 8px; align-items: center; & .apt-split-fld input { font-size: 16px; font-weight: 750; font-variant-numeric: tabular-nums; } }
.apt-split .apt-split-seg {
  display: inline-flex; padding: 2px; border-radius: 10px; background: var(--apt-split-surface); box-shadow: inset 0 0 0 1px var(--apt-split-line2); flex: none;
  & button { padding: 6px 10px; border: 0; border-radius: 8px; background: none; font-weight: 650; font-size: 12px; color: var(--apt-split-mute); }
  & button[aria-checked="true"] { background: var(--apt-split-ink); color: var(--apt-split-bg); }
  &.is-sm { margin-left: 8px; letter-spacing: 0; text-transform: none; & button { padding: 3px 8px; font-size: 11.5px; } }
}
.apt-split .apt-split-lab { display: flex; align-items: center; font-size: 10.5px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--apt-split-mute); }
.apt-split .apt-split-chips {
  display: flex; flex-wrap: wrap; gap: 4px;
  & button { display: inline-flex; align-items: center; gap: 5px; padding: 3px 10px 3px 4px; border: 0; border-radius: 99px; background: none; box-shadow: inset 0 0 0 1px var(--apt-split-line2); font-size: 12px; font-weight: 600; }
  & button[aria-checked="true"] { box-shadow: inset 0 0 0 2px var(--apt-split-accent); background: color-mix(in oklab, var(--apt-split-accent) 12%, transparent); }
}
.apt-split .apt-split-parts {
  display: grid; gap: 3px;
  & li { display: grid; grid-template-columns: auto 1fr auto; align-items: center; gap: 8px; padding: 3px 4px; border-radius: 10px; }
  & li.is-on { background: var(--apt-split-surface); }
  & li > small { color: var(--apt-split-faint); font-size: 11.5px; }
  & li > b { min-width: 64px; text-align: right; font-size: 12px; font-variant-numeric: tabular-nums; color: var(--apt-split-accent); }
  & input { width: 76px; padding: 4px 8px; border: 0; border-radius: 8px; background: var(--apt-split-bg); box-shadow: inset 0 0 0 1px var(--apt-split-line2); text-align: right; font-variant-numeric: tabular-nums; }
}
.apt-split .apt-split-pt { min-width: 92px; display: inline-flex; align-items: center; gap: 6px; padding: 2px 8px 2px 2px; border: 0; border-radius: 99px; background: none; font-weight: 600; text-align: left; &[aria-pressed="false"] { opacity: .5; } &[aria-pressed="false"] .apt-split-av { filter: grayscale(1); } }
.apt-split .apt-split-step { display: inline-flex; align-items: center; gap: 2px; & button { display: grid; place-items: center; width: 22px; height: 22px; border: 0; border-radius: 7px; background: var(--apt-split-raised); } & button:disabled { opacity: .3; } & svg { width: 12px; height: 12px; stroke-width: 2.4; } & output { min-width: 18px; text-align: center; font-weight: 750; } }
.apt-split .apt-split-remain { display: flex; gap: 6px; align-items: center; font-size: 12px; color: var(--apt-split-accent); font-variant-numeric: tabular-nums; &.is-off { color: var(--apt-split-neg); } & svg { width: 14px; height: 14px; } }
.apt-split .apt-split-ferr { font-style: normal; font-size: 12px; color: var(--apt-split-neg); &:empty { display: none; } }
.apt-split .apt-split-catsel select { appearance: none; height: 100%; padding: 0 12px; border: 0; border-radius: 10px; background: var(--apt-split-surface); box-shadow: inset 0 0 0 1px var(--apt-split-line2); font-weight: 600; font-size: 12px; cursor: pointer; }

/* ── balances ── */
.apt-split .apt-split-mh, .apt-split .apt-split-gh, .apt-split .apt-split-rh {
  display: flex; align-items: baseline; justify-content: space-between; gap: 10px;
  & h3 { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--apt-split-mute); }
  & p { display: inline-flex; align-items: center; gap: 4px; font-size: 11.5px; color: var(--apt-split-faint); font-variant-numeric: tabular-nums; } & p svg { width: 13px; height: 13px; color: var(--apt-split-accent); }
}
.apt-split .apt-split-bars { display: grid; gap: 4px; }
.apt-split .apt-split-bar {
  --v: 0; display: grid; grid-template-columns: auto 92px minmax(0, 1fr) 84px; align-items: center; gap: 10px; padding: 5px 8px; border: 0; border-radius: 12px; background: none; text-align: left; transition: background .2s;
  &:hover { background: var(--apt-split-surface); }
