.apt-split .apt-split-bn { display: grid; line-height: 1.2; & b { font-weight: 700; } & b small { font-size: 10px; font-weight: 600; padding: 0 5px; border-radius: 99px; background: var(--apt-split-line); color: var(--apt-split-mute); } & > small { font-size: 11px; color: var(--apt-split-faint); } }
