  & .apt-split-node.is-pos circle { stroke: var(--apt-split-accent); } & .apt-split-node.is-neg circle { stroke: var(--apt-split-neg); }
  & .apt-split-node.is-sel circle, & .apt-split-node:focus-visible circle { r: 22px; stroke: var(--apt-split-ink); }
