.apt-split .apt-split-square { display: grid; justify-items: center; gap: 4px; padding: 30px 10px; text-align: center; color: var(--apt-split-mute); & svg { width: 30px; height: 30px; color: var(--apt-split-accent); stroke-width: 2.4; } & b { color: var(--apt-split-ink); } animation: apt-split-in .5s var(--apt-split-ease) both; }
