/* toast */
.apt-split .apt-split-toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50; translate: -50% 16px; opacity: 0; pointer-events: none; max-width: calc(100% - 32px);
  display: flex; align-items: center; gap: 10px; padding: 9px 12px 9px 14px; border-radius: 12px; background: var(--apt-split-ink); color: var(--apt-split-bg); font-weight: 600; font-size: 12.5px; box-shadow: 0 14px 30px -12px black;
