}
/* ── narrow ── */
@container (max-width: 759px) {
  .apt-split .apt-split-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "nav" "main"; }
  .apt-split .apt-split-nav {
    grid-area: nav; display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; padding: 8px 10px; border-bottom: 1px solid var(--apt-split-line);
