  .apt-split .apt-split-xfers { grid-template-columns: 1fr; }
  .apt-split .apt-split-keys { display: flex; flex-wrap: wrap; align-items: center; gap: 3px; font-size: 10.5px; color: var(--apt-split-faint); & kbd { font: 600 9.5px/1 var(--apt-split-mono); padding: 2px 4px; border: 1px solid currentColor; border-bottom-width: 2px; border-radius: 4px; } }
