/* ── Lofoten trip · expense splitter ─────────────────────────────────────
   Every amount is converted once to euro cents and every split — equal,
   shares or exact — is a weight vector allocated with the largest-remainder
   method, so each expense divides to the cent and the six balances always
   sum to exactly zero. "Simplify debts" swaps the pairwise IOUs for a greedy
   max-creditor / max-debtor plan of at most n − 1 payments. */
const P = 'apt-split';
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const RATE = 11.62;
const eur = c => (c < 0 ? '−' : '') + '€' + (Math.abs(c) / 100).toLocaleString('en-IE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const eur0 = c => '€' + Math.round(Math.abs(c) / 100).toLocaleString('en-IE');
const nok = v => 'NOK ' + v.toLocaleString('en-IE', { maximumFractionDigits: 2 });

const PEOPLE = [
  { id: 'ana', name: 'Ana', full: 'Ana Ferreira', h: 25, you: true },
  { id: 'ben', name: 'Ben', full: 'Ben Okafor', h: 75 },
  { id: 'chidi', name: 'Chidi', full: 'Chidi Mensah', h: 135 },
  { id: 'dana', name: 'Dana', full: 'Dana Kowalczyk', h: 190 },
  { id: 'emil', name: 'Emil', full: 'Emil Strøm', h: 250 },
  { id: 'farah', name: 'Farah', full: 'Farah Haddad', h: 320 }
];
const pp = id => PEOPLE.find(p => p.id === id);
const ALL = PEOPLE.map(p => p.id);
const CATS = { stay: 'Lodging', car: 'Transport', food: 'Food & drink', fun: 'Activities', other: 'Other', settle: 'Settlement' };
let seq = 0;
const E = (title, cat, payer, amt, cur, mode, among, w, day) => ({ id: 'e' + (++seq), title, cat, payer, amt, cur, mode, among, w: w || null, day });
const S = {
  ex: [
    E('Cabin in Reine, 3 nights', 'stay', 'ana', 14880, 'NOK', 'equal', ALL, null, 'Mon 12'),
    E('7-seat rental car', 'car', 'ben', 486, 'EUR', 'equal', ALL, null, 'Mon 12'),
    E('Ferry Bodø → Moskenes', 'car', 'emil', 3420, 'NOK', 'equal', ALL, null, 'Mon 12'),
    E('Groceries, Leknes market', 'food', 'dana', 2316, 'NOK', 'equal', ALL, null, 'Tue 13'),
    E('Fuel, Svolvær', 'car', 'chidi', 1240, 'NOK', 'equal', ALL, null, 'Tue 13'),
    E('Fish dinner (Ben skipped)', 'food', 'farah', 4950, 'NOK', 'equal', ['ana', 'chidi', 'dana', 'emil', 'farah'], null, 'Tue 13'),
    E('Sea kayak tour', 'fun', 'ana', 360, 'EUR', 'exact', ['ana', 'chidi', 'dana', 'farah'], { ana: 90, chidi: 90, dana: 90, farah: 90 }, 'Wed 14'),
    E('Wine and beer', 'food', 'ben', 1680, 'NOK', 'shares', ALL, { ana: 1, ben: 2, chidi: 1, dana: 1, emil: 2, farah: 1 }, 'Wed 14'),
    E('Floating sauna', 'fun', 'dana', 900, 'NOK', 'equal', ['dana', 'emil', 'farah'], null, 'Thu 15'),
    E('Parking and tolls', 'car', 'chidi', 610, 'NOK', 'equal', ALL, null, 'Fri 16'),
    E('Bakery breakfast', 'food', 'emil', 1140, 'NOK', 'equal', ALL, null, 'Sat 17'),
    E('Reinebringen guide', 'fun', 'farah', 240, 'EUR', 'equal', ALL, null, 'Sat 17')
  ],
  who: 'all', open: null, simplify: true, pane: 'list', composing: false, draft: null, sel: null
};
let undoBuf = null;

/* ── money engine ── */
const cents = e => e.cur === 'EUR' ? Math.round(e.amt * 100) : Math.round(e.amt / RATE * 100);
function alloc(e) {
  const T = cents(e), ids = e.among;
  const w = ids.map(id => e.mode === 'equal' ? 1 : (e.w && e.w[id]) || 0), W = w.reduce((a, b) => a + b, 0) || 1;
  const raw = w.map(x => T * x / W), base = raw.map(Math.floor);
  let left = T - base.reduce((a, b) => a + b, 0);
  raw.map((r, i) => [r - base[i], i]).sort((a, b) => b[0] - a[0] || a[1] - b[1]).forEach(([, i]) => { if (left > 0) { base[i]++; left--; } });
  const out = {}; ids.forEach((id, i) => { out[id] = base[i]; });
  return out;
}
function balances() {
  const b = {}; ALL.forEach(id => { b[id] = 0; });
  S.ex.forEach(e => { const T = cents(e), sh = alloc(e); b[e.payer] += T; Object.keys(sh).forEach(id => { b[id] -= sh[id]; }); });
  return b;
}
function rawDebts() {
  const d = {};
  S.ex.forEach(e => { const sh = alloc(e); Object.keys(sh).forEach(id => { if (id === e.payer || !sh[id]) return; const k = id + '>' + e.payer; d[k] = (d[k] || 0) + sh[id]; }); });
  const out = [];
  ALL.forEach((a, i) => ALL.slice(i + 1).forEach(b => {
    const n = (d[a + '>' + b] || 0) - (d[b + '>' + a] || 0);
    if (n > 0) out.push({ from: a, to: b, c: n }); else if (n < 0) out.push({ from: b, to: a, c: -n });
  }));
  return out.sort((x, y) => y.c - x.c);
}
function simplified() {
  const b = balances(), cr = [], db = [], out = [];
  ALL.forEach(id => { if (b[id] > 0) cr.push([id, b[id]]); else if (b[id] < 0) db.push([id, -b[id]]); });
  while (cr.length && db.length) {
    cr.sort((x, y) => y[1] - x[1]); db.sort((x, y) => y[1] - x[1]);
    const c = cr[0], d = db[0], m = Math.min(c[1], d[1]);
    out.push({ from: d[0], to: c[0], c: m });
    c[1] -= m; d[1] -= m;
    if (!c[1]) cr.shift(); if (!d[1]) db.shift();
  }
  return out;
}
const plan = () => S.simplify ? simplified() : rawDebts();

/* ── icons ── */
const I = {
  stay: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 11 12 4l9 7M5 9.5V20h14V9.5M10 20v-5h4v5"/></svg>',
  car: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 16v-4l2-5h12l2 5v4zM4 16v2.5M20 16v2.5"/><circle cx="8" cy="13.5" r="1"/><circle cx="16" cy="13.5" r="1"/></svg>',
  food: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3v8M5 3v5a2 2 0 0 0 4 0V3M7 11v10M17 21V3c-2.5 1.5-4 4-4 8h4"/></svg>',
  fun: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m3 19 6-11 4 6 2.5-3.5L21 19z"/><circle cx="17" cy="6" r="1.8"/></svg>',
  other: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="6" cy="12" r="1.3"/><circle cx="12" cy="12" r="1.3"/><circle cx="18" cy="12" r="1.3"/></svg>',
  settle: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 8h13l-3-3M20 16H7l3 3"/></svg>',
  check: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.2 4.2L19 7"/></svg>',
  x: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 7l10 10M17 7 7 17"/></svg>',
  trash: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 7h14M10 7V5h4v2M7 7l1 12h8l1-12"/></svg>',
  arrow: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15M14 7l5 5-5 5"/></svg>',
  minus: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M6 12h12"/></svg>',
  plus: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 6v12M6 12h12"/></svg>'
};
const av = (id, sm) => '<span class="' + P + '-av' + (sm ? ' is-sm' : '') + '" style="--h:' + pp(id).h + '" aria-hidden="true">' + pp(id).name[0] + '</span>';

/* ── left: expenses ── */
function renderHead() {
  const spend = S.ex.filter(e => e.cat !== 'settle'), T = spend.reduce((a, e) => a + cents(e), 0);
  $('[data-total]').innerHTML = eur(T) + ' <small>spent</small>';
  const mine = spend.reduce((a, e) => a + (alloc(e).ana || 0), 0);
  $('[data-sub]').innerHTML = spend.length + ' expenses · your share ' + eur(mine) + ' · ' + eur(Math.round(T / 6)) + ' a head on average';
  $('[data-whos]').innerHTML = [['all', 'Everyone']].concat(PEOPLE.map(p => [p.id, p.name])).map(([id, n]) => '<button type="button" role="radio" data-who="' + id + '" aria-checked="' + (S.who === id) + '" tabindex="' + (S.who === id ? 0 : -1) + '">' + (id === 'all' ? '' : av(id, true)) + n + '</button>').join('');
}
function renderList(anim) {
  const list = $('[data-list]');
  const items = S.ex.filter(e => S.who === 'all' || e.payer === S.who || e.among.includes(S.who)).slice().reverse();
  const before = new Map(); $$('[data-k]', list).forEach(n => before.set(n.dataset.k, n.getBoundingClientRect()));
  const af = doc.activeElement, fk = af && list.contains(af) && af.closest('[data-k]') ? [af.closest('[data-k]').dataset.k, af.dataset.f] : null;
  list.innerHTML = items.map((e, i) => {
    const T = cents(e), sh = alloc(e), open = S.open === e.id, me = S.who === 'all' ? 'ana' : S.who;
    const mine = sh[me] || 0, paid = e.payer === me ? T : 0, net = paid - mine;
    const settle = e.cat === 'settle';
    const note = settle ? pp(e.payer).name + ' paid ' + pp(e.among[0]).name : (e.mode === 'equal' ? (e.among.length === 6 ? 'split 6 ways' : 'split ' + e.among.length + ' ways') : e.mode === 'shares' ? 'by shares' : 'exact amounts');
    const right = settle ? '<em class="is-settle">settled</em>' : net > 0 ? '<em class="is-pos">' + (me === 'ana' ? 'you lent ' : pp(me).name + ' lent ') + eur(net) + '</em>' : mine ? '<em class="is-neg">' + (me === 'ana' ? 'your share ' : pp(me).name + '’s share ') + eur(mine) + '</em>' : '<em>not involved</em>';
    return '<li class="' + P + '-ex' + (open ? ' is-open' : '') + (settle ? ' is-settle' : '') + (anim && !before.has(e.id) ? ' is-new' : '') + '" data-k="' + e.id + '" style="--i:' + Math.min(i, 10) + '">' +
      '<button type="button" class="' + P + '-exrow" data-open="' + e.id + '" data-f="row" aria-expanded="' + open + '"><span class="' + P + '-cat is-' + e.cat + '">' + I[e.cat] + '</span>' +
        '<span class="' + P + '-exm"><b>' + esc(e.title) + '</b><small>' + e.day + ' · ' + pp(e.payer).name + ' paid ' + (e.cur === 'NOK' ? nok(e.amt) : eur(T)) + ' · ' + note + '</small></span>' +
        '<span class="' + P + '-exa"><b>' + eur(T) + '</b>' + right + '</span></button>' +
