  --apt-desk-wash: color-mix(in oklab, var(--apt-desk-ink) 3.5%, var(--apt-desk-bg));
  --apt-desk-line: color-mix(in oklab, var(--apt-desk-ink) 10%, transparent);
  --apt-desk-line2: color-mix(in oklab, var(--apt-desk-ink) 19%, transparent);
  --apt-desk-mute: color-mix(in oklab, var(--apt-desk-ink) 58%, var(--apt-desk-bg));
  --apt-desk-faint: color-mix(in oklab, var(--apt-desk-ink) 34%, var(--apt-desk-bg));
  --apt-desk-warnink: color-mix(in oklab, var(--apt-desk-warn) 60%, var(--apt-desk-ink));
  --apt-desk-mono: ui-monospace, Menlo, monospace;
  --apt-desk-ease: cubic-bezier(.2, .85, .25, 1);
  --apt-desk-spring: linear(0, .1 4%, .38 10%, .74 17%, .97 24%, 1.06 30%, 1.07 35%, 1.04 42%, 1.01 52%, .996 64%, 1);

  position: relative; width: 100%; height: var(--apt-desk-h, 680px);
  container-type: inline-size; overflow: clip; isolation: isolate; box-sizing: border-box;
  background: var(--apt-desk-bg); color: var(--apt-desk-ink); color-scheme: light; accent-color: var(--apt-desk-accent);
  font: 13px/1.45 system-ui, -apple-system, "Segoe UI", Roboto, sans-serif; border-radius: 16px; box-shadow: 0 0 0 1px var(--apt-desk-line); -webkit-tap-highlight-color: transparent;

  & *, & *::before, & *::after { box-sizing: border-box; }
  & :focus-visible { outline: 2px solid var(--apt-desk-ink); outline-offset: 2px; }
  & button, & input, & textarea { font: inherit; color: inherit; }
  & button { cursor: pointer; }
  & button:disabled { cursor: not-allowed; }
  & h2, & h3, & h4, & p, & ol, & ul { margin: 0; padding: 0; }
  & ol, & ul { list-style: none; }
  & table { border-collapse: collapse; width: 100%; }
  & svg { width: 16px; height: 16px; fill: none; stroke: currentColor; stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; flex: none; }
  & kbd { font: 600 9.5px/1 var(--apt-desk-mono); padding: 2px 4px; display: inline-block; border: 1px solid currentColor; border-bottom-width: 2px; border-radius: 4px; opacity: .55; }
}

/* ── shell ── */
.apt-desk .apt-desk-app { height: 100%; display: grid; grid-template-columns: 312px minmax(0, 1fr) 300px; grid-template-rows: minmax(0, 1fr); grid-template-areas: "queue detail budget"; }
.apt-desk .apt-desk-nav { display: none; }
.apt-desk .apt-desk-queue { grid-area: queue; min-height: 0; display: flex; flex-direction: column; border-right: 1px solid var(--apt-desk-line); background: var(--apt-desk-wash); }
.apt-desk .apt-desk-detail { grid-area: detail; min-height: 0; overflow-y: auto; scrollbar-width: thin; background: var(--apt-desk-surface); }
.apt-desk .apt-desk-budget { grid-area: budget; min-height: 0; overflow-y: auto; scrollbar-width: none; display: flex; flex-direction: column; gap: 14px; padding: 18px 16px; border-left: 1px solid var(--apt-desk-line); }
.apt-desk .apt-desk-budget > * { flex: none; }

/* queue */
.apt-desk .apt-desk-qh { display: grid; gap: 10px; padding: 16px 14px 10px; & h2 { font-size: 24px; font-weight: 800; letter-spacing: -.03em; line-height: 1; } }
.apt-desk .apt-desk-org { display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 700; & small { font-weight: 500; color: var(--apt-desk-mute); } }
.apt-desk .apt-desk-logo { display: grid; place-items: center; width: 22px; height: 22px; border-radius: 6px; background: var(--apt-desk-ink); color: var(--apt-desk-bg); font-weight: 800; font-size: 12px; }
.apt-desk .apt-desk-tabs {
  display: grid; grid-template-columns: repeat(3, 1fr); padding: 3px; border-radius: 10px; background: var(--apt-desk-line);
  & button { display: inline-flex; align-items: center; justify-content: center; gap: 5px; padding: 5px 4px; border: 0; border-radius: 8px; background: none; font-weight: 650; font-size: 12px; color: var(--apt-desk-mute); transition: background .2s, color .2s; }
  & small { font-size: 10.5px; font-variant-numeric: tabular-nums; padding: 0 5px; border-radius: 99px; background: var(--apt-desk-line); }
  & button[aria-selected="true"] { background: var(--apt-desk-surface); color: var(--apt-desk-ink); box-shadow: 0 1px 3px color-mix(in oklab, var(--apt-desk-ink) 16%, transparent); }
}
.apt-desk .apt-desk-search {
  display: flex; align-items: center; gap: 7px; padding: 0 8px 0 10px; border-radius: 10px; background: var(--apt-desk-surface); box-shadow: inset 0 0 0 1px var(--apt-desk-line2);
  & svg { color: var(--apt-desk-faint); } & input { flex: 1; min-width: 0; padding: 7px 0; border: 0; background: none; outline: none; } & input::-webkit-search-cancel-button { display: none; }
  &:focus-within { box-shadow: inset 0 0 0 1.5px var(--apt-desk-ink); }
}
.apt-desk .apt-desk-list { flex: 1; min-height: 0; overflow-y: auto; scrollbar-width: thin; display: grid; align-content: start; gap: 3px; padding: 4px 8px 10px; }
.apt-desk .apt-desk-item.is-new { animation: apt-desk-in .4s var(--apt-desk-ease) both; animation-delay: calc(var(--i) * 30ms); }
@keyframes apt-desk-in { from { opacity: 0; translate: 0 8px; } }
.apt-desk .apt-desk-row {
  position: relative; width: 100%; display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 10px; align-items: center; padding: 8px 10px; border: 0; border-radius: 12px; background: none; text-align: left; transition: background .2s, box-shadow .2s;
  &:hover { background: var(--apt-desk-surface); }
  &.is-sel { background: var(--apt-desk-surface); box-shadow: 0 0 0 1px var(--apt-desk-line2), 0 6px 14px -10px color-mix(in oklab, var(--apt-desk-ink) 50%, transparent); }
  &.is-sel::before { content: ""; position: absolute; left: -8px; top: 12px; bottom: 12px; width: 3px; border-radius: 0 3px 3px 0; background: var(--apt-desk-ink); }
}
.apt-desk .apt-desk-av { display: grid; place-items: center; width: 32px; height: 32px; border-radius: 50%; background: oklch(0.88 0.06 var(--h)); color: oklch(0.32 0.08 var(--h)); font-weight: 750; font-size: 11.5px; letter-spacing: .02em; flex: none; &.is-lg { width: 46px; height: 46px; font-size: 15px; } }
.apt-desk .apt-desk-rm { min-width: 0; display: grid; & b { font-weight: 650; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; } & small { font-size: 11.5px; color: var(--apt-desk-mute); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-variant-numeric: tabular-nums; } }
.apt-desk .apt-desk-rt {
  display: grid; justify-items: end; line-height: 1.25; font-variant-numeric: tabular-nums;
  & b { font-weight: 750; }
  & em { display: inline-flex; align-items: center; gap: 3px; font-style: normal; font-size: 10.5px; font-weight: 650; }
  & em svg { width: 11px; height: 11px; stroke-width: 2.4; }
  & .is-pass, & .is-approved { color: var(--apt-desk-accent); } & .is-warn, & .is-changes { color: var(--apt-desk-warnink); } & .is-fail, & .is-rejected { color: var(--apt-desk-bad); }
}
.apt-desk .apt-desk-empty { display: grid; justify-items: center; gap: 4px; padding: 40px 16px; text-align: center; color: var(--apt-desk-mute); & b { color: var(--apt-desk-ink); font-size: 14px; } }
.apt-desk .apt-desk-qf { display: flex; flex-wrap: wrap; align-items: center; gap: 8px; padding: 10px 12px; border-top: 1px solid var(--apt-desk-line); }
.apt-desk .apt-desk-keys { display: inline-flex; align-items: center; gap: 3px; font-size: 10.5px; color: var(--apt-desk-faint); margin-left: auto; }
.apt-desk .apt-desk-chip { padding: 4px 9px; border: 0; border-radius: 99px; background: var(--apt-desk-ink); color: var(--apt-desk-bg); font-size: 11.5px; font-weight: 650; }
.apt-desk .apt-desk-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 6px; padding: 7px 12px; border: 0; border-radius: 10px; font-weight: 700; font-size: 12.5px; white-space: nowrap;
  background: var(--apt-desk-surface); box-shadow: inset 0 0 0 1px var(--apt-desk-line2); transition: background .2s, color .2s, box-shadow .2s, scale .25s var(--apt-desk-spring);
  &:hover:not(:disabled) { box-shadow: inset 0 0 0 1.5px var(--apt-desk-ink); }
  &:active:not(:disabled) { scale: .97; }
  &:disabled { opacity: .4; }
  & svg { width: 14px; height: 14px; stroke-width: 2.3; }
  & kbd { opacity: .6; margin-left: 2px; }
  &.is-good { background: var(--apt-desk-accent); color: white; box-shadow: none; &:hover:not(:disabled) { background: color-mix(in oklab, var(--apt-desk-accent) 85%, black); } }
  &.is-warn { background: color-mix(in oklab, var(--apt-desk-warn) 22%, var(--apt-desk-surface)); color: var(--apt-desk-warnink); box-shadow: inset 0 0 0 1px color-mix(in oklab, var(--apt-desk-warn) 55%, transparent); }
  &.is-bad { color: var(--apt-desk-bad); }
  &.is-bad:hover:not(:disabled) { box-shadow: inset 0 0 0 1.5px var(--apt-desk-bad); }
}

/* detail */
.apt-desk .apt-desk-dwrap { display: grid; gap: 16px; padding: 20px 24px 24px; animation: apt-desk-swap .4s var(--apt-desk-ease) both; }
@keyframes apt-desk-swap { from { opacity: 0; translate: 8px 0; } }
.apt-desk .apt-desk-back { display: none; }
.apt-desk .apt-desk-none { display: grid; place-content: center; justify-items: center; gap: 4px; height: 100%; color: var(--apt-desk-mute); & b { color: var(--apt-desk-ink); font-size: 15px; } }
.apt-desk .apt-desk-dh {
  display: grid; grid-template-columns: auto 1fr auto; gap: 14px; align-items: center;
  & h2 { font-size: clamp(19px, 1.2cqi + 8px, 24px); font-weight: 800; letter-spacing: -.02em; line-height: 1.15; text-wrap: balance; }
  & p { font-size: 12px; color: var(--apt-desk-mute); }
}
.apt-desk .apt-desk-stat {
  padding: 5px 11px; border-radius: 99px; font-size: 11.5px; font-weight: 750; white-space: nowrap;
  &.is-pass, &.is-approved { background: color-mix(in oklab, var(--apt-desk-accent) 14%, transparent); color: var(--apt-desk-accent); }
  &.is-warn, &.is-changes { background: color-mix(in oklab, var(--apt-desk-warn) 22%, transparent); color: var(--apt-desk-warnink); }
  &.is-fail, &.is-rejected { background: color-mix(in oklab, var(--apt-desk-bad) 12%, transparent); color: var(--apt-desk-bad); }
}
.apt-desk .apt-desk-trip { display: grid; gap: 3px; padding: 14px 16px; border-radius: 14px; background: var(--apt-desk-wash); & p { font-size: 12.5px; color: var(--apt-desk-mute); font-variant-numeric: tabular-nums; } }
.apt-desk .apt-desk-route { display: flex; align-items: center; gap: 10px; & b { font-size: 21px; font-weight: 800; letter-spacing: -.02em; } & svg { width: 20px; height: 20px; color: var(--apt-desk-faint); } }
.apt-desk .apt-desk-purpose { font-style: italic; text-wrap: pretty; }
.apt-desk .apt-desk-cost {
  & th { text-align: left; font-weight: 650; white-space: nowrap; padding: 8px 12px 8px 0; vertical-align: top; }
  & th svg { width: 14px; height: 14px; margin-right: 7px; vertical-align: -2px; color: var(--apt-desk-faint); }
  & td { padding: 8px 0; color: var(--apt-desk-mute); font-size: 12.5px; vertical-align: top; }
  & td:last-child { text-align: right; color: var(--apt-desk-ink); font-weight: 650; font-variant-numeric: tabular-nums; white-space: nowrap; padding-left: 12px; }
  & tbody tr + tr { border-top: 1px solid var(--apt-desk-line); }
  & tfoot { border-top: 2px solid var(--apt-desk-ink); } & tfoot th, & tfoot td { padding-top: 10px; font-size: 15px; font-weight: 800; color: var(--apt-desk-ink); }
}
.apt-desk .apt-desk-checks {
  display: grid; gap: 8px;
  & h3 { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--apt-desk-mute); } & h3 small { margin-left: 6px; letter-spacing: 0; text-transform: none; font-weight: 500; color: var(--apt-desk-faint); }
  & ul { display: grid; gap: 4px; }
  & li { display: grid; grid-template-columns: auto 92px 1fr; gap: 10px; align-items: start; padding: 8px 10px; border-radius: 10px; font-size: 12.5px; animation: apt-desk-in .4s var(--apt-desk-ease) both; animation-delay: calc(var(--i) * 45ms); }
  & li svg { width: 16px; height: 16px; stroke-width: 2.2; margin-top: 1px; }
  & li b { font-weight: 650; } & li span { color: var(--apt-desk-mute); text-wrap: pretty; font-variant-numeric: tabular-nums; }
  & li.is-pass svg { color: var(--apt-desk-accent); }
  & li.is-warn { background: color-mix(in oklab, var(--apt-desk-warn) 13%, transparent); & svg { color: var(--apt-desk-warnink); } & span { color: var(--apt-desk-warnink); } }
  & li.is-fail { background: color-mix(in oklab, var(--apt-desk-bad) 8%, transparent); & svg, & span { color: var(--apt-desk-bad); } }
}
.apt-desk .apt-desk-act { position: sticky; bottom: 0; z-index: 2; display: grid; gap: 10px; margin: 0 -24px -24px; padding: 12px 24px 18px; background: color-mix(in oklab, var(--apt-desk-surface) 92%, transparent); backdrop-filter: blur(8px); border-top: 1px solid var(--apt-desk-line); }
.apt-desk .apt-desk-note {
  display: grid; gap: 4px;
  & > span { font-size: 12px; font-weight: 650; } & > span small { font-weight: 450; color: var(--apt-desk-faint); margin-left: 4px; }
  & textarea { width: 100%; resize: vertical; min-height: 38px; padding: 8px 10px; border: 0; border-radius: 10px; background: var(--apt-desk-wash); box-shadow: inset 0 0 0 1px var(--apt-desk-line2); }
  & textarea:focus-visible { outline: none; box-shadow: inset 0 0 0 1.5px var(--apt-desk-ink); }
  & textarea[aria-invalid="true"] { box-shadow: inset 0 0 0 1.5px var(--apt-desk-bad); }
  & em { font-style: normal; font-size: 11.5px; color: var(--apt-desk-bad); } & em:empty { display: none; }
}
.apt-desk .apt-desk-btns { display: flex; flex-wrap: wrap; gap: 6px; }
.apt-desk .apt-desk-decided { display: flex; align-items: center; justify-content: space-between; gap: 10px; padding: 12px 14px; border-radius: 12px; background: var(--apt-desk-wash); & p { color: var(--apt-desk-mute); text-wrap: pretty; } }

/* budget */
.apt-desk .apt-desk-eyebrow { font-size: 10.5px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; color: var(--apt-desk-mute); }
.apt-desk .apt-desk-bh { & h3 { font-size: 28px; font-weight: 800; letter-spacing: -.03em; line-height: 1.1; font-variant-numeric: tabular-nums; } & h3 small { font-size: 12px; font-weight: 500; letter-spacing: 0; color: var(--apt-desk-mute); } }
.apt-desk .apt-desk-bsub { font-size: 12px; color: var(--apt-desk-mute); font-variant-numeric: tabular-nums; text-wrap: pretty; }
.apt-desk .apt-desk-bar {
  position: relative; height: 16px; border-radius: 6px; background: var(--apt-desk-line); overflow: visible;
  & i { position: absolute; top: 0; bottom: 0; transition: left .7s var(--apt-desk-ease), width .7s var(--apt-desk-ease); }
  & .is-spent { background: var(--apt-desk-ink); border-radius: 6px 0 0 6px; }
  & .is-com { background: color-mix(in oklab, var(--apt-desk-ink) 55%, var(--apt-desk-bg)); }
  & .is-appr { background: var(--apt-desk-accent); }
  & .is-pen { background: repeating-linear-gradient(135deg, color-mix(in oklab, var(--apt-desk-warn) 70%, transparent) 0 3px, color-mix(in oklab, var(--apt-desk-warn) 30%, transparent) 3px 6px); }
  & > b { position: absolute; top: -5px; bottom: -5px; width: 2px; border-radius: 2px; background: var(--apt-desk-bad); translate: -1px 0; transition: left .7s var(--apt-desk-ease); }
}
.apt-desk .apt-desk-leg {
  display: grid; grid-template-columns: 1fr 1fr; gap: 4px 12px; margin-top: 8px; font-size: 11.5px;
  & li { display: flex; justify-content: space-between; gap: 6px; color: var(--apt-desk-mute); } & b { color: var(--apt-desk-ink); font-variant-numeric: tabular-nums; }
  & li span::before { content: ""; display: inline-block; width: 8px; height: 8px; margin-right: 5px; border-radius: 2px; vertical-align: 0; }
  & .is-spent span::before { background: var(--apt-desk-ink); } & .is-com span::before { background: color-mix(in oklab, var(--apt-desk-ink) 55%, var(--apt-desk-bg)); } & .is-appr span::before { background: var(--apt-desk-accent); } & .is-pen span::before { background: var(--apt-desk-warn); }
}
.apt-desk .apt-desk-chart {
  display: grid; gap: 6px; padding: 12px; border-radius: 14px; background: var(--apt-desk-surface); box-shadow: inset 0 0 0 1px var(--apt-desk-line);
  & header { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: 6px; } & h4 { font-size: 12px; font-weight: 700; }
}
.apt-desk .apt-desk-sw {
  display: inline-flex; align-items: center; gap: 6px; padding: 0; border: 0; background: none; font-size: 11px; font-weight: 600; color: var(--apt-desk-mute);
  & i { position: relative; width: 26px; height: 15px; border-radius: 99px; background: var(--apt-desk-line2); transition: background .25s; }
  & i::after { content: ""; position: absolute; left: 2px; top: 2px; width: 11px; height: 11px; border-radius: 50%; background: white; transition: translate .35s var(--apt-desk-spring); }
  &[aria-checked="true"] i { background: var(--apt-desk-warn); } &[aria-checked="true"] i::after { translate: 11px 0; }
}
.apt-desk .apt-desk-svg {
  width: 100%; height: auto;
  & text { stroke: none; font: 500 9px system-ui, sans-serif; fill: var(--apt-desk-faint); font-variant-numeric: tabular-nums; }
  & .apt-desk-yl { text-anchor: end; } & .apt-desk-xl { text-anchor: middle; }
  & .apt-desk-gl { stroke: var(--apt-desk-line); stroke-width: 1; }
  & .apt-desk-limit { stroke: var(--apt-desk-bad); stroke-width: 1.5; stroke-dasharray: 4 3; }
  & .apt-desk-bl { text-anchor: end; fill: var(--apt-desk-bad); font-weight: 700; }
  & .apt-desk-area { fill: color-mix(in oklab, var(--apt-desk-accent) 16%, transparent); stroke: none; transition: d .8s var(--apt-desk-ease); }
  & .apt-desk-line { fill: none; stroke: var(--apt-desk-accent); stroke-width: 2.2; transition: d .8s var(--apt-desk-ease); }
  & .apt-desk-ghost { fill: none; stroke: var(--apt-desk-warnink); stroke-width: 1.6; stroke-dasharray: 3 3; opacity: 0; transition: d .8s var(--apt-desk-ease), opacity .3s; }
  &.is-ghost .apt-desk-ghost { opacity: 1; }
  & .apt-desk-now { stroke: var(--apt-desk-line2); stroke-dasharray: 2 2; } & .apt-desk-nl { font-weight: 650; }
  & .apt-desk-end { fill: var(--apt-desk-surface); stroke: var(--apt-desk-accent); stroke-width: 2; transition: cy .8s var(--apt-desk-ease); &.is-over { stroke: var(--apt-desk-bad); } }
  & .apt-desk-el { text-anchor: end; font-weight: 750; fill: var(--apt-desk-ink); font-size: 9.5px; }
}
.apt-desk .apt-desk-cc { display: grid; gap: 2px; }
.apt-desk .apt-desk-cc li > button {
  width: 100%; display: grid; grid-template-columns: 112px 1fr 58px; gap: 8px; align-items: center; padding: 5px 6px; border: 0; border-radius: 9px; background: none; text-align: left; font-size: 12px; transition: background .2s;
  & span { display: grid; line-height: 1.2; font-weight: 600; } & span small { font: 500 10px var(--apt-desk-mono); color: var(--apt-desk-faint); }
  & i { position: relative; height: 8px; border-radius: 4px; background: var(--apt-desk-line); overflow: hidden; }
  & i::before { content: ""; position: absolute; inset: 0 auto 0 0; width: calc(var(--b) * 100%); background: color-mix(in oklab, var(--apt-desk-warn) 45%, transparent); border-radius: 4px; transition: width .7s var(--apt-desk-ease); }
  & i::after { content: ""; position: absolute; inset: 0 auto 0 0; width: calc(var(--a) * 100%); background: var(--apt-desk-ink); border-radius: 4px; transition: width .7s var(--apt-desk-ease); }
  & b { text-align: right; font-variant-numeric: tabular-nums; font-weight: 650; }
  &:hover { background: var(--apt-desk-wash); }
  &.is-on { background: var(--apt-desk-ink); color: var(--apt-desk-bg); & span small { color: color-mix(in oklab, var(--apt-desk-bg) 60%, transparent); } & i::after { background: var(--apt-desk-bg); } }
}

/* toast */
.apt-desk .apt-desk-toast {
  position: absolute; left: 50%; bottom: 18px; z-index: 50; translate: -50% 16px; opacity: 0; pointer-events: none; max-width: calc(100% - 32px);
  display: flex; align-items: center; gap: 10px; padding: 9px 12px 9px 14px; border-radius: 12px; background: var(--apt-desk-ink); color: var(--apt-desk-bg); font-weight: 600; font-size: 12.5px; box-shadow: 0 14px 30px -12px color-mix(in oklab, var(--apt-desk-ink) 70%, transparent);
  transition: opacity .25s, translate .5s var(--apt-desk-spring);
  &.is-on { opacity: 1; translate: -50% 0; pointer-events: auto; }
}
.apt-desk .apt-desk-tl { margin-left: 8px; padding: 3px 9px; border: 0; border-radius: 7px; background: color-mix(in oklab, var(--apt-desk-bg) 18%, transparent); color: var(--apt-desk-bg); font-weight: 750; font-size: 12px; }

/* ── medium ── */
@container (max-width: 1023px) {
