}
/* ── narrow ── */
@container (max-width: 759px) {
  .apt-desk .apt-desk-app { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); grid-template-areas: "nav" "main"; }
  .apt-desk .apt-desk-nav {
    grid-area: nav; display: grid; grid-template-columns: repeat(3, 1fr); gap: 4px; padding: 8px 10px; border-bottom: 1px solid var(--apt-desk-line);
    & button { padding: 8px 4px; border: 0; border-radius: 10px; background: none; font-weight: 650; color: var(--apt-desk-mute); }
    & button span { font-size: 11px; padding: 0 6px; border-radius: 99px; background: var(--apt-desk-line); } & button span:empty { display: none; }
    & button[aria-selected="true"] { background: var(--apt-desk-surface); color: var(--apt-desk-ink); box-shadow: 0 1px 3px color-mix(in oklab, var(--apt-desk-ink) 16%, transparent); }
  }
  .apt-desk .apt-desk-queue, .apt-desk .apt-desk-detail, .apt-desk .apt-desk-budget { grid-area: main; display: none; border: 0; max-height: none; }
  .apt-desk[data-pane="queue"] .apt-desk-queue { display: flex; }
  .apt-desk[data-pane="detail"] .apt-desk-detail { display: block; }
  .apt-desk[data-pane="budget"] .apt-desk-budget { display: flex; align-items: stretch; }
  .apt-desk .apt-desk-cc { display: grid; }
  .apt-desk .apt-desk-back { display: inline-flex; align-items: center; gap: 4px; justify-self: start; padding: 4px 8px 4px 4px; border: 0; border-radius: 8px; background: var(--apt-desk-wash); font-weight: 650; font-size: 12px; }
  .apt-desk .apt-desk-dwrap { padding: 14px 14px 20px; }
  .apt-desk .apt-desk-act { position: static; margin: 0 -14px -20px; padding: 12px 14px 16px; backdrop-filter: none; }
  .apt-desk .apt-desk-dh { grid-template-columns: auto 1fr; & .apt-desk-stat { grid-column: 1 / -1; justify-self: start; } }
  .apt-desk .apt-desk-checks li { grid-template-columns: auto 1fr; & span { grid-column: 2; } }
}

@media (prefers-reduced-motion: reduce) {
  .apt-desk {
    & *, & *::before, & *::after { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; transition-delay: 0s !important; animation-delay: 0s !important; }
  }
}

js:
/* ── Fernhill travel desk · approvals with a policy engine ──────────────
   Each request is costed from its parts (fare + nights × rate + per diem
   days × city rate + ground) and run through the written policy: cabin by
   flight time, advance purchase, hotel caps by city, fare type and carrier,
   and the effect on the Q4 budget. Approving moves the request's total into
   "committed" at its travel week, so the stacked bar, the cumulative chart
   (whose path morphs with a CSS d transition) and the team totals all move
   together. */
const P = 'apt-desk';
const doc = root.ownerDocument;
const $ = (s, el = root) => el.querySelector(s);
const $$ = (s, el = root) => Array.from(el.querySelectorAll(s));
const RM = matchMedia('(prefers-reduced-motion: reduce)');
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => '&#' + c.charCodeAt(0) + ';');
const eur = n => '€' + Math.round(n).toLocaleString('en-IE');
const DAY = 864e5, D = (m, d) => Math.round(Date.UTC(2026, m - 1, d) / DAY), TODAY = D(10, 2);
const WD = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'], MO = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
const fd = n => { const t = new Date(n * DAY); return WD[t.getUTCDay()] + ' ' + t.getUTCDate() + ' ' + MO[t.getUTCMonth()]; };
const fds = n => { const t = new Date(n * DAY); return t.getUTCDate() + ' ' + MO[t.getUTCMonth()]; };
const hmin = m => Math.floor(m / 60) + 'h ' + String(m % 60).padStart(2, '0');

/* ── policy ── */
const CITY = { London: [210, 65], Berlin: [150, 50], Lisbon: [140, 45], 'New York': [290, 75], Singapore: [230, 60], Copenhagen: [190, 60], Madrid: [150, 50] };
const PREFERRED = ['Corvid Air', 'Tern Atlantic'];
const BUDGET = 48000, SPENT = 3180;
const W0 = D(9, 28), WEEKS = 14;
const COMMITTED = [0, 2840, 3120, 1980, 2460, 3300, 1560, 2210, 1890, 2280, 0, 0, 0, 0];
const TEAMS = { 'Client Services': 'CC-210', Product: 'CC-140', Sales: 'CC-310', Partnerships: 'CC-330', Engineering: 'CC-120', Finance: 'CC-500' };
const TEAM_BASE = { 'Client Services': 6420, Product: 5180, Sales: 5960, Partnerships: 2890, Engineering: 3240, Finance: 1130 };   /* spent + committed so far: sums to 24,820 */
const R = (id, name, role, team, from, to, dep, ret, purpose, fl, ho, ground, sub) => ({ id, name, role, team, from, to, dep, ret, purpose, fl, ho, ground, sub, status: 'pending', note: '' });
const REQ = [
  R('r1', 'Jonas Weber', 'Senior Consultant', 'Client Services', 'Berlin', 'London', D(11, 3), D(11, 5), 'Northgate Retail discovery workshop', { al: 'Corvid Air', cls: 'Economy', fare: 312, mins: 115 }, { name: 'The Ropemaker, Shoreditch', rate: 238 }, 60, 'Thu 1 Oct'),
  R('r2', 'Amara Diallo', 'Product Manager', 'Product', 'Lisbon', 'New York', D(11, 9), D(11, 13), 'Speaking at Signal & Noise conference', { al: 'Tern Atlantic', cls: 'Premium economy', fare: 1840, mins: 460 }, { name: 'Harbor & Pine, Midtown', rate: 276 }, 120, 'Thu 1 Oct'),
  R('r3', 'Leo Martins', 'Account Executive', 'Sales', 'Lisbon', 'Madrid', D(10, 7), D(10, 7), 'Renewal meeting, Valcarce Foods', { al: 'Brisa', cls: 'Economy', fare: 286, mins: 80, alt: ['Tern Atlantic', 262] }, null, 45, 'Fri 2 Oct'),
  R('r4', 'Sofia Ricci', 'Partnerships Lead', 'Partnerships', 'Berlin', 'Singapore', D(11, 16), D(11, 21), 'APAC partner offsite', { al: 'Corvid Air', cls: 'Business', fare: 4920, mins: 770, alt: ['Corvid Air premium economy', 2380] }, { name: 'Keong Saik Rooms', rate: 244 }, 140, 'Wed 30 Sep'),
  R('r5', 'Tomás Ortega', 'Data Engineer', 'Engineering', 'Madrid', 'Copenhagen', D(10, 26), D(10, 28), 'Data platform summit', { al: 'Brisa', cls: 'Economy', fare: 198, mins: 190, alt: ['Tern Atlantic', 214] }, { name: 'Nyhavn Quarter Hotel', rate: 176 }, 50, 'Thu 1 Oct'),
  R('r6', 'Hana Sato', 'UX Researcher', 'Product', 'London', 'Berlin', D(10, 20), D(10, 22), 'Usability sessions with pilot customers', { al: 'Tern Atlantic', cls: 'Economy', fare: 164, mins: 110 }, { name: 'Hotel Kastanie', rate: 132 }, 40, 'Tue 29 Sep'),
  R('r7', 'Mateo Rossi', 'Solutions Architect', 'Client Services', 'Lisbon', 'London', D(11, 12), D(11, 14), 'Northgate Retail architecture review', { al: 'Corvid Air', cls: 'Economy', fare: 520, mins: 155, flex: true, alt: ['Corvid Air basic fare', 310] }, { name: 'Fenwick House', rate: 205 }, 60, 'Thu 1 Oct'),
  R('r8', 'Ingrid Dahl', 'Engineering Manager', 'Engineering', 'Copenhagen', 'Lisbon', D(10, 26), D(10, 30), 'Engineering team offsite', { al: 'Tern Atlantic', cls: 'Economy', fare: 265, mins: 230 }, { name: 'Casa Ribeira', rate: 158 }, 70, 'Wed 30 Sep'),
  R('r9', 'Kwame Asante', 'Sales Director', 'Sales', 'Berlin', 'New York', D(12, 1), D(12, 6), 'Q1 pipeline review with US team', { al: 'Corvid Air', cls: 'Economy', fare: 980, mins: 530 }, { name: 'Harbor & Pine, Midtown', rate: 312 }, 150, 'Fri 2 Oct'),
  R('r10', 'Elena Petrova', 'Finance Analyst', 'Finance', 'London', 'Madrid', D(10, 12), D(10, 13), 'Quarter-close with the Madrid office', { al: 'Tern Atlantic', cls: 'Economy', fare: 142, mins: 140 }, { name: 'Hotel Alcalá 12', rate: 149 }, 40, 'Fri 2 Oct')
];
const nights = r => r.ret - r.dep;
const pdDays = r => nights(r) + 1;
function cost(r) {
  const n = nights(r), pd = CITY[r.to][1];
  const hotel = r.ho ? n * r.ho.rate : 0, per = pdDays(r) * pd;
  return { fare: r.fl.fare, hotel, n, rate: r.ho ? r.ho.rate : 0, per, pdRate: pd, days: pdDays(r), ground: r.ground, total: r.fl.fare + hotel + per + r.ground };
}
const weekOf = d => Math.max(0, Math.min(WEEKS - 1, Math.floor((d - W0) / 7)));
function committedNow() { return REQ.filter(r => r.status === 'approved').reduce((s, r) => s + cost(r).total, 0); }
function pendingNow() { return REQ.filter(r => r.status === 'pending').reduce((s, r) => s + cost(r).total, 0); }
function checks(r) {
  const c = cost(r), out = [];
  const cap = CITY[r.to][0], lead = r.dep - TODAY, h = r.fl.mins;
  /* cabin */
  if (r.fl.cls === 'Economy') out.push(['pass', 'Cabin', 'Economy on a ' + hmin(h) + ' flight']);
  else if (r.fl.cls === 'Premium economy') out.push(h >= 360 ? ['pass', 'Cabin', 'Premium economy allowed over 6 h — this is ' + hmin(h)] : ['fail', 'Cabin', 'Premium economy needs 6 h+; this is ' + hmin(h)]);
  else out.push(h >= 540 ? ['warn', 'Cabin', 'Business allowed over 9 h with VP sign-off — ' + (r.fl.alt ? r.fl.alt[0] + ' is ' + eur(r.fl.alt[1]) : '') + ', ' + eur(r.fl.fare - (r.fl.alt ? r.fl.alt[1] : 0)) + ' less'] : ['fail', 'Cabin', 'Business needs a 9 h+ flight']);
  /* advance purchase */
  out.push(lead >= 14 ? ['pass', 'Booked ahead', lead + ' days before departure'] : lead >= 7 ? ['warn', 'Booked ahead', 'Only ' + lead + ' days ahead — policy asks for 14'] : ['fail', 'Booked ahead', lead + ' days ahead — under 7 needs a reason']);
  /* hotel */
  if (!r.ho) out.push(['pass', 'Hotel', 'Day trip, no hotel']);
  else { const over = (r.ho.rate - cap) / cap; out.push(over <= 0 ? ['pass', 'Hotel', eur(r.ho.rate) + '/night, cap in ' + r.to + ' is ' + eur(cap)] : over <= .25 ? ['warn', 'Hotel', eur(r.ho.rate) + '/night is ' + Math.round(over * 100) + '% over the ' + eur(cap) + ' ' + r.to + ' cap (+' + eur((r.ho.rate - cap) * c.n) + ')'] : ['fail', 'Hotel', eur(r.ho.rate) + '/night is ' + Math.round(over * 100) + '% over cap']); }
  /* fare + carrier */
  if (r.fl.flex) out.push(['warn', 'Fare', 'Flexible fare, ' + eur(r.fl.fare - r.fl.alt[1]) + ' more than the basic fare']);
  else if (!PREFERRED.includes(r.fl.al)) { const d = r.fl.fare - r.fl.alt[1]; out.push(d > 0 ? ['warn', 'Carrier', r.fl.al + ' is not preferred and costs ' + eur(d) + ' more than ' + r.fl.alt[0]] : ['pass', 'Carrier', r.fl.al + ' is ' + eur(-d) + ' cheaper than ' + r.fl.alt[0]]); }
  else out.push(['pass', 'Carrier', r.fl.al + ' · preferred']);
  /* budget */
  const after = SPENT + COMMITTED.reduce((a, b) => a + b, 0) + committedNow() + (r.status === 'pending' ? c.total : 0);
  out.push(after > BUDGET ? ['fail', 'Budget', 'Takes Q4 to ' + eur(after) + ', over the ' + eur(BUDGET) + ' budget'] : after > BUDGET * .9 ? ['warn', 'Budget', 'Takes Q4 to ' + Math.round(after / BUDGET * 100) + '% of budget'] : ['pass', 'Budget', 'Q4 at ' + Math.round(after / BUDGET * 100) + '% after this']);
  return out;
}
const worst = r => { const c = checks(r); return c.some(x => x[0] === 'fail') ? 'fail' : c.some(x => x[0] === 'warn') ? 'warn' : 'pass'; };

/* ── state ── */
const S = { tab: 'pending', sel: 'r1', q: '', team: null, ghost: true, pane: 'queue', err: '' };
let undo = null;
const I = {
  pass: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m5 12.5 4.2 4.2L19 7"/></svg>',
  warn: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 4 2.8 19.5h18.4z"/><path d="M12 10v4.5M12 17.2v.3"/></svg>',
  fail: '<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.5"/><path d="m8.5 8.5 7 7M15.5 8.5l-7 7"/></svg>',
  plane: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 14.5 21 8l-2.6-1.6a2 2 0 0 0-1.6-.2L5 10.3 3 9.6l1.2 3.4z"/><path d="M5 19h14"/></svg>',
  bed: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 18V7M3 14h18v4M21 14v-2.5a3 3 0 0 0-3-3h-7v5.5"/><circle cx="7" cy="11" r="1.6"/></svg>',
  fork: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M7 3v8M5 3v5a2 2 0 0 0 4 0V3M7 11v10M17 21V3c-2.5 1.5-4 4-4 8h4"/></svg>',
  car: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 16v-4l2-5h12l2 5v4zM4 16v2.5M20 16v2.5"/><circle cx="8" cy="13.5" r="1"/><circle cx="16" cy="13.5" r="1"/></svg>',
  arrow: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 12h15M14 7l5 5-5 5"/></svg>',
  back: '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6"/></svg>'
};
const initials = n => n.split(' ').map(w => w[0]).join('').slice(0, 2);
const hueOf = n => [...n].reduce((a, ch) => a + ch.charCodeAt(0), 0) * 37 % 360;

/* ── queue ── */
function visible() {
  const q = S.q.trim().toLowerCase();
  return REQ.filter(r => {
    if (S.tab === 'pending' && r.status !== 'pending') return false;
    if (S.tab === 'flagged' && (r.status !== 'pending' || worst(r) === 'pass')) return false;
    if (S.tab === 'done' && r.status === 'pending') return false;
    if (S.team && r.team !== S.team) return false;
    if (q && !(r.name + ' ' + r.from + ' ' + r.to + ' ' + r.team + ' ' + r.purpose).toLowerCase().includes(q)) return false;
    return true;
  });
}
function renderTabs() {
  const pend = REQ.filter(r => r.status === 'pending');
  $('[data-tabs]').innerHTML = [['pending', 'Pending', pend.length], ['flagged', 'Flagged', pend.filter(r => worst(r) !== 'pass').length], ['done', 'Decided', REQ.length - pend.length]].map(([k, l, n]) => '<button type="button" role="tab" data-tab="' + k + '" aria-selected="' + (S.tab === k) + '" tabindex="' + (S.tab === k ? 0 : -1) + '">' + l + '<small>' + n + '</small></button>').join('');
  $('[data-navn]').textContent = pend.length || '';
}
function renderList(anim) {
  const list = $('[data-list]'), vis = visible();
  const before = new Map(); $$('[data-k]', list).forEach(n => before.set(n.dataset.k, n.getBoundingClientRect()));
  list.innerHTML = vis.length ? vis.map((r, i) => {
    const c = cost(r), w = worst(r), ck = checks(r);
    const nW = ck.filter(x => x[0] === 'warn').length, nF = ck.filter(x => x[0] === 'fail').length;
    return '<li class="' + P + '-item' + (anim === 'enter' || (anim && !before.has(r.id)) ? ' is-new' : '') + '" data-k="' + r.id + '" style="--i:' + i + '">' +
      '<button type="button" class="' + P + '-row' + (S.sel === r.id ? ' is-sel' : '') + '" data-pick="' + r.id + '" aria-current="' + (S.sel === r.id) + '">' +
      '<span class="' + P + '-av" style="--h:' + hueOf(r.name) + '">' + initials(r.name) + '</span>' +
      '<span class="' + P + '-rm"><b>' + esc(r.name) + '</b><small>' + r.from + ' → ' + r.to + ' · ' + fds(r.dep) + (nights(r) ? '–' + fds(r.ret) : '') + '</small></span>' +
      '<span class="' + P + '-rt"><b>' + eur(c.total) + '</b>' + (r.status === 'pending' ? '<em class="is-' + w + '">' + (w === 'pass' ? I.pass + 'in policy' : (nF ? nF + ' blocking' : nW + (nW > 1 ? ' flags' : ' flag'))) + '</em>' : '<em class="is-' + r.status + '">' + (r.status === 'approved' ? (r.exception ? 'exception' : 'approved') : r.status === 'changes' ? 'changes asked' : 'rejected') + '</em>') + '</span></button></li>';
  }).join('') : '<li class="' + P + '-empty"><b>' + (S.tab === 'pending' && !S.q && !S.team ? 'Inbox zero' : 'Nothing here') + '</b><span>' + (S.q || S.team ? 'Clear the search or team filter.' : S.tab === 'done' ? 'Decisions you make appear here.' : 'Every request has a decision.') + '</span></li>';
  if (anim === 'flip' && !RM.matches) $$('[data-k]', list).forEach(n => { const b = before.get(n.dataset.k); if (!b) return; const dy = b.top - n.getBoundingClientRect().top; if (Math.abs(dy) > 1) n.animate([{ transform: 'translateY(' + dy + 'px)' }, { transform: 'none' }], { duration: 420, easing: 'cubic-bezier(.2,.9,.25,1)' }); });
  const clean = REQ.filter(r => r.status === 'pending' && worst(r) === 'pass');
  $('[data-qf]').innerHTML = '<button type="button" class="' + P + '-btn" data-act="clean"' + (clean.length ? '' : ' disabled title="No in-policy requests waiting"') + '>' + I.pass + 'Approve ' + clean.length + ' in policy</button>' +
    (S.team ? '<button type="button" class="' + P + '-chip" data-team="' + esc(S.team) + '">' + esc(S.team) + ' ×</button>' : '') +
    '<span class="' + P + '-keys"><kbd>J</kbd><kbd>K</kbd> move <kbd>A</kbd> approve <kbd>E</kbd> exception <kbd>R</kbd> reject</span>';
}

/* ── detail ── */
function renderDetail(focusSel) {
  const box = $('[data-detail]'), r = REQ.find(x => x.id === S.sel);
  if (!r) { box.innerHTML = '<div class="' + P + '-none"><b>Nothing selected</b><span>Pick a request from the queue.</span></div>'; return; }
  const c = cost(r), ck = checks(r), w = worst(r), pend = r.status === 'pending';
  const lead = r.dep - TODAY;
  box.innerHTML = '<div class="' + P + '-dwrap" data-key="' + r.id + '">' +
    '<button type="button" class="' + P + '-back" data-go="queue">' + I.back + 'Queue</button>' +
    '<header class="' + P + '-dh"><span class="' + P + '-av is-lg" style="--h:' + hueOf(r.name) + '">' + initials(r.name) + '</span><div><h2>' + esc(r.name) + '</h2><p>' + esc(r.role) + ' · ' + esc(r.team) + ' · ' + TEAMS[r.team] + '</p></div>' +
      '<span class="' + P + '-stat is-' + (pend ? w : r.status) + '">' + (pend ? (w === 'pass' ? 'In policy' : w === 'warn' ? 'Needs a look' : 'Out of policy') : r.status === 'approved' ? (r.exception ? 'Approved with exception' : 'Approved') : r.status === 'changes' ? 'Changes requested' : 'Rejected') + '</span></header>' +
    '<section class="' + P + '-trip"><div class="' + P + '-route"><b>' + r.from + '</b>' + I.arrow + '<b>' + r.to + '</b></div><p>' + fd(r.dep) + (nights(r) ? ' – ' + fd(r.ret) + ' · ' + nights(r) + (nights(r) > 1 ? ' nights' : ' night') : ' · day trip') + ' · departs in ' + lead + ' days</p><p class="' + P + '-purpose">“' + esc(r.purpose) + '” · submitted ' + r.sub + '</p></section>' +
    '<section class="' + P + '-cost" aria-label="Cost"><table><tbody>' +
      '<tr><th>' + I.plane + 'Flight</th><td>' + r.fl.al + ' · ' + r.fl.cls + (r.fl.flex ? ' flexible' : '') + ' · ' + hmin(r.fl.mins) + ' each way</td><td>' + eur(c.fare) + '</td></tr>' +
      (r.ho ? '<tr><th>' + I.bed + 'Hotel</th><td>' + esc(r.ho.name) + ' · ' + c.n + ' × ' + eur(c.rate) + '</td><td>' + eur(c.hotel) + '</td></tr>' : '') +
      '<tr><th>' + I.fork + 'Per diem</th><td>' + c.days + (c.days > 1 ? ' days' : ' day') + ' × ' + eur(c.pdRate) + ' ' + r.to + ' rate</td><td>' + eur(c.per) + '</td></tr>' +
      '<tr><th>' + I.car + 'Ground</th><td>Airport transfers, estimate</td><td>' + eur(c.ground) + '</td></tr>' +
      '</tbody><tfoot><tr><th colspan="2">Total</th><td>' + eur(c.total) + '</td></tr></tfoot></table></section>' +
    '<section class="' + P + '-checks" aria-label="Policy checks"><h3>Policy check <small>' + ck.filter(x => x[0] === 'pass').length + ' of ' + ck.length + ' pass</small></h3><ul>' +
      ck.map((x, i) => '<li class="is-' + x[0] + '" style="--i:' + i + '">' + I[x[0]] + '<b>' + x[1] + '</b><span>' + x[2] + '</span></li>').join('') + '</ul></section>' +
    (pend ? '<section class="' + P + '-act"><label class="' + P + '-note"><span>Note to ' + esc(r.name.split(' ')[0]) + ' <small>required to reject, ask for changes or approve an exception</small></span><textarea data-note rows="1" placeholder="' + (w === 'pass' ? 'Optional' : 'Why this is fine, or what should change') + '"' + (S.err ? ' aria-invalid="true"' : '') + '>' + esc(r.note) + '</textarea><em data-noteerr>' + esc(S.err) + '</em></label>' +
      '<div class="' + P + '-btns">' +
        '<button type="button" class="' + P + '-btn is-good" data-decide="approve"' + (w !== 'pass' ? ' disabled title="Out-of-policy items need an exception note"' : '') + '>' + I.pass + 'Approve</button>' +
        '<button type="button" class="' + P + '-btn is-warn" data-decide="exception"' + (w === 'pass' ? ' disabled title="Nothing to make an exception for"' : '') + '>Allow exception</button>' +
        '<button type="button" class="' + P + '-btn" data-decide="changes">Ask for changes</button>' +
        '<button type="button" class="' + P + '-btn is-bad" data-decide="reject">Reject</button></div></section>'
      : '<section class="' + P + '-decided"><p>' + (r.status === 'approved' ? 'Approved' : r.status === 'changes' ? 'Sent back for changes' : 'Rejected') + ' by Priya Nair just now' + (r.note ? ' — “' + esc(r.note) + '”' : '') + '</p><button type="button" class="' + P + '-btn" data-act="reopen">Undo decision</button></section>') +
    '</div>';
