/* ── budget ── */
function series(includePending) {
  const add = new Array(WEEKS).fill(0), pen = new Array(WEEKS).fill(0);
  REQ.forEach(r => { const w = weekOf(r.dep), t = cost(r).total; if (r.status === 'approved') add[w] += t; else if (r.status === 'pending') pen[w] += t; });
  let a = SPENT, b = SPENT;
  const base = [], ghost = [];
  for (let i = 0; i < WEEKS; i++) { a += COMMITTED[i] + add[i]; b += COMMITTED[i] + add[i] + (includePending ? pen[i] : 0); base.push(a); ghost.push(b); }
  return { base, ghost };
}
function renderBudget() {
  const com = COMMITTED.reduce((x, y) => x + y, 0), appr = committedNow(), pen = pendingNow();
  const used = SPENT + com + appr, left = BUDGET - used;
  $('[data-bleft]').innerHTML = eur(left) + ' <small>left of ' + eur(BUDGET) + '</small>';
  $('[data-bsub]').textContent = Math.round(used / BUDGET * 100) + '% committed · ' + eur(pen) + ' waiting for you' + (used + pen > BUDGET ? ' — more than is left' : '');
  const seg = [['spent', 'Spent', SPENT], ['com', 'Booked', com], ['appr', 'Approved', appr], ['pen', 'Pending', pen]];
  const st = $('[data-stack]');
  if (!st.children.length) st.innerHTML = '<div class="' + P + '-bar">' + seg.map(s => '<i class="is-' + s[0] + '"></i>').join('') + '<b aria-hidden="true"></b></div><ul class="' + P + '-leg">' + seg.map(s => '<li class="is-' + s[0] + '"><span>' + s[1] + '</span><b></b></li>').join('') + '</ul>';
  const total = Math.max(BUDGET, used + pen) * 1.02;
  let x = 0;
  seg.forEach(s => { const el = $('.' + P + '-bar .is-' + s[0], st); el.style.left = (x / total * 100).toFixed(2) + '%'; el.style.width = (s[2] / total * 100).toFixed(2) + '%'; x += s[2]; $('.' + P + '-leg .is-' + s[0] + ' b', st).textContent = eur(s[2]); });
  $('.' + P + '-bar > b', st).style.left = (BUDGET / total * 100).toFixed(2) + '%';
  renderChart();
  /* per team: spent + committed + approved today, with pending as a ghost */
  const teams = Object.keys(TEAMS).map(t => { const ap = REQ.filter(r => r.team === t && r.status === 'approved').reduce((s, r) => s + cost(r).total, 0), pe = REQ.filter(r => r.team === t && r.status === 'pending').reduce((s, r) => s + cost(r).total, 0); return { t, v: TEAM_BASE[t] + ap, pe }; });
  const mx = Math.max(...teams.map(t => t.v + t.pe));
  $('[data-cc]').innerHTML = teams.map(t => '<li><button type="button" class="' + P + '-cc' + (S.team === t.t ? ' is-on' : '') + '" data-team="' + esc(t.t) + '" aria-pressed="' + (S.team === t.t) + '"><span>' + esc(t.t) + '<small>' + TEAMS[t.t] + '</small></span><i style="--a:' + (t.v / mx).toFixed(3) + ';--b:' + ((t.v + t.pe) / mx).toFixed(3) + '"></i><b>' + eur(t.v) + '</b></button></li>').join('');
}
function renderChart() {
  const svg = $('[data-chart]'), { base, ghost } = series(true);
  const X0 = 30, X1 = 292, Y0 = 168, Y1 = 14, top = 56000;
  const x = i => X0 + (X1 - X0) * i / (WEEKS - 1), y = v => Y0 - (Y0 - Y1) * v / top;
  const line = arr => arr.map((v, i) => (i ? 'L' : 'M') + x(i).toFixed(1) + ' ' + y(v).toFixed(1)).join('');
  const area = arr => line(arr) + 'L' + x(WEEKS - 1).toFixed(1) + ' ' + Y0 + 'L' + X0 + ' ' + Y0 + 'Z';
  if (!svg.firstChild) {
    const grid = [0, 12000, 24000, 36000, 48000].map(v => '<line x1="' + X0 + '" x2="' + X1 + '" y1="' + y(v).toFixed(1) + '" y2="' + y(v).toFixed(1) + '" class="' + P + '-gl"/><text x="' + (X0 - 4) + '" y="' + (y(v) + 3).toFixed(1) + '" class="' + P + '-yl">' + (v / 1000) + 'k</text>').join('');
    const xl = [0, 2, 5, 9, 13].map(i => { const d = W0 + i * 7; return '<text x="' + x(i).toFixed(1) + '" y="182" class="' + P + '-xl">' + fds(Math.max(d, D(10, 1))) + '</text>'; }).join('');
    svg.innerHTML = grid + xl +
      '<line class="' + P + '-limit" x1="' + X0 + '" x2="' + X1 + '" y1="' + y(BUDGET).toFixed(1) + '" y2="' + y(BUDGET).toFixed(1) + '"/><text class="' + P + '-bl" x="' + X1 + '" y="' + (y(BUDGET) - 5).toFixed(1) + '">Budget ' + eur(BUDGET) + '</text>' +
      '<path class="' + P + '-ghost" data-ghost/><path class="' + P + '-area" data-area/><path class="' + P + '-line" data-line/>' +
      '<line class="' + P + '-now" x1="' + x(0.3).toFixed(1) + '" x2="' + x(0.3).toFixed(1) + '" y1="' + Y1 + '" y2="' + Y0 + '"/><text class="' + P + '-nl" x="' + (x(0.3) + 3).toFixed(1) + '" y="' + (Y1 + 8) + '">today</text>' +
      '<circle class="' + P + '-end" data-end r="3.5"/><text class="' + P + '-el" data-endl></text>';
  }
  /* paths change through the CSS d property so they morph instead of jumping */
  $('[data-area]', svg).style.d = 'path("' + area(base) + '")';
  $('[data-line]', svg).style.d = 'path("' + line(base) + '")';
  $('[data-ghost]', svg).style.d = 'path("' + line(S.ghost ? ghost : base) + '")';
  svg.classList.toggle('is-ghost', S.ghost);
  const e = $('[data-end]', svg), last = S.ghost ? ghost[WEEKS - 1] : base[WEEKS - 1];
  e.setAttribute('cx', x(WEEKS - 1).toFixed(1)); e.setAttribute('cy', y(last).toFixed(1));
  const el = $('[data-endl]', svg); el.setAttribute('x', (x(WEEKS - 1) - 6).toFixed(1)); el.setAttribute('y', (y(last) + (last > BUDGET * .8 ? 14 : -7)).toFixed(1)); el.textContent = eur(last);
  e.classList.toggle('is-over', last > BUDGET);
}

/* ── actions ── */
function renderAll(anim) { renderTabs(); renderList(anim); renderDetail(); renderBudget(); root.dataset.pane = S.pane; $$('[data-go]').forEach(b => { if (b.getAttribute('role') === 'tab') b.setAttribute('aria-selected', b.dataset.go === S.pane); }); }
let toastT = 0;
function toast(msg) {
  const t = $('[data-toast]');
  t.innerHTML = '<span>' + msg + '</span>';
  t.classList.remove('is-on'); void t.offsetWidth; t.classList.add('is-on');
  clearTimeout(toastT); toastT = setTimeout(() => { if (root.isConnected) t.classList.remove('is-on'); }, 3200);
}
function nextPending(fromId) {
  const vis = REQ.filter(r => r.status === 'pending');
  if (!vis.length) return null;
  const i = REQ.findIndex(r => r.id === fromId);
  return (REQ.slice(i + 1).find(r => r.status === 'pending') || vis[0]).id;
}
function decide(kind) {
  const r = REQ.find(x => x.id === S.sel);
  if (!r || r.status !== 'pending') return;
  const note = ($('[data-note]') && $('[data-note]').value.trim()) || '';
  r.note = note;
  if ((kind === 'reject' || kind === 'changes' || kind === 'exception') && !note) {
    S.err = kind === 'reject' ? 'Tell ' + r.name.split(' ')[0] + ' why it was rejected' : kind === 'changes' ? 'Say what should change' : 'Record why the exception is OK';
    renderDetail('[data-note]'); return;
  }
  if (kind === 'approve' && worst(r) !== 'pass') { toast('This request is out of policy — approve with an exception note'); return; }
  S.err = '';
  undo = { id: r.id };
  r.status = kind === 'reject' ? 'rejected' : kind === 'changes' ? 'changes' : 'approved';
  r.exception = kind === 'exception';
  const c = cost(r).total;
  S.sel = nextPending(r.id) || r.id;
  renderAll('flip');
  toast((r.status === 'approved' ? 'Approved ' : r.status === 'changes' ? 'Sent back ' : 'Rejected ') + esc(r.name) + (r.status === 'approved' ? ' · ' + eur(c) + ' committed' : '') + ' <button type="button" class="' + P + '-tl" data-act="undo">Undo</button>');
}
function reopen(id) { const r = REQ.find(x => x.id === id); if (!r) return; r.status = 'pending'; r.exception = false; S.sel = id; if (S.tab === 'done') S.tab = 'pending'; renderAll('flip'); }

/* ── events ── */
root.addEventListener('click', e => {
  const t = e.target.closest('button');
  if (!t || !root.contains(t)) return;
  const a = t.dataset;
  if (a.pick) { S.sel = a.pick; S.err = ''; renderList(); renderDetail(); if (root.clientWidth < 760) { S.pane = 'detail'; root.dataset.pane = 'detail'; $$('[role="tab"][data-go]').forEach(b => b.setAttribute('aria-selected', b.dataset.go === 'detail')); } const n = $('[data-pick="' + a.pick + '"]'); if (n && root.clientWidth >= 760) n.focus(); return; }
  if (a.tab) { S.tab = a.tab; renderTabs(); renderList('enter'); const n = $('[data-tab="' + a.tab + '"]'); if (n) n.focus(); return; }
  if (a.decide) { decide(a.decide); return; }
  if (a.team) { S.team = S.team === a.team ? null : a.team; renderList('enter'); renderBudget(); toast(S.team ? 'Showing ' + esc(S.team) + ' only' : 'Showing every team'); return; }
  if (a.go) { S.pane = a.go; root.dataset.pane = S.pane; $$('[role="tab"][data-go]').forEach(b => b.setAttribute('aria-selected', b.dataset.go === S.pane)); return; }
  switch (a.act) {
    case 'clean': {
      const ids = REQ.filter(r => r.status === 'pending' && worst(r) === 'pass');
      if (!ids.length) return;
      const sum = ids.reduce((s, r) => s + cost(r).total, 0);
      ids.forEach(r => { r.status = 'approved'; });
      undo = { ids: ids.map(r => r.id) };
      if (ids.some(r => r.id === S.sel)) S.sel = nextPending(S.sel) || S.sel;
      renderAll('flip');
      toast('Approved ' + ids.length + ' in-policy requests · ' + eur(sum) + ' <button type="button" class="' + P + '-tl" data-act="undo">Undo</button>');
      return;
    }
    case 'undo': if (!undo) return; (undo.ids || [undo.id]).forEach(id => { const r = REQ.find(x => x.id === id); if (r) { r.status = 'pending'; r.exception = false; } }); S.sel = undo.id || undo.ids[0]; undo = null; renderAll('flip'); toast('Undone — back in the queue'); return;
    case 'reopen': reopen(S.sel); toast('Decision undone'); return;
    case 'ghost': S.ghost = !S.ghost; t.setAttribute('aria-checked', S.ghost); renderChart(); toast(S.ghost ? 'Dashed line: if every pending request is approved' : 'Showing committed spend only'); return;
  }
});
root.addEventListener('input', e => {
  if (e.target.matches('[data-q]')) { S.q = e.target.value; renderList('enter'); }
  else if (e.target.matches('[data-note]')) { const r = REQ.find(x => x.id === S.sel); if (r) r.note = e.target.value; if (S.err) { S.err = ''; e.target.removeAttribute('aria-invalid'); const em = $('[data-noteerr]'); if (em) em.textContent = ''; } }
});
root.addEventListener('keydown', e => {
  const t = e.target;
  if (t.matches && t.matches('[data-q]') && e.key === 'Escape') { t.value = ''; S.q = ''; renderList('enter'); return; }
  const tabs = t.closest && t.closest('[data-tabs]');
  if (tabs && /^Arrow(Left|Right)$/.test(e.key)) { const bs = $$('[role="tab"]', tabs), i = bs.indexOf(t); e.preventDefault(); bs[(i + (e.key === 'ArrowRight' ? 1 : -1) + bs.length) % bs.length].click(); return; }
  if (/INPUT|TEXTAREA|SELECT/.test(t.tagName) || e.metaKey || e.ctrlKey || e.altKey) return;
